-- BibleArena published database content sync.
-- Generated from buildLocalChallengesForLevel; 5 database-backed games x 30 levels x 5 questions.
-- Preserves UUID primary keys and existing player progress; matches rows by the unique game/level/challenge key.
BEGIN;

INSERT INTO public.game_content (
  question_key, game_slug, level, challenge_index, question_text,
  options, correct_answer, explanation, reference, metadata
) VALUES
('scripture-challenge-l1-c1', 'scripture-challenge', 1, 1, 'Which item did the Lord command Noah to bring into the ark in addition to his family and the animals?', ARRAY['A lampstand', 'A golden altar', 'Food for every kind of creature', 'The tablets of the covenant']::text[], 'Food for every kind of creature', 'Noah was instructed to gather and store food for himself and the animals.', 'Genesis 6:21', '{"challengeType":"mixed-knowledge","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l1-c2', 'scripture-challenge', 1, 2, 'At the dedication of the temple, what filled the house so that the priests could not continue ministering?', ARRAY['The glory of the LORD', 'A great wind from the east', 'The sound of trumpets alone', 'A cloud of incense from the altar']::text[], 'The glory of the LORD', 'The cloud filled the house of the LORD, and the priests could not stand to minister because of it.', '1 Kings 8:10-11', '{"challengeType":"textual-detail","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l1-c3', 'scripture-challenge', 1, 3, 'Which New Testament book records the Bereans examining the Scriptures daily to test what they heard?', ARRAY['Romans', 'Hebrews', 'Acts', 'James']::text[], 'Acts', 'The Bereans received the message eagerly and examined the Scriptures daily to see whether Paul and Silas’ teaching was true.', 'Acts 17:10-12', '{"challengeType":"book-identification","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l1-c4', 'scripture-challenge', 1, 4, 'Which prophet was instructed to marry Gomer as a sign concerning Israel?', ARRAY['Micah', 'Amos', 'Ezekiel', 'Hosea']::text[], 'Hosea', 'The LORD told Hosea to take an unfaithful wife as a prophetic sign concerning the unfaithfulness of the land.', 'Hosea 1:2-3', '{"challengeType":"prophet-identification","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l1-c5', 'scripture-challenge', 1, 5, 'When Jesus asked the disciples who people said He was, which answer did Peter give when Jesus asked, “But who do you say that I am?”', ARRAY['You are the Son of David only', 'You are Elijah who is to come', 'You are the prophet like Moses', 'You are the Christ, the Son of the living God']::text[], 'You are the Christ, the Son of the living God', 'Peter confessed Jesus as the Christ, the Son of the living God.', 'Matthew 16:15-16', '{"challengeType":"final-detail","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l2-c1', 'scripture-challenge', 2, 1, 'I was a left-handed Benjamite. I delivered Israel by striking down Moab’s king in a private audience. Who am I?', ARRAY['Gideon', 'Othniel', 'Ehud', 'Shamgar']::text[], 'Ehud', 'Ehud was a left-handed man from Benjamin who used a concealed sword to kill Eglon, king of Moab.', 'Judges 3:15-22', '{"challengeType":"progressive-clues","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l2-c2', 'scripture-challenge', 2, 2, 'I was a Cushite official in the service of King Zedekiah. I rescued Jeremiah from a muddy cistern. Who am I?', ARRAY['Ebed-melech', 'Gedaliah', 'Baruch', 'Pashhur']::text[], 'Ebed-melech', 'Ebed-melech appealed to the king and used ropes and worn-out clothes to lift Jeremiah from the cistern.', 'Jeremiah 38:7-13', '{"challengeType":"progressive-clues","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l2-c3', 'scripture-challenge', 2, 3, 'I was a craftsman from the tribe of Judah, filled with the Spirit of God for work on the tabernacle. Who am I?', ARRAY['Hur', 'Bezalel', 'Oholiab', 'Ithamar']::text[], 'Bezalel', 'Bezalel son of Uri was appointed and equipped to design and make the tabernacle furnishings.', 'Exodus 31:1-5', '{"challengeType":"progressive-clues","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l2-c4', 'scripture-challenge', 2, 4, 'I was the prophetess consulted when the Book of the Law was found during King Josiah’s reign. Who am I?', ARRAY['Miriam', 'Huldah', 'Noadiah', 'Deborah']::text[], 'Huldah', 'Huldah delivered the LORD’s message to the delegation sent by Josiah.', '2 Kings 22:14-20', '{"challengeType":"progressive-clues","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l2-c5', 'scripture-challenge', 2, 5, 'I was chosen by lot to take the place left vacant by Judas among the apostles. Who am I?', ARRAY['Silas', 'Matthias', 'Joseph Barsabbas', 'Barnabas']::text[], 'Matthias', 'After prayer and the casting of lots, Matthias was numbered with the eleven apostles.', 'Acts 1:23-26', '{"challengeType":"progressive-clues","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l3-c1', 'scripture-challenge', 3, 1, 'Which pair correctly identifies the two men named James who appear among the Twelve: one was the son of Zebedee and the other the son of Alphaeus?', ARRAY['James son of Zebedee and James son of Clopas', 'James son of Zebedee and James son of Alphaeus', 'James the Lord’s brother and James son of Joseph', 'James son of Alphaeus and James son of Cleopas']::text[], 'James son of Zebedee and James son of Alphaeus', 'The lists of the Twelve distinguish James son of Zebedee from James son of Alphaeus.', 'Matthew 10:2-3; Mark 3:17-18', '{"challengeType":"name-disambiguation","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l3-c2', 'scripture-challenge', 3, 2, 'Which statement correctly distinguishes the two kings named Herod in the birth and ministry narratives?', ARRAY['Both names refer to the same ruler', 'Herod Agrippa ruled at Jesus’ birth; Herod the Great ruled during John’s imprisonment', 'Herod Antipas ruled at Jesus’ birth; Herod the Great ruled during the trial', 'Herod the Great ruled at Jesus’ birth; Herod Antipas ruled during much of Jesus’ public ministry']::text[], 'Herod the Great ruled at Jesus’ birth; Herod Antipas ruled during much of Jesus’ public ministry', 'Matthew places Jesus’ birth under Herod the Great; Luke identifies Herod Antipas as tetrarch during Jesus’ ministry.', 'Matthew 2:1; Luke 3:1; Luke 23:7-11', '{"challengeType":"name-disambiguation","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l3-c3', 'scripture-challenge', 3, 3, 'Which Mary was the sister of Martha and Lazarus?', ARRAY['Mary Magdalene', 'Mary the mother of James and Joses', 'Mary the wife of Clopas', 'Mary of Bethany']::text[], 'Mary of Bethany', 'John identifies Mary as the sister of Martha and Lazarus; Luke records her sitting at Jesus’ feet.', 'John 11:1-2; Luke 10:38-39', '{"challengeType":"name-disambiguation","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l3-c4', 'scripture-challenge', 3, 4, 'Which John was the father of the apostle Peter?', ARRAY['John the son of Zebedee', 'John Mark', 'The Bible does not identify Peter’s father as John; it names him Jonah or John in different translations', 'John the Baptist']::text[], 'The Bible does not identify Peter’s father as John; it names him Jonah or John in different translations', 'Matthew 16:17 calls Peter son of Jonah; John 1:42 uses a form rendered John or Jonah depending on translation. Do not confuse him with John the Baptist or the apostle John.', 'Matthew 16:17; John 1:42', '{"challengeType":"name-disambiguation","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l3-c5', 'scripture-challenge', 3, 5, 'Which statement correctly distinguishes Philip the apostle from Philip the evangelist in Acts?', ARRAY['They are explicitly identified as the same person', 'Philip the apostle was the Ethiopian official baptized on the road', 'Philip the evangelist was one of the Twelve; Philip the apostle was one of the Seven', 'Philip the apostle was one of the Twelve; Philip the evangelist was one of the Seven appointed in Jerusalem']::text[], 'Philip the apostle was one of the Twelve; Philip the evangelist was one of the Seven appointed in Jerusalem', 'The apostle Philip appears in the lists of the Twelve; Acts 6 names Philip among the Seven, and Acts 8 describes his evangelistic work.', 'Matthew 10:2-3; Acts 6:5; Acts 8:5-6', '{"challengeType":"name-disambiguation","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l4-c1', 'scripture-challenge', 4, 1, 'Ruth married Boaz after returning to Bethlehem with Naomi. What was Ruth’s relationship to Naomi before that marriage?', ARRAY['Daughter-in-law', 'Niece', 'Sister', 'Cousin']::text[], 'Daughter-in-law', 'Ruth was married to Naomi’s son Mahlon. After Mahlon died, Ruth remained with her mother-in-law Naomi.', 'Ruth 1:3-5; Ruth 4:13', '{"challengeType":"family-relationships","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l4-c2', 'scripture-challenge', 4, 2, 'Jonathan, the close friend of David, was the son of which king?', ARRAY['David', 'Saul', 'Ish-bosheth', 'Solomon']::text[], 'Saul', 'The account lists Jonathan among Saul’s children. Jonathan and David made a covenant of friendship.', '1 Samuel 14:49; 1 Samuel 18:1-3', '{"challengeType":"parent-child-links","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l4-c3', 'scripture-challenge', 4, 3, 'Moses’ father and mother are identified by name in Exodus. Which pair is correct?', ARRAY['Kohath and Miriam', 'Aaron and Elisheba', 'Amram and Jochebed', 'Amram and Miriam']::text[], 'Amram and Jochebed', 'Amram married Jochebed, and she gave birth to Aaron and Moses; the passage also names their sister Miriam elsewhere.', 'Exodus 6:18-20', '{"challengeType":"family-relationships","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l4-c4', 'scripture-challenge', 4, 4, 'Paul mentions Timothy’s sincere faith and names two women in his family. Who were they?', ARRAY['His mother Lois and grandmother Priscilla', 'His mother Eunice and grandmother Lois', 'His mother Priscilla and grandmother Phoebe', 'His mother Lydia and grandmother Eunice']::text[], 'His mother Eunice and grandmother Lois', 'Paul recalls the sincere faith first present in Timothy’s grandmother Lois and his mother Eunice.', '2 Timothy 1:5', '{"challengeType":"family-relationships","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l4-c5', 'scripture-challenge', 4, 5, 'In Mark’s account, which of these men is named as one of Jesus’ brothers?', ARRAY['Zacchaeus', 'Judas', 'Bartimaeus', 'Nicodemus']::text[], 'Judas', 'Mark names James, Joses, Judas and Simon as Jesus’ brothers, and also mentions His sisters.', 'Mark 6:3', '{"challengeType":"sibling-identification","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l5-c1', 'scripture-challenge', 5, 1, 'Three names below are sons of Jacob by birth. Which one was Jacob’s grandson through Joseph?', ARRAY['Levi', 'Ephraim', 'Simeon', 'Reuben']::text[], 'Ephraim', 'Ephraim was a son of Joseph and therefore a grandson of Jacob. Reuben, Simeon and Levi were Jacob’s sons.', 'Genesis 41:50-52; Genesis 46:8-27', '{"challengeType":"odd-one-out-family","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l5-c2', 'scripture-challenge', 5, 2, 'Ephesus, Smyrna and Pergamum are among the seven churches addressed in Revelation. Which place below is NOT one of those seven?', ARRAY['Laodicea', 'Sardis', 'Philadelphia', 'Rome']::text[], 'Rome', 'The seven churches were in Ephesus, Smyrna, Pergamum, Thyatira, Sardis, Philadelphia and Laodicea. Rome is not in that list.', 'Revelation 1:11; Revelation 2:1-3:22', '{"challengeType":"odd-one-out-geography","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l5-c3', 'scripture-challenge', 5, 3, 'The ark of the covenant, the lampstand and the table of the bread of the Presence belonged to Israel’s worship sanctuary. Which item does NOT belong to that group of sanctuary furnishings?', ARRAY['The table of the bread of the Presence', 'The bronze serpent', 'The ark of the covenant', 'The golden lampstand']::text[], 'The bronze serpent', 'The bronze serpent was made during the wilderness journey as instructed in Numbers 21; it was not one of the sanctuary furnishings described in Exodus 25.', 'Exodus 25:10-40; Numbers 21:8-9', '{"challengeType":"odd-one-out-objects","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l5-c4', 'scripture-challenge', 5, 4, 'Deborah, Gideon and Samson are remembered among Israel’s judges. Which person below was a prophet during David’s reign, not one of the judges in the book of Judges?', ARRAY['Othniel', 'Ehud', 'Shamgar', 'Nathan']::text[], 'Nathan', 'Othniel, Ehud and Shamgar are identified as judges or deliverers in Judges. Nathan served as a prophet in David’s court.', 'Judges 3:9-31; 2 Samuel 7:2-5', '{"challengeType":"odd-one-out-people","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l5-c5', 'scripture-challenge', 5, 5, 'Hananiah, Mishael and Azariah were taken to Babylon with Daniel. Which name below is NOT one of Daniel’s three companions?', ARRAY['Mishael', 'Azariah', 'Hananiah', 'Ezra']::text[], 'Ezra', 'Daniel’s three companions were Hananiah, Mishael and Azariah, whose Babylonian names were Shadrach, Meshach and Abednego. Ezra was a different biblical figure.', 'Daniel 1:6-7', '{"challengeType":"odd-one-out-names","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l6-c1', 'scripture-challenge', 6, 1, 'Before the Israelites crossed the Red Sea, what did Pharaoh do when he heard that they had left?', ARRAY['He pursued them with his army and chariots', 'He ordered the Israelites to return to Goshen', 'He sent Moses a message asking for peace', 'He appointed Aaron as a ruler in Egypt']::text[], 'He pursued them with his army and chariots', 'Pharaoh changed his mind and pursued the Israelites with horses, chariots and troops, reaching them while they were camped by the sea.', 'Exodus 14:5-9', '{"challengeType":"event-before","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l6-c2', 'scripture-challenge', 6, 2, 'What happened just before Joseph was brought out of prison to interpret Pharaoh’s dreams?', ARRAY['The famine began throughout Egypt', 'Pharaoh’s chief cupbearer remembered Joseph and told Pharaoh about him', 'Jacob arrived in Egypt with his family', 'Joseph was appointed governor of Egypt']::text[], 'Pharaoh’s chief cupbearer remembered Joseph and told Pharaoh about him', 'After Pharaoh’s birthday, the restored cupbearer remembered Joseph. Pharaoh then sent for Joseph when his dreams troubled him.', 'Genesis 40:20-23; Genesis 41:1-14', '{"challengeType":"event-before","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l6-c3', 'scripture-challenge', 6, 3, 'After Samuel anointed David, which service did David later perform for King Saul before the battle with Goliath?', ARRAY['He played the lyre for Saul when the harmful spirit troubled him', 'He became commander of Saul’s army', 'He built a new altar in Jerusalem', 'He led Israel across the Jordan']::text[], 'He played the lyre for Saul when the harmful spirit troubled him', 'After David was anointed, he was brought to Saul to play the lyre. The account of Goliath’s challenge follows in 1 Samuel 17.', '1 Samuel 16:13-23; 1 Samuel 17:1-3', '{"challengeType":"event-after","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l6-c4', 'scripture-challenge', 6, 4, 'According to Matthew, what happened immediately after Jesus was baptised and came up from the water?', ARRAY['He called Peter and Andrew beside the Sea of Galilee', 'He entered Jerusalem riding a donkey', 'He fed the five thousand', 'The Spirit led Him into the wilderness to be tempted']::text[], 'The Spirit led Him into the wilderness to be tempted', 'After Jesus’ baptism and the heavenly declaration, the Spirit led Him into the wilderness, where He fasted and was tempted.', 'Matthew 3:13-17; Matthew 4:1-2', '{"challengeType":"event-after","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l6-c5', 'scripture-challenge', 6, 5, 'After Jesus and the disciples finished the Last Supper, what did they do before reaching the place where Jesus was arrested?', ARRAY['They travelled to Bethany to meet Lazarus', 'They sailed across the Sea of Galilee', 'They sang a hymn and went out to the Mount of Olives', 'They returned to the temple courts']::text[], 'They sang a hymn and went out to the Mount of Olives', 'Mark records that they sang a hymn and went out to the Mount of Olives. They then went to Gethsemane, where Jesus was arrested.', 'Mark 14:22-26; Mark 14:32-43', '{"challengeType":"event-sequence","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l7-c1', 'scripture-challenge', 7, 1, 'When Abraham’s servant was sent to find a wife for Isaac, what sign did he ask God to give at the well?', ARRAY['She would arrive carrying a basket of figs', 'She would identify herself as Abraham’s niece', 'She would draw water before sunset without speaking', 'The woman would offer him a drink and also water his camels']::text[], 'The woman would offer him a drink and also water his camels', 'The servant asked that the chosen woman offer him a drink and volunteer to draw water for his camels too. Rebekah did exactly this.', 'Genesis 24:12-20', '{"challengeType":"covenant-clue","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l7-c2', 'scripture-challenge', 7, 2, 'Which son of Isaac was born holding his twin brother’s heel?', ARRAY['Benjamin', 'Jacob', 'Joseph', 'Esau']::text[], 'Jacob', 'Jacob was born after Esau, with his hand holding Esau’s heel; this detail is connected with his name in the account.', 'Genesis 25:24-26', '{"challengeType":"birth-record","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l7-c3', 'scripture-challenge', 7, 3, 'What did Jacob place under his head when he slept at Bethel and dreamed of a stairway reaching to heaven?', ARRAY['A bundle of reeds', 'His cloak', 'A stone', 'A wooden staff']::text[], 'A stone', 'Jacob took one of the stones of the place, used it as a pillow, and later set it up as a pillar.', 'Genesis 28:10-19', '{"challengeType":"detail-recall","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l7-c4', 'scripture-challenge', 7, 4, 'Which son of Jacob received a special robe from his father, provoking jealousy among his brothers?', ARRAY['Joseph', 'Reuben', 'Benjamin', 'Judah']::text[], 'Joseph', 'Israel loved Joseph more than his other sons because Joseph was the son of his old age, and he made him a distinctive robe.', 'Genesis 37:3-4', '{"challengeType":"family-evidence","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l7-c5', 'scripture-challenge', 7, 5, 'When Joseph tested his brothers in Egypt, whose sack was found to contain Joseph’s silver cup?', ARRAY['Judah’s', 'Reuben’s', 'Benjamin’s', 'Simeon’s']::text[], 'Benjamin’s', 'Joseph ordered his cup placed in Benjamin’s sack. The steward found it there when the brothers were searched.', 'Genesis 44:1-12', '{"challengeType":"patriarch-case-file","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l8-c1', 'scripture-challenge', 8, 1, 'In Pharaoh’s first dream interpreted by Joseph, what came up out of the Nile before the seven thin cows?', ARRAY['Seven healthy, well-fed cows', 'Seven large locusts', 'Seven ears of blighted grain', 'Seven white horses']::text[], 'Seven healthy, well-fed cows', 'The first dream featured seven beautiful, fat cows coming up from the Nile, followed by seven ugly, thin cows.', 'Genesis 41:1-4', '{"challengeType":"dream-decoding","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l8-c2', 'scripture-challenge', 8, 2, 'What Egyptian name did Pharaoh give Joseph when he appointed him over the land of Egypt?', ARRAY['Zaphenath-paneah', 'Belteshazzar', 'Abednego', 'Sheshbazzar']::text[], 'Zaphenath-paneah', 'Pharaoh gave Joseph the name Zaphenath-paneah and gave him Asenath as a wife.', 'Genesis 41:39-45', '{"challengeType":"name-and-title","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l8-c3', 'scripture-challenge', 8, 3, 'During the first meeting in Egypt, which brother did Joseph keep in custody while the others returned to Canaan?', ARRAY['Reuben', 'Simeon', 'Benjamin', 'Judah']::text[], 'Simeon', 'Joseph held Simeon before the brothers returned home, requiring them to bring Benjamin on their next visit.', 'Genesis 42:18-24', '{"challengeType":"sequence-investigation","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l8-c4', 'scripture-challenge', 8, 4, 'When Moses first asked Pharaoh to let Israel go, what additional demand did Pharaoh impose on the Hebrew slaves?', ARRAY['They had to surrender their livestock immediately', 'They had to build a new city without tools', 'They had to gather their own straw while maintaining the same brick quota', 'They had to work only at night']::text[], 'They had to gather their own straw while maintaining the same brick quota', 'Pharaoh ordered the taskmasters to stop supplying straw but demanded the same number of bricks each day.', 'Exodus 5:6-14', '{"challengeType":"exodus-policy","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l8-c5', 'scripture-challenge', 8, 5, 'At the first Passover, where were the Israelites instructed to put the blood of the lamb?', ARRAY['On the altar in Pharaoh’s palace', 'On the threshold and the roof', 'On the two doorposts and the lintel of the house', 'On the handles of their kneading bowls']::text[], 'On the two doorposts and the lintel of the house', 'The blood was to be put on the two doorposts and the lintel of each house; it would be a sign for the households.', 'Exodus 12:5-7, 12-13', '{"challengeType":"passover-detail","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l9-c1', 'scripture-challenge', 9, 1, 'When the Israelites first complained of hunger in the wilderness of Sin, what food did God promise to provide in the evening?', ARRAY['Quail', 'Fish', 'Locusts', 'Dates']::text[], 'Quail', 'The LORD promised bread in the morning and meat in the evening; quail came and covered the camp at evening.', 'Exodus 16:11-13', '{"challengeType":"wilderness-provision","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l9-c2', 'scripture-challenge', 9, 2, 'What name did the Israelites give the bread-like substance that appeared with the morning dew?', ARRAY['Manna', 'Ephah', 'Nehushtan', 'Mazzaroth']::text[], 'Manna', 'The Israelites called it manna. Exodus describes it as white like coriander seed and tasting like wafers made with honey.', 'Exodus 16:13-15, 31', '{"challengeType":"wilderness-provision","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l9-c3', 'scripture-challenge', 9, 3, 'At Rephidim, what did Moses strike with his staff so that water came out for the people?', ARRAY['The waters of Marah', 'The bronze altar', 'The pillar of cloud', 'The rock at Horeb']::text[], 'The rock at Horeb', 'At the LORD’s command, Moses struck the rock at Horeb, and water came out for the people to drink.', 'Exodus 17:1-7', '{"challengeType":"location-and-action","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l9-c4', 'scripture-challenge', 9, 4, 'How many spies did Moses send to explore Canaan, one from each tribe?', ARRAY['Fourteen', 'Seven', 'Ten', 'Twelve']::text[], 'Twelve', 'Moses sent twelve men, one leader from each ancestral tribe, to explore the land of Canaan.', 'Numbers 13:1-3, 17-20', '{"challengeType":"number-check","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l9-c5', 'scripture-challenge', 9, 5, 'Which two spies urged Israel to trust God and enter the land, despite the people’s fear?', ARRAY['Korah and Dathan', 'Joshua and Caleb', 'Moses and Aaron', 'Eleazar and Phinehas']::text[], 'Joshua and Caleb', 'Joshua son of Nun and Caleb son of Jephunneh urged the people not to rebel or fear the inhabitants because the LORD was with them.', 'Numbers 14:5-9, 30-38', '{"challengeType":"wilderness-verdict","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l10-c1', 'scripture-challenge', 10, 1, 'When Abraham pleaded for Sodom, what was the smallest number of righteous people for whose sake he asked God to spare the city?', ARRAY['Seven', 'Twelve', 'Ten', 'Five']::text[], 'Ten', 'Abraham’s final request was that the city be spared if ten righteous people were found there.', 'Genesis 18:27-33', '{"challengeType":"boss-countdown","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l10-c2', 'scripture-challenge', 10, 2, 'After Sarah died, in which field and cave did Abraham bury her?', ARRAY['The field of Machpelah, near Mamre', 'The cave of Adullam, near Bethlehem', 'The field of Ephron, near Bethel', 'The field of Shechem, beside the oak']::text[], 'The field of Machpelah, near Mamre', 'Abraham purchased the field of Ephron at Machpelah, near Mamre, and buried Sarah there.', 'Genesis 23:17-20', '{"challengeType":"patriarch-location","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l10-c3', 'scripture-challenge', 10, 3, 'Which name did God give Jacob after he wrestled through the night at Peniel?', ARRAY['Jeshurun', 'Israel', 'Bethel', 'Edom']::text[], 'Israel', 'Jacob was told that his name would no longer be Jacob but Israel, because he had struggled with God and with men.', 'Genesis 32:24-30', '{"challengeType":"identity-turning-point","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l10-c4', 'scripture-challenge', 10, 4, 'When Jacob blessed Joseph’s sons, which younger grandson did he deliberately place his right hand upon?', ARRAY['Manasseh', 'Ephraim', 'Benjamin', 'Asher']::text[], 'Ephraim', 'Jacob crossed his hands and placed his right hand on Ephraim, the younger son, despite Joseph’s objection.', 'Genesis 48:13-20', '{"challengeType":"crossed-hands","curated":true,"difficulty":"medium"}'::jsonb),
('scripture-challenge-l10-c5', 'scripture-challenge', 10, 5, 'Which brother proposed selling Joseph to the traders rather than leaving him to die in the pit?', ARRAY['Levi', 'Reuben', 'Simeon', 'Judah']::text[], 'Judah', 'Reuben intended to rescue Joseph, but Judah proposed selling him; the brothers then sold Joseph to passing traders.', 'Genesis 37:21-28', '{"challengeType":"motive-and-action","curated":true,"difficulty":"medium"}'::jsonb)
ON CONFLICT (game_slug, level, challenge_index) DO UPDATE SET
  question_key = EXCLUDED.question_key,
  question_text = EXCLUDED.question_text,
  options = EXCLUDED.options,
  correct_answer = EXCLUDED.correct_answer,
  explanation = EXCLUDED.explanation,
  reference = EXCLUDED.reference,
  metadata = EXCLUDED.metadata;

INSERT INTO public.game_content (
  question_key, game_slug, level, challenge_index, question_text,
  options, correct_answer, explanation, reference, metadata
) VALUES
('scripture-challenge-l11-c1', 'scripture-challenge', 11, 1, 'Which judge made a vow that led to a tragic encounter involving his daughter after returning from battle?', ARRAY['Samson', 'Gideon', 'Barak', 'Jephthah']::text[], 'Jephthah', 'Jephthah made a vow before fighting the Ammonites. His daughter came out to meet him when he returned.', 'Judges 11:29-40', '{"challengeType":"vow-and-consequence","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l11-c2', 'scripture-challenge', 11, 2, 'Which judge used an oxgoad to strike down six hundred Philistines?', ARRAY['Shamgar', 'Othniel', 'Ehud', 'Samson']::text[], 'Shamgar', 'Shamgar son of Anath struck down six hundred Philistines with an oxgoad and also delivered Israel.', 'Judges 3:31', '{"challengeType":"weapon-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l11-c3', 'scripture-challenge', 11, 3, 'In Deborah’s song, which woman received the honour of defeating Sisera after he fled from the battle?', ARRAY['Jael', 'Achsa', 'Deborah', 'Delilah']::text[], 'Jael', 'Jael invited Sisera into her tent and killed him with a tent peg while he slept.', 'Judges 4:17-22; Judges 5:24-27', '{"challengeType":"victory-investigation","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l11-c4', 'scripture-challenge', 11, 4, 'What sign did Gideon ask for when he placed a fleece on the threshing floor the first time?', ARRAY['Rain falling only on the fleece', 'The fleece changing colour at sunrise', 'Dew on the fleece while the ground around it remained dry', 'Fire consuming the fleece while the ground stayed wet']::text[], 'Dew on the fleece while the ground around it remained dry', 'Gideon asked that the fleece alone be covered with dew while the ground remained dry; God granted the sign.', 'Judges 6:36-38', '{"challengeType":"sign-and-symbol","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l11-c5', 'scripture-challenge', 11, 5, 'Which judge was known for having thirty sons who rode thirty donkeys and controlled thirty towns?', ARRAY['Tola', 'Abdon', 'Jair', 'Ibzan']::text[], 'Jair', 'Jair the Gileadite judged Israel for twenty-two years. His thirty sons rode thirty donkeys and had thirty towns called Havvoth-jair.', 'Judges 10:3-5', '{"challengeType":"detail-under-pressure","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l12-c1', 'scripture-challenge', 12, 1, 'Who was the first king anointed by Samuel over Israel?', ARRAY['Ish-bosheth', 'Saul', 'David', 'Solomon']::text[], 'Saul', 'Samuel anointed Saul as ruler over the LORD’s inheritance, and the people later confirmed his kingship at Gilgal.', '1 Samuel 10:1; 1 Samuel 11:14-15', '{"challengeType":"royal-beginnings","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l12-c2', 'scripture-challenge', 12, 2, 'Which king asked God for wisdom to govern the people after God invited him to ask for something at Gibeon?', ARRAY['Solomon', 'Hezekiah', 'David', 'Josiah']::text[], 'Solomon', 'Solomon asked for a discerning heart to govern God’s people and distinguish between right and wrong.', '1 Kings 3:4-12', '{"challengeType":"royal-request","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l12-c3', 'scripture-challenge', 12, 3, 'After Solomon’s death, which son became king in Jerusalem while the northern tribes rejected his rule?', ARRAY['Jeroboam', 'Abijah', 'Asa', 'Rehoboam']::text[], 'Rehoboam', 'Rehoboam succeeded Solomon. The northern tribes rejected his rule after he refused the elders’ counsel and answered harshly.', '1 Kings 11:43; 1 Kings 12:1-20', '{"challengeType":"kingdom-division","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l12-c4', 'scripture-challenge', 12, 4, 'Which king of Israel built golden calves and placed one at Bethel and the other at Dan?', ARRAY['Jehu son of Jehoshaphat', 'Baasha son of Ahijah', 'Jeroboam son of Nebat', 'Ahab son of Omri']::text[], 'Jeroboam son of Nebat', 'Jeroboam feared that worship in Jerusalem would draw the people back to the house of David, so he set up two golden calves.', '1 Kings 12:26-30', '{"challengeType":"idolatry-record","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l12-c5', 'scripture-challenge', 12, 5, 'Which king of Judah found the Book of the Law during repairs to the temple and led a major covenant renewal?', ARRAY['Uzziah', 'Hezekiah', 'Josiah', 'Manasseh']::text[], 'Josiah', 'During Josiah’s reign, Hilkiah the high priest found the Book of the Law. Josiah gathered the people and renewed the covenant.', '2 Kings 22:3-13; 2 Kings 23:1-3', '{"challengeType":"reform-and-discovery","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l13-c1', 'scripture-challenge', 13, 1, 'After King Ahaziah of Judah died, which woman seized power and attempted to destroy the royal family?', ARRAY['Athaliah’s daughter Jehosheba', 'Jezebel', 'Maacah', 'Athaliah']::text[], 'Athaliah', 'Athaliah destroyed the royal offspring, but Jehosheba hid the young Joash and his nurse in the temple for six years.', '2 Kings 11:1-3', '{"challengeType":"royal-lineage","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l13-c2', 'scripture-challenge', 13, 2, 'Which priest helped preserve the royal line by hiding Joash and later presenting him as king?', ARRAY['Hilkiah', 'Jehoiada', 'Abiathar', 'Zadok']::text[], 'Jehoiada', 'Jehoiada gathered the commanders, arranged protection for Joash, and brought the king’s son out to be crowned.', '2 Kings 11:4-12', '{"challengeType":"hidden-heir","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l13-c3', 'scripture-challenge', 13, 3, 'Which king of Judah was struck with leprosy after unlawfully entering the temple to burn incense?', ARRAY['Hezekiah', 'Uzziah', 'Jotham', 'Ahaz']::text[], 'Uzziah', 'Uzziah became proud and entered the temple to burn incense. Azariah the priest confronted him, and leprosy broke out on his forehead.', '2 Chronicles 26:16-21', '{"challengeType":"royal-consequence","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l13-c4', 'scripture-challenge', 13, 4, 'Which king of Judah was taken captive to Babylon after reigning for only three months?', ARRAY['Jehoiachin', 'Manasseh', 'Jehoiakim', 'Zedekiah']::text[], 'Jehoiachin', 'Jehoiachin was eighteen when he became king and reigned three months in Jerusalem before surrendering to Nebuchadnezzar.', '2 Kings 24:8-15', '{"challengeType":"succession-record","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l13-c5', 'scripture-challenge', 13, 5, 'Which Persian king issued the decree allowing the Jewish exiles to return and rebuild the temple in Jerusalem?', ARRAY['Darius the Mede', 'Ahasuerus', 'Artaxerxes', 'Cyrus']::text[], 'Cyrus', 'In the first year of Cyrus king of Persia, the LORD stirred his spirit to issue a proclamation concerning the temple in Jerusalem.', 'Ezra 1:1-4; 2 Chronicles 36:22-23', '{"challengeType":"restoration-decree","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l14-c1', 'scripture-challenge', 14, 1, 'Which commander killed Abner after Abner had made peace with David?', ARRAY['Joab', 'Benaiah', 'Abishai', 'Asahel']::text[], 'Joab', 'Joab took Abner aside at the gate and struck him in the stomach, avenging the death of his brother Asahel.', '2 Samuel 3:26-30', '{"challengeType":"betrayal-investigation","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l14-c2', 'scripture-challenge', 14, 2, 'During the battle against the Philistines in the Valley of Rephaim, what did David do before attacking after hearing the sound of marching in the tops of the trees?', ARRAY['He attacked immediately without waiting', 'He waited for the LORD’s signal, then struck when the signal came', 'He sent Joab to negotiate a treaty', 'He withdrew his army to Hebron']::text[], 'He waited for the LORD’s signal, then struck when the signal came', 'David asked God again. He was told not to go straight up, but to circle behind the Philistines and attack when he heard the sound in the trees.', '2 Samuel 5:22-25', '{"challengeType":"battle-strategy","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l14-c3', 'scripture-challenge', 14, 3, 'Who betrayed Samson by repeatedly pressing him to reveal the secret of his strength?', ARRAY['Delilah', 'Michal', 'Jael', 'Athaliah']::text[], 'Delilah', 'Delilah persistently questioned Samson and eventually arranged for his hair to be shaved while he slept.', 'Judges 16:4-21', '{"challengeType":"betrayal-and-motive","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l14-c4', 'scripture-challenge', 14, 4, 'Which young man killed Absalom despite David’s command to deal gently with him?', ARRAY['Zadok', 'Joab', 'Ahimaaz', 'Ittai']::text[], 'Joab', 'Joab found Absalom hanging in a tree and thrust three javelins into him, despite David’s instruction to spare him.', '2 Samuel 18:5, 9-15', '{"challengeType":"command-versus-action","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l14-c5', 'scripture-challenge', 14, 5, 'When the Arameans surrounded Dothan to capture Elisha, what did Elisha pray for his servant?', ARRAY['That the enemy army would fall asleep', 'That the servant would become invisible', 'That the LORD would open his eyes to see the mountain full of horses and chariots of fire', 'That the city walls would collapse']::text[], 'That the LORD would open his eyes to see the mountain full of horses and chariots of fire', 'The LORD opened the servant’s eyes, and he saw the mountain full of horses and chariots of fire around Elisha.', '2 Kings 6:14-17', '{"challengeType":"unseen-army","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l15-c1', 'scripture-challenge', 15, 1, 'Which king of Judah destroyed the bronze serpent Moses had made because the people were burning incense to it?', ARRAY['Asa', 'Josiah', 'Jehoshaphat', 'Hezekiah']::text[], 'Hezekiah', 'Hezekiah removed the high places and broke the bronze serpent into pieces because the Israelites had begun to burn incense to it.', '2 Kings 18:1-4', '{"challengeType":"reform-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l15-c2', 'scripture-challenge', 15, 2, 'Which king of Israel was assassinated by Zimri while drinking himself drunk in the house of Arza?', ARRAY['Nadab son of Jeroboam', 'Pekahiah son of Menahem', 'Ahab son of Omri', 'Elah son of Baasha']::text[], 'Elah son of Baasha', 'Zimri, a commander over half the chariots, entered the house of Arza and killed Elah, who was drunk.', '1 Kings 16:8-10', '{"challengeType":"royal-downfall","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l15-c3', 'scripture-challenge', 15, 3, 'Which king of Judah received a sign involving the shadow moving backward on the steps of Ahaz?', ARRAY['Hezekiah', 'Uzziah', 'Manasseh', 'Josiah']::text[], 'Hezekiah', 'As a sign that the LORD would heal him, the shadow went back ten steps on the stairway of Ahaz.', '2 Kings 20:8-11; Isaiah 38:7-8', '{"challengeType":"sign-verification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l15-c4', 'scripture-challenge', 15, 4, 'Which king of Israel was rebuked by the prophet Jehu son of Hanani for helping the wicked King Ahab?', ARRAY['Jeroboam son of Nebat', 'Jehoshaphat', 'Jehu son of Nimshi', 'Joash']::text[], 'Jehoshaphat', 'Jehu the seer confronted Jehoshaphat after he returned safely from helping Ahab, asking whether he should help the wicked and love those who hate the LORD.', '2 Chronicles 19:1-3', '{"challengeType":"prophetic-rebuke","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l15-c5', 'scripture-challenge', 15, 5, 'Which Babylonian king later released Jehoiachin from prison and gave him a place of honour at his table?', ARRAY['Belshazzar', 'Nebuchadnezzar', 'Evil-merodach', 'Nabonidus']::text[], 'Evil-merodach', 'In the year Evil-merodach became king, he released Jehoiachin, spoke kindly to him, and gave him a regular allowance.', '2 Kings 25:27-30; Jeremiah 52:31-34', '{"challengeType":"exile-record","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l16-c1', 'scripture-challenge', 16, 1, 'Which prophet confronted King David with a story about a rich man who took a poor man’s only lamb?', ARRAY['Gad', 'Micaiah', 'Nathan', 'Ahijah']::text[], 'Nathan', 'Nathan told David the parable of the ewe lamb, then declared, “You are the man!”', '2 Samuel 12:1-7', '{"challengeType":"prophet-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l16-c2', 'scripture-challenge', 16, 2, 'Which prophet was told to buy a linen belt, hide it by the Euphrates, and later retrieve it ruined?', ARRAY['Ezekiel', 'Hosea', 'Zechariah', 'Jeremiah']::text[], 'Jeremiah', 'The ruined belt was a sign that Judah and Jerusalem had become useless through pride and refusal to listen to the LORD.', 'Jeremiah 13:1-11', '{"challengeType":"symbolic-prophetic-act","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l16-c3', 'scripture-challenge', 16, 3, 'Which prophet saw a basket of summer fruit in a vision, a sign that the end had come for Israel?', ARRAY['Habakkuk', 'Joel', 'Amos', 'Micah']::text[], 'Amos', 'The vision of summer fruit announced that the time was ripe for judgment; the Hebrew wordplay links the fruit with the end.', 'Amos 8:1-3', '{"challengeType":"vision-recognition","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l16-c4', 'scripture-challenge', 16, 4, 'Which prophet was shown a flying scroll and a woman sitting inside an ephah in a series of visions?', ARRAY['Zechariah', 'Malachi', 'Obadiah', 'Haggai']::text[], 'Zechariah', 'Zechariah 5 records both the flying scroll and the woman in the measuring basket called an ephah.', 'Zechariah 5:1-11', '{"challengeType":"vision-recognition","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l16-c5', 'scripture-challenge', 16, 5, 'Which prophet challenged the prophets of Baal on Mount Carmel and prayed for fire to fall on the offering?', ARRAY['Isaiah', 'Samuel', 'Elijah', 'Elisha']::text[], 'Elijah', 'Elijah repaired the LORD’s altar, prepared the offering, and called on the LORD; fire consumed the sacrifice, wood, stones and water.', '1 Kings 18:17-39', '{"challengeType":"prophetic-confrontation","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l17-c1', 'scripture-challenge', 17, 1, 'According to Micah, what three things does the LORD require of people?', ARRAY['To pray at sunrise, avoid cities, and make pilgrimages', 'To act justly, love mercy, and walk humbly with God', 'To keep the festivals, conquer nations, and give silver', 'To offer a thousand rams, build an altar, and fast weekly']::text[], 'To act justly, love mercy, and walk humbly with God', 'Micah answers that the LORD requires justice, mercy, and humble fellowship with God rather than empty religious display.', 'Micah 6:6-8', '{"challengeType":"message-decoding","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l17-c2', 'scripture-challenge', 17, 2, 'Which prophet declared that the LORD desired mercy and knowledge of God rather than sacrifice?', ARRAY['Hosea', 'Amos', 'Zephaniah', 'Nahum']::text[], 'Hosea', 'Hosea records the LORD’s words: He desires steadfast love rather than sacrifice, and knowledge of God rather than burnt offerings.', 'Hosea 6:6', '{"challengeType":"central-message","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l17-c3', 'scripture-challenge', 17, 3, 'In Jeremiah’s temple sermon, what warning did the prophet give the people not to trust?', ARRAY['The warning that Egypt would refuse to help Judah', 'The promise that Babylon would attack Jerusalem', 'The command to rebuild the city walls', 'The repeated claim that the temple of the LORD would guarantee their safety']::text[], 'The repeated claim that the temple of the LORD would guarantee their safety', 'Jeremiah warned that repeating “the temple of the LORD” would not protect people who oppressed others and worshipped other gods.', 'Jeremiah 7:1-11', '{"challengeType":"warning-and-context","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l17-c4', 'scripture-challenge', 17, 4, 'What did Haggai challenge the returned exiles for doing while the LORD’s house remained in ruins?', ARRAY['Planting vineyards outside Jerusalem', 'Refusing to observe the Sabbath year', 'Building a palace for the Persian king', 'Living in their own panelled houses while neglecting the temple']::text[], 'Living in their own panelled houses while neglecting the temple', 'The people said the time had not come to rebuild the temple, while they lived in finished houses; Haggai called them to consider their ways.', 'Haggai 1:2-9', '{"challengeType":"historical-message","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l17-c5', 'scripture-challenge', 17, 5, 'Which prophet announced that the ruler of Israel would come from Bethlehem, whose origins are from ancient days?', ARRAY['Malachi', 'Micah', 'Jeremiah', 'Isaiah']::text[], 'Micah', 'Micah foretold a ruler for Israel coming from Bethlehem Ephrathah, a passage later associated with the Messiah’s birthplace.', 'Micah 5:2', '{"challengeType":"messianic-prophecy","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l18-c1', 'scripture-challenge', 18, 1, 'In the account of Elisha and the borrowed axe, what happened to the iron axe head after it fell into the water?', ARRAY['It turned into wood', 'It was carried downstream and recovered in a net', 'It floated to the surface', 'It remained at the bottom until the river dried up']::text[], 'It floated to the surface', 'Elisha cut a stick and threw it into the water; the iron axe head floated, and the man was able to pick it up.', '2 Kings 6:1-7', '{"challengeType":"unexpected-miracle","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l18-c2', 'scripture-challenge', 18, 2, 'Which animal spoke to Balaam after the angel of the LORD blocked the road?', ARRAY['A donkey', 'A camel', 'A horse', 'A sheep']::text[], 'A donkey', 'The LORD opened the donkey’s mouth, and it questioned Balaam after seeing the angel standing in the road.', 'Numbers 22:21-35', '{"challengeType":"unexpected-speaker","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l18-c3', 'scripture-challenge', 18, 3, 'After a man died and his body touched Elisha’s bones, what happened?', ARRAY['The man came back to life and stood on his feet', 'The man became a prophet', 'The man was healed but remained asleep', 'The man’s body disappeared']::text[], 'The man came back to life and stood on his feet', 'When the dead man touched Elisha’s bones, he revived and stood up. The event occurred when a burial party saw a raiding band.', '2 Kings 13:20-21', '{"challengeType":"unusual-resurrection","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l18-c4', 'scripture-challenge', 18, 4, 'In Ezekiel’s symbolic action, what was he first instructed to use as fuel when baking bread during the siege sign?', ARRAY['Dried palm leaves', 'Animal bones', 'Olive wood', 'Human excrement']::text[], 'Human excrement', 'Ezekiel was told to bake bread over human excrement as a sign of the defilement Israel would experience. After he objected, God permitted cow dung instead.', 'Ezekiel 4:9-15', '{"challengeType":"symbolic-action-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l18-c5', 'scripture-challenge', 18, 5, 'Which prophet was instructed to lie on his side for a symbolic number of days to represent the years of Israel’s and Judah’s guilt?', ARRAY['Jeremiah', 'Ezekiel', 'Hosea', 'Daniel']::text[], 'Ezekiel', 'Ezekiel was told to lie on his left side for 390 days for Israel and on his right side for 40 days for Judah.', 'Ezekiel 4:4-8', '{"challengeType":"symbolic-duration","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l19-c1', 'scripture-challenge', 19, 1, 'When Gideon reduced his army, what action did the 300 men who were kept perform at the water?', ARRAY['They lapped water with their hands to their mouths', 'They filled leather jars and poured the water out', 'They drank directly from the river while kneeling', 'They crossed the river without drinking']::text[], 'They lapped water with their hands to their mouths', 'The LORD told Gideon to separate the men by how they drank. Three hundred lapped water with their hands; the rest knelt to drink.', 'Judges 7:4–7', '{"challengeType":"detail-check","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l19-c2', 'scripture-challenge', 19, 2, 'When Abigail hurried to meet David, which item was part of the food she brought?', ARRAY['A basket of figs and dates only', 'A young goat prepared with herbs', 'Two skins of wine', 'Three jars of olive oil']::text[], 'Two skins of wine', 'Abigail gathered bread, wine, prepared sheep, roasted grain, raisins and fig cakes before meeting David.', '1 Samuel 25:18', '{"challengeType":"inventory-recall","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l19-c3', 'scripture-challenge', 19, 3, 'During Nehemiah’s first inspection of Jerusalem’s walls, what did he use to make the journey at night?', ARRAY['An animal to ride', 'A chariot with two horses', 'A ladder carried by guards', 'A boat along the city wall']::text[], 'An animal to ride', 'Nehemiah went out at night with a few men and an animal he was riding; he inspected the damaged walls and gates.', 'Nehemiah 2:11–16', '{"challengeType":"scene-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l19-c4', 'scripture-challenge', 19, 4, 'Who first alerted Paul to the plot by more than forty men to kill him?', ARRAY['The high priest’s youngest son', 'Paul’s sister’s son', 'The Roman commander’s personal servant', 'A temple guard who changed sides']::text[], 'Paul’s sister’s son', 'Paul’s nephew heard about the ambush, went into the barracks and informed Paul, who then sent him to the commander.', 'Acts 23:12–22', '{"challengeType":"identity-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l19-c5', 'scripture-challenge', 19, 5, 'In Troas, where was Eutychus sitting when he fell asleep during Paul’s long message?', ARRAY['A window', 'At the foot of the stairs', 'On the roof terrace', 'Beside the doorway']::text[], 'A window', 'Eutychus was sitting in a window on the third story. He fell asleep and fell down while Paul was speaking.', 'Acts 20:7–12', '{"challengeType":"scene-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l20-c1', 'scripture-challenge', 20, 1, 'Which prophet told King Ahab that he would see Israel scattered like sheep without a shepherd?', ARRAY['Jehu son of Hanani', 'Shemaiah the prophet', 'Elijah the Tishbite', 'Micaiah son of Imlah']::text[], 'Micaiah son of Imlah', 'Micaiah contradicted the reassuring message of the other prophets and described Israel scattered on the hills.', '1 Kings 22:13–17', '{"challengeType":"prophet-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l20-c2', 'scripture-challenge', 20, 2, 'Which prophet used a symbolic act involving a yoke to warn surrounding nations about Babylon’s rule?', ARRAY['Habakkuk', 'Ezekiel', 'Jeremiah', 'Hosea']::text[], 'Jeremiah', 'Jeremiah was instructed to make and wear a yoke and send a message that the nations should submit to Nebuchadnezzar.', 'Jeremiah 27:1–11', '{"challengeType":"prophetic-symbol","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l20-c3', 'scripture-challenge', 20, 3, 'For how long was Isaiah instructed to walk stripped and barefoot as a sign concerning Egypt and Cush?', ARRAY['Forty days', 'Three years', 'One year', 'Seven days']::text[], 'Three years', 'Isaiah’s unusual sign-act lasted three years and pointed to the humiliation of Egypt and Cush.', 'Isaiah 20:1–4', '{"challengeType":"number-trap","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l20-c4', 'scripture-challenge', 20, 4, 'When a deadly substance was discovered in the stew at Gilgal, what did Elisha put into the pot?', ARRAY['Flour', 'Salt', 'A piece of bread', 'Olive oil']::text[], 'Flour', 'Elisha asked for flour, threw it into the pot and the harmful effect was removed.', '2 Kings 4:38–41', '{"challengeType":"prophet-action","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l20-c5', 'scripture-challenge', 20, 5, 'When David was offered three possible punishments after his census, which prophet delivered the LORD’s message to him?', ARRAY['Samuel', 'Gad', 'Nathan', 'Ahijah']::text[], 'Gad', 'Gad the seer came to David with the three choices: famine, fleeing before enemies, or plague.', '2 Samuel 24:11–14', '{"challengeType":"prophet-identification","curated":true,"difficulty":"hard"}'::jsonb)
ON CONFLICT (game_slug, level, challenge_index) DO UPDATE SET
  question_key = EXCLUDED.question_key,
  question_text = EXCLUDED.question_text,
  options = EXCLUDED.options,
  correct_answer = EXCLUDED.correct_answer,
  explanation = EXCLUDED.explanation,
  reference = EXCLUDED.reference,
  metadata = EXCLUDED.metadata;

INSERT INTO public.game_content (
  question_key, game_slug, level, challenge_index, question_text,
  options, correct_answer, explanation, reference, metadata
) VALUES
('scripture-challenge-l21-c1', 'scripture-challenge', 21, 1, 'Which priestly division did Zechariah, the father of John the Baptist, belong to?', ARRAY['Jedaiah', 'Pashhur', 'Immer', 'Abijah']::text[], 'Abijah', 'Zechariah belonged to the division of Abijah, and Elizabeth was descended from Aaron.', 'Luke 1:5', '{"challengeType":"family-record","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l21-c2', 'scripture-challenge', 21, 2, 'How many months did Elizabeth keep herself in seclusion after she became pregnant?', ARRAY['Seven months', 'Three months', 'Six months', 'Five months']::text[], 'Five months', 'After her days of service were completed, Elizabeth conceived and kept herself hidden for five months.', 'Luke 1:23–25', '{"challengeType":"number-trap","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l21-c3', 'scripture-challenge', 21, 3, 'What happened to the baby in Elizabeth’s womb when Mary greeted her?', ARRAY['He became still and stopped moving', 'He cried out audibly', 'He leaped in her womb', 'He turned so that Elizabeth felt pain']::text[], 'He leaped in her womb', 'At Mary’s greeting, the baby leaped in Elizabeth’s womb, and Elizabeth was filled with the Holy Spirit.', 'Luke 1:39–45', '{"challengeType":"birth-narrative","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l21-c4', 'scripture-challenge', 21, 4, 'Which elderly woman recognized the significance of the child Jesus at the temple and spoke about him to those awaiting Jerusalem’s redemption?', ARRAY['Anna the prophetess', 'Joanna the wife of Chuza', 'Salome the mother of James', 'Martha of Bethany']::text[], 'Anna the prophetess', 'Anna, a prophetess from the tribe of Asher, gave thanks to God and spoke about Jesus to those looking for Jerusalem’s redemption.', 'Luke 2:36–38', '{"challengeType":"identity-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l21-c5', 'scripture-challenge', 21, 5, 'At what age did Jesus remain behind in Jerusalem and later get found among the teachers in the temple?', ARRAY['Fourteen years old', 'Twelve years old', 'Eight years old', 'Ten years old']::text[], 'Twelve years old', 'Jesus was twelve when his parents found him in the temple, listening to the teachers and asking questions.', 'Luke 2:41–49', '{"challengeType":"number-trap","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l22-c1', 'scripture-challenge', 22, 1, 'Which tax collector did Jesus call while he was sitting at the tax booth?', ARRAY['Bartimaeus son of Timaeus', 'Levi son of Alphaeus', 'Zacchaeus son of Baruch', 'Matthew son of Zebedee']::text[], 'Levi son of Alphaeus', 'Mark names the tax collector Jesus called as Levi son of Alphaeus. Matthew’s Gospel gives the name Matthew in its parallel account.', 'Mark 2:13–17', '{"challengeType":"ministry-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l22-c2', 'scripture-challenge', 22, 2, 'At the synagogue in Nazareth, which prophet’s scroll was handed to Jesus to read?', ARRAY['Daniel', 'Isaiah', 'Ezekiel', 'Jeremiah']::text[], 'Isaiah', 'Jesus read from the scroll of Isaiah, including the passage about the Spirit of the Lord being upon him.', 'Luke 4:16–21', '{"challengeType":"ministry-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l22-c3', 'scripture-challenge', 22, 3, 'Which two brothers did Jesus nickname Boanerges, meaning “Sons of Thunder”?', ARRAY['Philip and Bartholomew', 'James and John', 'Peter and Andrew', 'Judas and Thomas']::text[], 'James and John', 'Jesus gave the name Boanerges to James and John, the sons of Zebedee.', 'Mark 3:16–17', '{"challengeType":"name-and-title","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l22-c4', 'scripture-challenge', 22, 4, 'Who asked Jesus, “What is truth?” during the proceedings before the crucifixion?', ARRAY['Pontius Pilate', 'Simon of Cyrene', 'Herod Antipas', 'Joseph Caiaphas']::text[], 'Pontius Pilate', 'Pilate asked Jesus whether he was a king and then asked, “What is truth?”', 'John 18:33–38', '{"challengeType":"ministry-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l22-c5', 'scripture-challenge', 22, 5, 'Which Pharisee came to Jesus at night and later helped bring a large quantity of spices for his burial?', ARRAY['Gamaliel', 'Nicodemus', 'Simon the leper', 'Joseph of Arimathea']::text[], 'Nicodemus', 'Nicodemus first visited Jesus at night and later joined Joseph of Arimathea in preparing Jesus’ body for burial.', 'John 3:1–2; 19:38–40', '{"challengeType":"character-trail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l23-c1', 'scripture-challenge', 23, 1, 'At the wedding in Cana, how many stone water jars were standing there for Jewish purification?', ARRAY['Seven', 'Five', 'Six', 'Four']::text[], 'Six', 'John specifies six stone water jars, each holding two or three measures.', 'John 2:1–10', '{"challengeType":"miracle-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l23-c2', 'scripture-challenge', 23, 2, 'How many baskets of fragments were collected after Jesus fed the five thousand?', ARRAY['Fourteen', 'Ten', 'Seven', 'Twelve']::text[], 'Twelve', 'After the five thousand ate, the disciples collected twelve baskets of broken pieces and fish.', 'Mark 6:35–44', '{"challengeType":"number-trap","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l23-c3', 'scripture-challenge', 23, 3, 'What was the name of the servant whose right ear Peter cut off during Jesus’ arrest?', ARRAY['Barabbas', 'Malchus', 'Tertullus', 'Alexander']::text[], 'Malchus', 'John identifies the servant as Malchus and records that Peter cut off his right ear.', 'John 18:10', '{"challengeType":"identity-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l23-c4', 'scripture-challenge', 23, 4, 'At the pool of Bethesda, how long had the man been disabled before Jesus healed him?', ARRAY['Twelve years', 'Thirty-eight years', 'Twenty-five years', 'Forty years']::text[], 'Thirty-eight years', 'The man told Jesus that he had been an invalid for thirty-eight years.', 'John 5:1–9', '{"challengeType":"number-trap","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l23-c5', 'scripture-challenge', 23, 5, 'When Jesus healed the blind man in Bethsaida, what did the man initially say he could see?', ARRAY['People who looked like trees walking around', 'People standing upside down', 'Faces without bodies', 'Bright lights but no people']::text[], 'People who looked like trees walking around', 'The healing happened in stages. At first the man saw people but described them as looking like trees walking.', 'Mark 8:22–26', '{"challengeType":"miracle-sequence","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l24-c1', 'scripture-challenge', 24, 1, 'Who said, “Am I my brother’s keeper?”', ARRAY['Cain', 'Adam', 'Lamech', 'Abel']::text[], 'Cain', 'After killing Abel, Cain answered the LORD with the question about being his brother’s keeper.', 'Genesis 4:8–10', '{"challengeType":"speaker-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l24-c2', 'scripture-challenge', 24, 2, 'Who declared, “As for me and my house, we will serve the LORD”?', ARRAY['Caleb', 'Samuel', 'Moses', 'Joshua']::text[], 'Joshua', 'Joshua spoke these words when he challenged Israel to choose whom they would serve.', 'Joshua 24:14–15', '{"challengeType":"speaker-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l24-c3', 'scripture-challenge', 24, 3, 'Who said, “Though he slay me, yet will I trust in him” in the traditional wording of the verse?', ARRAY['David', 'Habakkuk', 'Job', 'Jeremiah']::text[], 'Job', 'The statement comes from Job as he responds amid his suffering and dispute with his friends.', 'Job 13:15', '{"challengeType":"speaker-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l24-c4', 'scripture-challenge', 24, 4, 'Who said, “Behold, I am the handmaid of the Lord; let it be to me according to your word”?', ARRAY['Martha', 'Anna', 'Mary', 'Elizabeth']::text[], 'Mary', 'Mary answered Gabriel with these words after hearing that she would give birth to Jesus.', 'Luke 1:26–38', '{"challengeType":"speaker-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l24-c5', 'scripture-challenge', 24, 5, 'Who said, “You are the man!” when confronting King David about his sin?', ARRAY['Joab the commander', 'Gad the seer', 'Abiathar the priest', 'Nathan the prophet']::text[], 'Nathan the prophet', 'After telling David the parable of the rich man and the ewe lamb, Nathan declared that David was the man.', '2 Samuel 12:1–7', '{"challengeType":"speaker-identification","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l25-c1', 'scripture-challenge', 25, 1, 'Which Gospel alone records the visit of the Magi and their gifts to the child Jesus?', ARRAY['Mark', 'John', 'Matthew', 'Luke']::text[], 'Matthew', 'Matthew records the Magi following the star and presenting gold, frankincense and myrrh. The other Gospels do not include this episode.', 'Matthew 2:1–12', '{"challengeType":"gospel-comparison","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l25-c2', 'scripture-challenge', 25, 2, 'Which Gospel records the parable of the Good Samaritan?', ARRAY['Luke', 'John', 'Mark', 'Matthew']::text[], 'Luke', 'The Good Samaritan is found in Luke’s account, in response to a lawyer’s question about who counts as a neighbour.', 'Luke 10:25–37', '{"challengeType":"gospel-comparison","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l25-c3', 'scripture-challenge', 25, 3, 'Which Gospel records Jesus raising Lazarus from the dead?', ARRAY['Matthew', 'Luke', 'John', 'Mark']::text[], 'John', 'John gives the account of Lazarus of Bethany, including his sisters Mary and Martha. This event is not narrated in the other three Gospels.', 'John 11:1–44', '{"challengeType":"gospel-comparison","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l25-c4', 'scripture-challenge', 25, 4, 'Which Gospel begins with a genealogy tracing Jesus’ ancestry back to Adam?', ARRAY['John', 'Matthew', 'Luke', 'Mark']::text[], 'Luke', 'Luke’s genealogy runs back to Adam, while Matthew’s genealogy begins with Abraham.', 'Luke 3:23–38', '{"challengeType":"gospel-comparison","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l25-c5', 'scripture-challenge', 25, 5, 'Which Gospel records the young man who fled naked when Jesus was arrested?', ARRAY['John', 'Mark', 'Matthew', 'Luke']::text[], 'Mark', 'Mark alone includes the brief detail of a young man who left his linen cloth behind and ran away naked.', 'Mark 14:51–52', '{"challengeType":"gospel-comparison","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l26-c1', 'scripture-challenge', 26, 1, 'In the parable of the ten virgins, what did the five wise virgins take along with their lamps?', ARRAY['A second lamp each', 'Extra oil in jars', 'A flask of water', 'Torches and spare wicks']::text[], 'Extra oil in jars', 'The wise virgins took oil in jars along with their lamps, while the foolish ones did not bring extra oil.', 'Matthew 25:1–13', '{"challengeType":"parable-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l26-c2', 'scripture-challenge', 26, 2, 'In the parable of the unforgiving servant, how much did the servant owe the king?', ARRAY['One hundred denarii', 'Ten thousand talents', 'One thousand drachmas', 'Five hundred talents']::text[], 'Ten thousand talents', 'The servant owed ten thousand talents, an enormous debt that the king cancelled when he pleaded for patience.', 'Matthew 18:23–27', '{"challengeType":"parable-number","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l26-c3', 'scripture-challenge', 26, 3, 'In the parable of the sower, what happened to the seed that fell among thorns?', ARRAY['Birds immediately ate it', 'It withered because it had no root', 'The thorns grew up and choked it', 'It produced a crop thirtyfold']::text[], 'The thorns grew up and choked it', 'The thorns grew and choked the plants. Jesus explained that this represents the word being choked by the cares of the world and the deceitfulness of wealth.', 'Matthew 13:3–7, 18–23', '{"challengeType":"parable-interpretation","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l26-c4', 'scripture-challenge', 26, 4, 'In the parable of the lost coin, how many coins did the woman have before losing one?', ARRAY['Seven', 'Twenty', 'Twelve', 'Ten']::text[], 'Ten', 'The woman had ten silver coins, lit a lamp and swept the house until she found the one she had lost.', 'Luke 15:8–10', '{"challengeType":"parable-number","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l26-c5', 'scripture-challenge', 26, 5, 'In the parable of the workers in the vineyard, which group was paid first?', ARRAY['Those hired at dawn', 'Those hired last', 'Those who worked the longest', 'Those hired at the third hour']::text[], 'Those hired last', 'The owner instructed the manager to pay the workers beginning with the last hired and ending with the first.', 'Matthew 20:1–16', '{"challengeType":"parable-sequence","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l27-c1', 'scripture-challenge', 27, 1, 'Complete Jesus’ teaching: “Blessed are the peacemakers, for they shall be called…”', ARRAY['Sons of God', 'Children of light', 'Friends of God', 'Heirs of the kingdom']::text[], 'Sons of God', 'In the Beatitudes, Jesus says that peacemakers will be called sons of God. Some translations render this as children of God.', 'Matthew 5:9', '{"challengeType":"teaching-completion","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l27-c2', 'scripture-challenge', 27, 2, 'Complete Jesus’ instruction: “Seek first the kingdom of God and…”', ARRAY['His righteousness', 'His power and glory', 'His temple and altar', 'His wisdom and knowledge']::text[], 'His righteousness', 'Jesus tells his hearers to seek first God’s kingdom and his righteousness, with these other things to be added.', 'Matthew 6:33', '{"challengeType":"teaching-completion","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l27-c3', 'scripture-challenge', 27, 3, 'Complete Jesus’ teaching about judging others: “First take the plank out of your own…”', ARRAY['Heart', 'Eye', 'Hand', 'House']::text[], 'Eye', 'Jesus uses the picture of a plank in one person’s eye and a speck in another’s to warn against hypocritical judgment.', 'Matthew 7:3–5', '{"challengeType":"teaching-completion","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l27-c4', 'scripture-challenge', 27, 4, 'Complete Jesus’ teaching: “Where your treasure is, there your…”', ARRAY['Hope will increase', 'Reward will be found', 'Mind will remain', 'Heart will be also']::text[], 'Heart will be also', 'Jesus teaches that the location of a person’s treasure reveals where that person’s heart is.', 'Matthew 6:19–21', '{"challengeType":"teaching-completion","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l27-c5', 'scripture-challenge', 27, 5, 'Complete Jesus’ command: “Love your enemies and…”', ARRAY['Avoid those who oppose you', 'Pray for those who persecute you', 'Wait until they ask for forgiveness', 'Repay them when they repent']::text[], 'Pray for those who persecute you', 'Jesus commands his followers to love their enemies and pray for those who persecute them.', 'Matthew 5:43–48', '{"challengeType":"teaching-completion","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l28-c1', 'scripture-challenge', 28, 1, 'Which disciple was chosen by lot to take the place of Judas Iscariot?', ARRAY['Silas', 'Joseph Barsabbas', 'Justus', 'Matthias']::text[], 'Matthias', 'The gathered believers proposed Joseph called Barsabbas and Matthias. After prayer and the casting of lots, Matthias was added to the eleven apostles.', 'Acts 1:15–26', '{"challengeType":"disciple-identity","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l28-c2', 'scripture-challenge', 28, 2, 'Which disciple asked Jesus to show them the Father?', ARRAY['Thomas', 'Judas son of James', 'Andrew', 'Philip']::text[], 'Philip', 'Philip said, “Lord, show us the Father.” Jesus replied that whoever had seen him had seen the Father.', 'John 14:8–11', '{"challengeType":"disciple-identity","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l28-c3', 'scripture-challenge', 28, 3, 'Which disciple was known as “the Twin”?', ARRAY['Bartholomew', 'Thomas', 'Matthew', 'Thaddaeus']::text[], 'Thomas', 'John identifies Thomas as the one called Didymus, meaning Twin.', 'John 11:16; 20:24', '{"challengeType":"name-and-title","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l28-c4', 'scripture-challenge', 28, 4, 'Who was the mother of John Mark, at whose house believers gathered to pray for Peter?', ARRAY['Rhoda', 'Lydia', 'Mary', 'Priscilla']::text[], 'Mary', 'After his release from prison, Peter went to the house of Mary, the mother of John Mark, where many were gathered in prayer.', 'Acts 12:12–16', '{"challengeType":"disciple-network","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l28-c5', 'scripture-challenge', 28, 5, 'Which two disciples were sent by Jesus to prepare the Passover meal in Jerusalem according to Luke?', ARRAY['James and John', 'Peter and John', 'Philip and Thomas', 'Peter and Andrew']::text[], 'Peter and John', 'Jesus sent Peter and John ahead, telling them where they would find the furnished upper room.', 'Luke 22:7–13', '{"challengeType":"disciple-pair","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l29-c1', 'scripture-challenge', 29, 1, 'During the supper, what did Jesus do for his disciples according to John?', ARRAY['He washed their feet', 'He gave each of them a new robe', 'He broke the Passover bread first', 'He anointed their heads with oil']::text[], 'He washed their feet', 'John records that Jesus rose from the meal, wrapped a towel around himself and washed the disciples’ feet.', 'John 13:1–12', '{"challengeType":"final-week-sequence","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l29-c2', 'scripture-challenge', 29, 2, 'Who carried the cross of Jesus on the way to Golgotha according to the Synoptic Gospels?', ARRAY['Joseph of Arimathea', 'Simon of Cyrene', 'Cleopas', 'Barabbas']::text[], 'Simon of Cyrene', 'The soldiers compelled Simon of Cyrene, the father of Alexander and Rufus, to carry Jesus’ cross.', 'Matthew 27:32; Mark 15:21; Luke 23:26', '{"challengeType":"final-week-identity","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l29-c3', 'scripture-challenge', 29, 3, 'What was the inscription placed above Jesus on the cross according to John’s account?', ARRAY['Jesus, the Teacher from Nazareth', 'The Son of David, King of Israel', 'Jesus of Nazareth, the King of the Jews', 'Jesus, the Prophet of Galilee']::text[], 'Jesus of Nazareth, the King of the Jews', 'Pilate wrote the inscription in Hebrew, Latin and Greek: “Jesus of Nazareth, the King of the Jews.”', 'John 19:19–22', '{"challengeType":"final-week-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l29-c4', 'scripture-challenge', 29, 4, 'Who asked Pilate for Jesus’ body after the crucifixion?', ARRAY['Cleopas', 'Nicodemus alone', 'Joseph of Arimathea', 'Simon of Cyrene']::text[], 'Joseph of Arimathea', 'Joseph of Arimathea, a respected member of the council, went boldly to Pilate and asked for Jesus’ body.', 'Mark 15:42–46; John 19:38', '{"challengeType":"final-week-identity","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l29-c5', 'scripture-challenge', 29, 5, 'On the road to Emmaus, what did the two disciples recognize Jesus doing before they knew who he was?', ARRAY['Washing his hands', 'Pouring wine into a cup', 'Reading from the prophets', 'Breaking the bread']::text[], 'Breaking the bread', 'Their eyes were opened when Jesus took bread, blessed it, broke it and gave it to them.', 'Luke 24:13–35', '{"challengeType":"resurrection-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l30-c1', 'scripture-challenge', 30, 1, 'In Matthew’s account, what was the name of the field bought with the thirty pieces of silver?', ARRAY['The Shepherd’s Field', 'The Field of Blood', 'The Valley of Hinnom', 'The Potter’s Field']::text[], 'The Potter’s Field', 'The chief priests used the returned silver to buy the potter’s field as a burial place for foreigners.', 'Matthew 27:3–10', '{"challengeType":"gospel-synthesis","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l30-c2', 'scripture-challenge', 30, 2, 'Which Gospel gives the extended conversation in which Jesus calls Mary Magdalene by name near the tomb?', ARRAY['Matthew', 'Mark', 'John', 'Luke']::text[], 'John', 'John describes Mary remaining outside the tomb and then recognizing Jesus when he called her by name.', 'John 20:11–18', '{"challengeType":"gospel-synthesis","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l30-c3', 'scripture-challenge', 30, 3, 'In Luke’s account, what did the risen Jesus ask for before eating in front of the disciples?', ARRAY['A cup of wine', 'A piece of broiled fish', 'Roasted lamb', 'A loaf of bread and honey']::text[], 'A piece of broiled fish', 'Jesus asked whether they had anything to eat, and they gave him a piece of broiled fish.', 'Luke 24:36–43', '{"challengeType":"gospel-detail","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l30-c4', 'scripture-challenge', 30, 4, 'Which Gospel ends with Jesus commissioning the disciples and promising to be with them always, to the end of the age?', ARRAY['Mark', 'Matthew', 'Luke', 'John']::text[], 'Matthew', 'Matthew closes with the Great Commission and Jesus’ promise to be with his disciples always.', 'Matthew 28:16–20', '{"challengeType":"gospel-synthesis","curated":true,"difficulty":"hard"}'::jsonb),
('scripture-challenge-l30-c5', 'scripture-challenge', 30, 5, 'According to Acts, from which mount did the disciples return to Jerusalem after Jesus’ ascension?', ARRAY['The Mount of Carmel', 'The Mount of Olives', 'The road to Emmaus', 'The temple courts in Jerusalem']::text[], 'The Mount of Olives', 'Luke says Jesus led the disciples out toward Bethany; Acts places their return from the Mount called Olivet, near Jerusalem.', 'Acts 1:9–12', '{"challengeType":"gospel-synthesis","curated":true,"difficulty":"hard"}'::jsonb)
ON CONFLICT (game_slug, level, challenge_index) DO UPDATE SET
  question_key = EXCLUDED.question_key,
  question_text = EXCLUDED.question_text,
  options = EXCLUDED.options,
  correct_answer = EXCLUDED.correct_answer,
  explanation = EXCLUDED.explanation,
  reference = EXCLUDED.reference,
  metadata = EXCLUDED.metadata;

INSERT INTO public.game_content (
  question_key, game_slug, level, challenge_index, question_text,
  options, correct_answer, explanation, reference, metadata
) VALUES
('bible-detective-l1-c1', 'bible-detective', 1, 1, 'CASE FILE 001: The Alabaster Flask at Simon''s Table
Investigate the testimony and identify the biblical event or person.', ARRAY['The Samaritan Woman', 'Mary of Bethany at Bethany', 'The Sinful Woman Who Anointed Jesus'' Feet', 'The Woman with the Issue of Blood']::text[], 'The Sinful Woman Who Anointed Jesus'' Feet', 'Jesus used the story of two debtors to explain why the woman loved much, and he declared her sins forgiven.', 'Luke 7:36-50', '{"difficulty":"beginner","case_title":"The Alabaster Flask at Simon''s Table","clues":["A woman entered a Pharisee''s house while Jesus was reclining at the table.","She stood behind him weeping, wet his feet with tears, wiped them with her hair and anointed them from an alabaster flask.","The host questioned Jesus'' acceptance of her; Jesus answered with a story about two debtors and declared her sins forgiven."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-1"}'::jsonb),
('bible-detective-l1-c2', 'bible-detective', 1, 2, 'CASE FILE 002: The Fever at the Seventh Hour
Investigate the testimony and identify the biblical event or person.', ARRAY['The Healing of the Royal Official''s Son', 'The Widow of Nain''s Son', 'Jairus'' Daughter', 'The Centurion''s Servant']::text[], 'The Healing of the Royal Official''s Son', 'Jesus healed the royal official''s son from a distance; the official connected the recovery at the seventh hour with Jesus'' words.', 'John 4:46-54', '{"difficulty":"beginner","case_title":"The Fever at the Seventh Hour","clues":["A royal official from Capernaum begged Jesus to come down and heal his son, who was near death.","Jesus told him to go home because his son would live.","On the journey home, servants reported that the fever had left at the seventh hour; the official recognised that this was the hour Jesus had spoken."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-2"}'::jsonb),
('bible-detective-l1-c3', 'bible-detective', 1, 3, 'CASE FILE 03: The Unusual Witness at the City Gate
Investigate the testimony and identify the biblical event or person.', ARRAY['The Spies Return from Canaan', 'Gideon''s Night Raid', 'The Four Lepers Discover the Aramean Camp', 'The Gibeonites'' Deception']::text[], 'The Four Lepers Discover the Aramean Camp', 'The four men with leprosy found the Aramean camp deserted and reported it to Samaria.', '2 Kings 7:3-11', '{"difficulty":"beginner","case_title":"The Unusual Witness at the City Gate","clues":["Evidence A — A famine-stricken capital had four men excluded from ordinary society at its gate.","Evidence B — They discovered the enemy camp abandoned, with food and valuables left behind.","Evidence C — They first hid supplies, then returned to report the news instead of keeping it secret."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-3"}'::jsonb),
('bible-detective-l1-c4', 'bible-detective', 1, 4, 'CASE FILE 04: The Unclaimed Inheritance
Investigate the testimony and identify the biblical event or person.', ARRAY['The Daughters of Jethro', 'The Daughters of Job', 'The Daughters of Caleb', 'The Daughters of Zelophehad']::text[], 'The Daughters of Zelophehad', 'Mahlah, Noah, Hoglah, Milcah and Tirzah received an inheritance ruling from the LORD.', 'Numbers 27:1-11; 36:1-12', '{"difficulty":"beginner","case_title":"The Unclaimed Inheritance","clues":["Evidence A — A man died without sons, and his daughters approached the entrance of the tent of meeting.","Evidence B — They asked why their father''s name should disappear because he had no son.","Evidence C — Moses brought their case before the LORD, and the ruling changed Israel''s inheritance law."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-4"}'::jsonb),
('bible-detective-l1-c5', 'bible-detective', 1, 5, 'CASE FILE 05: The Unusual Census Payment
Investigate the testimony and identify the biblical event or person.', ARRAY['David''s Census of Israel', 'The Temple Tax in Jesus'' Day', 'The Widow''s Offering', 'The Half-Shekel Census Offering']::text[], 'The Half-Shekel Census Offering', 'Exodus prescribes a half-shekel ransom for each person counted in the census.', 'Exodus 30:11-16', '{"difficulty":"beginner","case_title":"The Unusual Census Payment","clues":["Evidence A — A census was ordered among Israel''s men eligible for military service.","Evidence B — Each counted person was to give the same half-shekel amount, regardless of wealth.","Evidence C — The payment was called atonement money and was assigned to the service of the tent of meeting."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-5"}'::jsonb),
('bible-detective-l2-c1', 'bible-detective', 2, 1, 'CASE FILE 006: The Trees Seeking a King
Investigate the evidence and identify the biblical event or person.', ARRAY['Joash''s Temple Chest', 'Gideon''s Fleece', 'Jotham''s Parable of the Trees', 'Nathan''s Parable of the Ewe Lamb']::text[], 'Jotham''s Parable of the Trees', 'Jotham told the people of Shechem a parable in which the olive, fig and vine declined kingship, while the bramble accepted it and warned of fire.', 'Judges 9:7-21', '{"difficulty":"beginner","case_title":"The Trees Seeking a King","clues":["A surviving son of Gideon addressed the people from Mount Gerizim after a violent struggle over kingship.","In his story, the olive tree, fig tree and vine each refused to abandon their useful work to rule the trees.","A bramble accepted the offer and warned that fire could come from it and consume the cedars of Lebanon."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-2-1"}'::jsonb),
('bible-detective-l2-c2', 'bible-detective', 2, 2, 'CASE FILE 07: The Prophetic Sign of Two Sticks
Investigate the testimony and identify the biblical event or person.', ARRAY['Ezekiel''s Two Sticks', 'Moses'' Two Tablets', 'Aaron''s Rod That Budded', 'Zechariah''s Two Olive Trees']::text[], 'Ezekiel''s Two Sticks', 'The joined sticks symbolised the reunification of Israel under one king.', 'Ezekiel 37:15-28', '{"difficulty":"beginner","case_title":"The Prophetic Sign of Two Sticks","clues":["Evidence A — A prophet was told to write two names on separate pieces of wood.","Evidence B — One stick represented Judah and its companions; the other represented Joseph/Ephraim.","Evidence C — The pieces were joined in the prophet''s hand as a sign of one reunited people."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-7"}'::jsonb),
('bible-detective-l2-c3', 'bible-detective', 2, 3, 'CASE FILE 08: The Prisoner Who Sent Back a Runaway
Investigate the testimony and identify the biblical event or person.', ARRAY['Peter''s Appeal for Silas', 'Paul''s Appeal for Onesimus', 'Paul''s Appeal for Mark', 'John''s Appeal for Demetrius']::text[], 'Paul''s Appeal for Onesimus', 'Paul appealed to Philemon to receive Onesimus as a brother, not merely as a servant.', 'Philemon 1:8-18', '{"difficulty":"beginner","case_title":"The Prisoner Who Sent Back a Runaway","clues":["Evidence A — A letter was written by a prisoner concerning a man who had become a Christian.","Evidence B — The writer called the man his child, saying he had become his father while in chains.","Evidence C — The request was not merely to receive him back, but to welcome him as a beloved brother."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-8"}'::jsonb),
('bible-detective-l2-c4', 'bible-detective', 2, 4, 'CASE FILE 09: The Courtroom Split Over a Resurrection
Investigate the testimony and identify the biblical event or person.', ARRAY['Peter Before the Council', 'Paul Before the Sanhedrin', 'Jesus Before Caiaphas', 'Stephen Before the Sanhedrin']::text[], 'Paul Before the Sanhedrin', 'Paul''s statement about resurrection divided the Pharisees and Sadducees.', 'Acts 23:1-10', '{"difficulty":"beginner","case_title":"The Courtroom Split Over a Resurrection","clues":["Evidence A — A prisoner stood before a council made up of two rival Jewish groups.","Evidence B — He declared that he was being judged concerning the hope of the resurrection of the dead.","Evidence C — The declaration divided the council because one group denied resurrection, angels and spirits."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-9"}'::jsonb),
('bible-detective-l2-c5', 'bible-detective', 2, 5, 'CASE FILE 10: The Unknown Altar in Athens
Investigate the testimony and identify the biblical event or person.', ARRAY['Barnabas in Lystra', 'Paul at the Areopagus', 'Paul in Ephesus', 'Peter at Pentecost']::text[], 'Paul at the Areopagus', 'Paul referred to the altar ''To the Unknown God'' in his speech in Athens.', 'Acts 17:16-31', '{"difficulty":"beginner","case_title":"The Unknown Altar in Athens","clues":["Evidence A — A travelling teacher examined religious objects in a Greek city.","Evidence B — He found an altar bearing an inscription to an unknown deity.","Evidence C — He used the inscription to introduce the Creator who does not live in temples made by hands."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-10"}'::jsonb),
('bible-detective-l3-c1', 'bible-detective', 3, 1, 'CASE FILE 011: The Voice in the Night at Shiloh
Investigate the evidence and identify the biblical event or person.', ARRAY['Micaiah''s Vision of the Heavenly Court', 'Samuel''s Call at Shiloh', 'Elijah''s Call at Horeb', 'Samuel Anoints Saul']::text[], 'Samuel''s Call at Shiloh', 'The LORD called Samuel during the night; Eli eventually understood what was happening and instructed the boy to answer the LORD.', '1 Samuel 3:1-18', '{"difficulty":"beginner","case_title":"The Voice in the Night at Shiloh","clues":["A young attendant served under an elderly priest while the word of the LORD was rare.","He heard his name called during the night and repeatedly ran to the priest, thinking he had been summoned.","The priest told him to answer, ''Speak, LORD, for your servant hears''; the message concerned judgment on the priest''s household."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-3-1"}'::jsonb),
('bible-detective-l3-c2', 'bible-detective', 3, 2, 'CASE FILE 12: The Man Who Was Not to Be Harmed
Investigate the testimony and identify the biblical event or person.', ARRAY['The Plot Against Stephen', 'The Plot Against Barnabas', 'The Plot Against Peter', 'The Plot Against Paul']::text[], 'The Plot Against Paul', 'Paul''s nephew warned the Roman commander of the ambush planned by conspirators.', 'Acts 23:12-35', '{"difficulty":"beginner","case_title":"The Man Who Was Not to Be Harmed","clues":["Evidence A — A commander of the Roman cohort protected a prisoner from a plot.","Evidence B — More than forty men had sworn not to eat or drink until they killed the prisoner.","Evidence C — The prisoner''s nephew heard the plot and reported it to the commander."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-12"}'::jsonb),
('bible-detective-l3-c3', 'bible-detective', 3, 3, 'CASE FILE 13: The Prophet Who Challenged a Royal Wedding
Investigate the testimony and identify the biblical event or person.', ARRAY['Elijah and Ahab', 'Micaiah and Ahab', 'Nathan and David', 'John the Baptist and Herod Antipas']::text[], 'John the Baptist and Herod Antipas', 'John rebuked Herod for marrying Herodias, his brother''s wife, and was executed after Herod''s oath.', 'Mark 6:17-29', '{"difficulty":"beginner","case_title":"The Prophet Who Challenged a Royal Wedding","clues":["Evidence A — A prophet confronted a ruler for taking his brother''s wife.","Evidence B — The ruler imprisoned the prophet, but feared him because he knew him to be righteous and holy.","Evidence C — At a birthday banquet, a promise made to a dancer led to the prophet''s execution."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-13"}'::jsonb),
('bible-detective-l3-c4', 'bible-detective', 3, 4, 'CASE FILE 14: The Contract Sealed Before Exile
Investigate the testimony and identify the biblical event or person.', ARRAY['Abraham Buys Machpelah', 'David Buys Araunah''s Threshing Floor', 'Jeremiah Buys Hanamel''s Field', 'Boaz Redeems Ruth''s Land']::text[], 'Jeremiah Buys Hanamel''s Field', 'Jeremiah bought his cousin Hanamel''s field at Anathoth as a sign of future restoration.', 'Jeremiah 32:6-15', '{"difficulty":"beginner","case_title":"The Contract Sealed Before Exile","clues":["Evidence A — A prophet was told to buy a field while the city was under siege.","Evidence B — The deed was signed, witnessed and sealed, with a copy left unsealed for reference.","Evidence C — The documents were placed in an earthen vessel so they would last many days."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-14"}'::jsonb),
('bible-detective-l3-c5', 'bible-detective', 3, 5, 'CASE FILE 15: The Man Who Refused to Strike the Ground Enough
Investigate the testimony and identify the biblical event or person.', ARRAY['Jehoash and the Bow of Jehu', 'Amaziah and the Edomites', 'Hezekiah and the Assyrian Threat', 'Joash and Elisha''s Arrows']::text[], 'Joash and Elisha''s Arrows', 'Elisha rebuked Joash for striking the ground only three times after the arrow of deliverance.', '2 Kings 13:14-19', '{"difficulty":"beginner","case_title":"The Man Who Refused to Strike the Ground Enough","clues":["Evidence A — A dying prophet told a king to take a bow and arrows and strike the ground.","Evidence B — The king struck the ground three times and stopped.","Evidence C — The prophet became angry because the king would now defeat Aram only three times rather than completely."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-15"}'::jsonb),
('bible-detective-l4-c1', 'bible-detective', 4, 1, 'CASE FILE 16: The Two Prophets and the Disputed Burial
Investigate the testimony and identify the biblical event or person.', ARRAY['The Man of God from Judah', 'Micaiah son of Imlah', 'Elijah at Cherith', 'Hanani the Seer']::text[], 'The Man of God from Judah', 'The unnamed man of God from Judah disobeyed the LORD''s instruction and was killed by a lion.', '1 Kings 13:11-32', '{"difficulty":"beginner","case_title":"The Two Prophets and the Disputed Burial","clues":["Evidence A — An older prophet persuaded a younger man of God to eat with him despite a contrary instruction.","Evidence B — The younger prophet died on the road after disobeying the word he had received.","Evidence C — A lion stood beside the corpse and the donkey, but neither animal was eaten."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-16"}'::jsonb),
('bible-detective-l4-c2', 'bible-detective', 4, 2, 'CASE FILE 17: The Battle Plan Hidden in a Dream
Investigate the testimony and identify the biblical event or person.', ARRAY['Joseph Interprets Pharaoh''s Dream', 'Gideon Overhears the Midianite Dream', 'Daniel Interprets Nebuchadnezzar''s Dream', 'Jonathan''s Armour-Bearer']::text[], 'Gideon Overhears the Midianite Dream', 'Gideon overheard a Midianite''s dream and its interpretation before attacking the camp.', 'Judges 7:9-15', '{"difficulty":"beginner","case_title":"The Battle Plan Hidden in a Dream","clues":["Evidence A — A Midianite soldier told a companion about a dream involving a barley loaf.","Evidence B — The loaf rolled into the camp and struck a tent, which collapsed.","Evidence C — The companion interpreted the dream as God''s giving the Midianite camp into Gideon''s hand."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-17"}'::jsonb),
('bible-detective-l4-c3', 'bible-detective', 4, 3, 'CASE FILE 18: The Priest Who Hid the Royal Heir
Investigate the testimony and identify the biblical event or person.', ARRAY['Moses Hidden by Pharaoh''s Daughter', 'Joash Hidden by Athaliah', 'Jehoash Hidden by Jehosheba', 'Josiah Hidden by Hilkiah']::text[], 'Jehoash Hidden by Jehosheba', 'Jehosheba hid Joash, and Jehoiada later brought him out to be crowned king.', '2 Kings 11:1-12', '{"difficulty":"beginner","case_title":"The Priest Who Hid the Royal Heir","clues":["Evidence A — A queen attempted to destroy the royal descendants after her son''s death.","Evidence B — A princess took a young child and his nurse and hid them in a bedroom.","Evidence C — The child remained hidden in the temple for six years before being crowned."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-18"}'::jsonb),
('bible-detective-l4-c4', 'bible-detective', 4, 4, 'CASE FILE 019: The Mountain Claimed at Eighty-Five
Investigate the evidence and identify the biblical event or person.', ARRAY['Joshua Receives Timnath-serah', 'Caleb Receives Hebron', 'The Daughters of Zelophehad Receive an Inheritance', 'Othniel Receives Achsah']::text[], 'Caleb Receives Hebron', 'Caleb reminded Joshua of the promise Moses had made and received Hebron as his inheritance because he had followed the LORD wholeheartedly.', 'Joshua 14:6-15', '{"difficulty":"beginner","case_title":"The Mountain Claimed at Eighty-Five","clues":["An older leader from the tribe of Judah approached Joshua at Gilgal and recalled the earlier mission to scout Canaan.","He said forty-five years had passed since Moses sent him from Kadesh-barnea, and he was now eighty-five.","Rather than request an easy portion, he asked for the hill country where the Anakim still lived."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-4-4"}'::jsonb),
('bible-detective-l4-c5', 'bible-detective', 4, 5, 'CASE FILE 20: The Prophet Who Bought Back His Wife
Investigate the testimony and identify the biblical event or person.', ARRAY['Jeremiah Buys a Field', 'Hosea Redeems Gomer', 'Abraham Marries Hagar', 'Boaz Redeems Ruth']::text[], 'Hosea Redeems Gomer', 'Hosea bought Gomer back as a sign of the LORD''s continued love for unfaithful Israel.', 'Hosea 3:1-5', '{"difficulty":"beginner","case_title":"The Prophet Who Bought Back His Wife","clues":["Evidence A — A prophet was told to love a woman who was loved by another and was adulterous.","Evidence B — He bought her for fifteen pieces of silver and a quantity of barley.","Evidence C — She was told to remain with him for many days without prostitution or another man."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-20"}'::jsonb),
('bible-detective-l5-c1', 'bible-detective', 5, 1, 'CASE FILE 21: The Queen Who Asked for a Second Banquet
Investigate the testimony and identify the biblical event or person.', ARRAY['Athaliah Seizes the Throne', 'Esther Exposes Haman', 'Bathsheba Appeals to David', 'Vashti Refuses the King']::text[], 'Esther Exposes Haman', 'Esther exposed Haman''s plot during the second banquet and pleaded for her people.', 'Esther 7:1-6', '{"difficulty":"beginner","case_title":"The Queen Who Asked for a Second Banquet","clues":["Evidence A — A royal decree threatened the lives of a people scattered through an empire.","Evidence B — A queen approached the king uninvited, then invited him and the enemy official to two banquets.","Evidence C — At the second banquet she identified her own people and exposed the plot against them."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-21"}'::jsonb),
('bible-detective-l5-c2', 'bible-detective', 5, 2, 'CASE FILE 22: The Vision of the Flying Scroll
Investigate the testimony and identify the biblical event or person.', ARRAY['Jeremiah''s Burned Scroll', 'Ezekiel''s Scroll', 'Daniel''s Sealed Book', 'Zechariah''s Flying Scroll']::text[], 'Zechariah''s Flying Scroll', 'Zechariah''s flying scroll represented judgment against theft and false swearing.', 'Zechariah 5:1-4', '{"difficulty":"beginner","case_title":"The Vision of the Flying Scroll","clues":["Evidence A — A prophet saw a scroll flying through the air.","Evidence B — The scroll was twenty cubits long and ten cubits wide.","Evidence C — It represented a curse entering the houses of thieves and those who swore falsely."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-22"}'::jsonb),
('bible-detective-l5-c3', 'bible-detective', 5, 3, 'CASE FILE 23: The Basket That Measured Wickedness
Investigate the testimony and identify the biblical event or person.', ARRAY['Ezekiel''s Measuring Line', 'Zechariah''s Ephah Vision', 'Amos'' Basket of Summer Fruit', 'Jeremiah''s Linen Belt']::text[], 'Zechariah''s Ephah Vision', 'The ephah vision depicted Wickedness being carried to Shinar.', 'Zechariah 5:5-11', '{"difficulty":"beginner","case_title":"The Basket That Measured Wickedness","clues":["Evidence A — A prophet saw a basket with a lead cover lifted away.","Evidence B — A woman called Wickedness sat inside, and she was pushed back into the basket.","Evidence C — Two women with wings carried it to Shinar to build a house for it."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-23"}'::jsonb),
('bible-detective-l5-c4', 'bible-detective', 5, 4, 'CASE FILE 024: The Midnight Hymns in Philippi
Investigate the evidence and identify the biblical event or person.', ARRAY['Peter Escapes Herod''s Prison', 'Paul''s Shipwreck on Malta', 'The Apostles Released by an Angel', 'Paul and Silas in the Philippian Jail']::text[], 'Paul and Silas in the Philippian Jail', 'After a slave girl''s owners stirred up opposition, Paul and Silas were beaten and imprisoned; an earthquake opened the prison, and the jailer and his household believed.', 'Acts 16:16-40', '{"difficulty":"beginner","case_title":"The Midnight Hymns in Philippi","clues":["A slave girl followed two missionaries through a Macedonian city, crying out about them; her owners profited from her fortune-telling.","After the missionaries removed the spirit, the owners dragged them before magistrates, who ordered them beaten and jailed.","At midnight the prisoners prayed and sang; an earthquake opened the doors, and the jailer asked what he must do to be saved."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-5-4"}'::jsonb),
('bible-detective-l5-c5', 'bible-detective', 5, 5, 'CASE FILE 25: The Council''s Unexpected Adviser
Investigate the testimony and identify the biblical event or person.', ARRAY['Joseph of Arimathea''s Appeal', 'Caiaphas'' Prophecy', 'Nicodemus'' Defence', 'Gamaliel''s Counsel']::text[], 'Gamaliel''s Counsel', 'Gamaliel advised caution when the council considered killing the apostles.', 'Acts 5:34-39', '{"difficulty":"beginner","case_title":"The Council''s Unexpected Adviser","clues":["Evidence A — A respected Pharisee stood up after apostles were brought before the council.","Evidence B — He recalled earlier failed uprisings led by Theudas and Judas the Galilean.","Evidence C — He advised the council to leave the apostles alone, warning that opposing God would fail."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-25"}'::jsonb),
('bible-detective-l6-c1', 'bible-detective', 6, 1, 'CASE FILE 026: A king hid among baggage during his public selection. Identify the person or event from the evidence.', ARRAY['Saul', 'Ish-bosheth', 'David', 'Absalom']::text[], 'Saul', 'Saul was found hiding among the baggage when Israel sought him after his selection.', '1 Samuel 10:17-24', '{"difficulty":"beginner","case_title":"A king hid among baggage during his public selection","clues":["Evidence A — The people gathered at Mizpah to confirm a king.","Evidence B — The chosen man could not initially be found among the tribes.","Evidence C — He was discovered concealed among the baggage."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-26"}'::jsonb),
('bible-detective-l6-c2', 'bible-detective', 6, 2, 'CASE FILE 027: The Barley Loaves in a Famine
Investigate the evidence and identify the biblical event or person.', ARRAY['Elijah Feeds the Widow at Zarephath', 'Elisha Feeds a Hundred Men', 'The Manna Given in the Wilderness', 'Jesus Feeds the Five Thousand']::text[], 'Elisha Feeds a Hundred Men', 'A man brought twenty barley loaves and fresh ears of grain; Elisha ordered that they be given to one hundred men, and the food was left over according to the LORD''s word.', '2 Kings 4:42-44', '{"difficulty":"beginner","case_title":"The Barley Loaves in a Famine","clues":["During a time of famine, a man arrived from Baal-shalishah carrying food from the firstfruits.","The prophet instructed his servant to set the food before a group of one hundred, although the servant questioned whether it was enough.","Everyone ate, and some was left over in keeping with the word of the LORD."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-6-2"}'::jsonb),
('bible-detective-l6-c3', 'bible-detective', 6, 3, 'CASE FILE 028: The Two Men at the Philistine Pass
Investigate the evidence and identify the biblical event or person.', ARRAY['Jonathan and His Armour-Bearer Attack the Outpost', 'David and Abishai Enter Saul''s Camp', 'Gideon and His Three Hundred', 'Shamgar Strikes the Philistines']::text[], 'Jonathan and His Armour-Bearer Attack the Outpost', 'Jonathan and his armour-bearer approached a Philistine outpost; Jonathan proposed a sign and the two climbed up to attack the garrison.', '1 Samuel 14:1-14', '{"difficulty":"beginner","case_title":"The Two Men at the Philistine Pass","clues":["While Israel''s king remained near Gibeah with the people, his son quietly left the camp with one companion.","The pair proposed that the enemy''s response—calling them to climb up—would serve as a sign that the LORD had given them into Israel''s hand.","They climbed on hands and feet and struck down about twenty men in the first attack."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-6-3"}'::jsonb),
('bible-detective-l6-c4', 'bible-detective', 6, 4, 'CASE FILE 029: A Moabite ruler was killed in a private upper room. Identify the person or event from the evidence.', ARRAY['Jabin', 'Agag', 'Sisera', 'Eglon']::text[], 'Eglon', 'Ehud killed Eglon, king of Moab, and escaped through the porch.', 'Judges 3:12-30', '{"difficulty":"beginner","case_title":"A Moabite ruler was killed in a private upper room","clues":["Evidence A — Israel was oppressed by Moab after doing evil.","Evidence B — The deliverer was left-handed and carried a short sword concealed on his right thigh.","Evidence C — He locked the chamber doors after killing the very obese king."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-29"}'::jsonb),
('bible-detective-l6-c5', 'bible-detective', 6, 5, 'CASE FILE 030: A prophet''s servant was struck with the disease of a healed commander. Identify the person or event from the evidence.', ARRAY['Naaman', 'Elisha', 'Gehazi', 'Joab']::text[], 'Gehazi', 'Gehazi took gifts from Naaman deceitfully and was struck with Naaman''s leprosy.', '2 Kings 5:15-27', '{"difficulty":"beginner","case_title":"A prophet''s servant was struck with the disease of a healed commander","clues":["Evidence A — A foreign military commander had been healed after washing in the Jordan.","Evidence B — The prophet refused payment, but his servant secretly pursued the commander.","Evidence C — The servant lied about visitors and received gifts; the disease clung to him."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-30"}'::jsonb),
('bible-detective-l7-c1', 'bible-detective', 7, 1, 'CASE FILE 031: A priest''s grandson carried a name linked to lost glory. Identify the person or event from the evidence.', ARRAY['Ebenezer', 'Jabez', 'Jeshurun', 'Ichabod']::text[], 'Ichabod', 'Ichabod''s name marked the loss of glory after the ark was captured and his father-in-law died.', '1 Samuel 4:19-22', '{"difficulty":"beginner","case_title":"A priest''s grandson carried a name linked to lost glory","clues":["Evidence A — The child was born when his mother heard that the ark had been captured.","Evidence B — His father and grandfather died on the same day.","Evidence C — His mother named him to mark the departure of glory from Israel."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-31"}'::jsonb),
('bible-detective-l7-c2', 'bible-detective', 7, 2, 'CASE FILE 032: A woman stopped a king from taking revenge on a household. Identify the person or event from the evidence.', ARRAY['Abishag', 'Abigail', 'Michal', 'Bathsheba']::text[], 'Abigail', 'Abigail intervened when Nabal insulted David and prevented David from avenging himself.', '1 Samuel 25:2-35', '{"difficulty":"beginner","case_title":"A woman stopped a king from taking revenge on a household","clues":["Evidence A — A wealthy landowner refused David''s messengers and insulted them.","Evidence B — His wife quickly prepared food and rode out to meet David.","Evidence C — She appealed to David''s future kingship and prevented bloodshed."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-32"}'::jsonb),
('bible-detective-l7-c3', 'bible-detective', 7, 3, 'CASE FILE 033: A prophet confronted a king with a stolen lamb story. Identify the person or event from the evidence.', ARRAY['Gad', 'Ahijah', 'Nathan', 'Micaiah']::text[], 'Nathan', 'Nathan used the parable of the ewe lamb to confront David over his sin.', '2 Samuel 12:1-13', '{"difficulty":"beginner","case_title":"A prophet confronted a king with a stolen lamb story","clues":["Evidence A — A rich man took a poor man''s only ewe lamb to feed a visitor.","Evidence B — The king became angry and declared that the offender deserved death.","Evidence C — The prophet identified the king himself as the guilty man."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-33"}'::jsonb),
('bible-detective-l7-c4', 'bible-detective', 7, 4, 'CASE FILE 034: A royal official was executed after refusing to bow. Identify the person or event from the evidence.', ARRAY['Daniel', 'Nehemiah', 'Mordecai', 'Ezra']::text[], 'Daniel', 'Daniel continued his regular prayers despite the decree and was preserved in the lions'' den.', 'Daniel 6:1-23', '{"difficulty":"beginner","case_title":"A royal official was executed after refusing to bow","clues":["Evidence A — The official was elevated above other officials in a foreign empire.","Evidence B — Rival officials persuaded the king to issue an unchangeable decree.","Evidence C — The official continued praying toward Jerusalem and was thrown into a lions'' den."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-34"}'::jsonb),
('bible-detective-l7-c5', 'bible-detective', 7, 5, 'CASE FILE 035: A queen approached the throne without being summoned. Identify the person or event from the evidence.', ARRAY['Vashti', 'Zeresh', 'Esther', 'Haman']::text[], 'Esther', 'Esther risked approaching the king and arranged banquets to expose Haman''s plot.', 'Esther 4:10-17; 5:1-8', '{"difficulty":"beginner","case_title":"A queen approached the throne without being summoned","clues":["Evidence A — A royal decree threatened the Jews throughout the Persian empire.","Evidence B — Her cousin urged her to consider that she might have come to royalty for that moment.","Evidence C — She fasted, entered the inner court and invited the king to two banquets."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-35"}'::jsonb),
('bible-detective-l8-c1', 'bible-detective', 8, 1, 'CASE FILE 036: A king''s sleep was interrupted by an old record. Identify the person or event from the evidence.', ARRAY['Mordecai', 'Daniel', 'Nehemiah', 'Ezra']::text[], 'Mordecai', 'Mordecai was publicly honoured after the king remembered his exposure of a conspiracy.', 'Esther 6:1-11', '{"difficulty":"beginner","case_title":"A king''s sleep was interrupted by an old record","clues":["Evidence A — The king could not sleep and ordered the chronicles to be read.","Evidence B — He discovered an earlier report of a plot against his life.","Evidence C — The man who had exposed the plot had not been rewarded, and his enemy was ordered to honour him."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-36"}'::jsonb),
('bible-detective-l8-c2', 'bible-detective', 8, 2, 'CASE FILE 037: The Answer from the Ash Heap
Investigate the evidence and identify the biblical event or person.', ARRAY['Job Refuses His Wife''s Counsel', 'Jeremiah Buys a Field', 'Job''s Friends Accuse Him', 'Habakkuk Questions God''s Justice']::text[], 'Job Refuses His Wife''s Counsel', 'After Job was struck with painful sores, his wife urged him to curse God and die; Job refused to speak foolishly and accepted that people receive both good and adversity.', 'Job 2:7-10', '{"difficulty":"beginner","case_title":"The Answer from the Ash Heap","clues":["A righteous man was afflicted with painful sores from the sole of his foot to the crown of his head.","He sat among ashes and used a piece of broken pottery to scrape himself.","His wife urged him to abandon his integrity, but he asked whether they should receive good from God and not adversity."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-8-2"}'::jsonb),
('bible-detective-l8-c3', 'bible-detective', 8, 3, 'CASE FILE 038: The Donkeys and Provisions on the Road
Investigate the evidence and identify the biblical event or person.', ARRAY['Mephibosheth''s Appeal to David', 'Ziba''s Report to David', 'Shimei Seeks Pardon', 'Abigail Meets David']::text[], 'Ziba''s Report to David', 'Ziba met David during his flight from Jerusalem with provisions and made a claim about Mephibosheth''s intentions; the passage records Ziba''s report, not an independently confirmed fact.', '2 Samuel 16:1-4', '{"difficulty":"beginner","case_title":"The Donkeys and Provisions on the Road","clues":["A king was fleeing Jerusalem shortly after crossing the Mount of Olives.","A servant of a man from Saul''s family arrived with two saddled donkeys, bread, dried fruit and wine.","When asked where his master was, the servant claimed that the man had stayed in Jerusalem hoping to regain the kingdom."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-8-3"}'::jsonb),
('bible-detective-l8-c4', 'bible-detective', 8, 4, 'CASE FILE 039: The Mockery on the Road to Bethel
Investigate the evidence and identify the biblical event or person.', ARRAY['The She-Bears of Samaria', 'Elisha Heals Naaman', 'Elisha and the Bears at Bethel', 'Elijah''s Chariot of Fire']::text[], 'Elisha and the Bears at Bethel', 'As Elisha travelled toward Bethel, youths mocked him; after he pronounced a curse in the LORD''s name, two bears came out of the woods and mauled forty-two of them.', '2 Kings 2:23-25', '{"difficulty":"beginner","case_title":"The Mockery on the Road to Bethel","clues":["A prophet was travelling uphill from Jericho toward Bethel after taking up his predecessor''s mantle.","A group of youths came out of the town and repeatedly mocked his appearance and told him to go up.","He turned, pronounced a curse in the name of the LORD, and two female bears came out of the woods."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-8-4"}'::jsonb),
('bible-detective-l8-c5', 'bible-detective', 8, 5, 'CASE FILE 040: The Garments Beside the Upper Room
Investigate the evidence and identify the biblical event or person.', ARRAY['Paul Raises Eutychus', 'Peter Heals Aeneas', 'Peter Raises Tabitha', 'Jesus Raises Jairus'' Daughter']::text[], 'Peter Raises Tabitha', 'Tabitha, also called Dorcas, died in Joppa; Peter prayed beside her and told her to arise, and she was presented alive to the believers.', 'Acts 9:36-43', '{"difficulty":"beginner","case_title":"The Garments Beside the Upper Room","clues":["A disciple in Joppa was known for good works and acts of charity, especially garments she made for others.","After she became ill and died, the believers washed her body and placed it in an upper room.","Widows stood beside the visiting apostle and showed him the tunics and other clothing she had made; he prayed and called her by name to rise."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-8-5"}'::jsonb),
('bible-detective-l9-c1', 'bible-detective', 9, 1, 'CASE FILE 041: The Burden of One Judge
Investigate the evidence and identify the biblical event or person.', ARRAY['Jethro''s Advice to Moses', 'Moses'' Appointment of the Twelve Spies', 'Aaron''s Counsel during the Golden Calf', 'Joshua''s Division of the Land']::text[], 'Jethro''s Advice to Moses', 'Jethro saw that Moses was judging the people alone and advised him to appoint capable, trustworthy leaders over groups of thousands, hundreds, fifties and tens.', 'Exodus 18:13-27', '{"difficulty":"beginner","case_title":"The Burden of One Judge","clues":["A leader sat from morning until evening hearing disputes brought by an entire nation.","His visiting father-in-law warned that the arrangement would exhaust both the leader and the people.","The advice was to appoint capable, God-fearing and trustworthy men over smaller groups, leaving only the hardest cases for the leader."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-9-1"}'::jsonb),
('bible-detective-l9-c2', 'bible-detective', 9, 2, 'CASE FILE 042: The Guests Who Would Not Drink
Investigate the evidence and identify the biblical event or group.', ARRAY['The Rechabites Refuse Wine', 'The Nazirites'' Vow', 'The Priests'' Refusal of Defiled Food', 'The Israelites at Marah']::text[], 'The Rechabites Refuse Wine', 'The Rechabites refused wine because their ancestor Jonadab had instructed them not to drink it or settle in houses; the LORD used their obedience as a contrast to Judah''s disobedience.', 'Jeremiah 35:1-19', '{"difficulty":"beginner","case_title":"The Guests Who Would Not Drink","clues":["A prophet invited members of a family clan into a chamber in the house of the LORD and set cups of wine before them.","They refused, explaining that their ancestor Jonadab son of Rechab had commanded them not to drink wine, build houses, sow seed or plant vineyards, but to live in tents.","The LORD used their obedience to their ancestor as a rebuke to Judah for refusing to listen to his commands."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-9-2"}'::jsonb),
('bible-detective-l9-c3', 'bible-detective', 9, 3, 'CASE FILE 043: A prophet''s marriage became a sign about Israel''s unfaithfulness. Identify the person or event from the evidence.', ARRAY['Malachi', 'Amos', 'Micah', 'Hosea']::text[], 'Hosea', 'Hosea''s relationship with Gomer illustrated God''s love for unfaithful Israel.', 'Hosea 1:2; 3:1-5', '{"difficulty":"beginner","case_title":"A prophet''s marriage became a sign about Israel''s unfaithfulness","clues":["Evidence A — The prophet was told to marry a woman associated with unfaithfulness.","Evidence B — He later bought her back for fifteen pieces of silver and barley.","Evidence C — Her restoration illustrated the LORD''s continuing love for an unfaithful people."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-43"}'::jsonb),
('bible-detective-l9-c4', 'bible-detective', 9, 4, 'CASE FILE 044: The Riders Among the Myrtle Trees
Investigate the evidence and identify the biblical event or person.', ARRAY['Elijah''s Vision at Horeb', 'Zechariah''s Four Horns and Craftsmen', 'The Vision of the Flying Scroll', 'Zechariah''s Horsemen Vision']::text[], 'Zechariah''s Horsemen Vision', 'Zechariah saw a rider on a red horse among myrtle trees, with other coloured horses behind him; the vision brought a message that the LORD would again show mercy to Jerusalem.', 'Zechariah 1:7-17', '{"difficulty":"beginner","case_title":"The Riders Among the Myrtle Trees","clues":["A prophet received a night vision in the eleventh month of the second year of Darius.","A rider on a red horse stood among myrtle trees in a ravine, with red, sorrel and white horses behind him.","The angel asked how long Jerusalem would remain without mercy, and the LORD answered with words of comfort and promised restoration."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-9-4"}'::jsonb),
('bible-detective-l9-c5', 'bible-detective', 9, 5, 'CASE FILE 045: The Defective Offering
Investigate the evidence and identify the biblical event or person.', ARRAY['Samuel Rebukes Saul''s Sacrifice', 'Malachi Rebukes Defective Offerings', 'Haggai Rebukes the Neglected Temple', 'Amos Condemns Dishonest Scales']::text[], 'Malachi Rebukes Defective Offerings', 'Malachi rebuked priests who brought blind, lame and sick animals to the altar, asking whether a human governor would accept such a gift.', 'Malachi 1:6-14', '{"difficulty":"beginner","case_title":"The Defective Offering","clues":["A prophet addressed priests who treated the LORD''s name with contempt while claiming to honour him.","The offerings brought to the altar included blind, lame and sick animals.","The prophet asked whether the governor would accept such a gift and declared that the LORD''s name would be great among the nations."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-9-5"}'::jsonb),
('bible-detective-l10-c1', 'bible-detective', 10, 1, 'CASE FILE 046: The One Who Returned
Investigate the evidence and identify the biblical event or person.', ARRAY['The Grateful Leper at Bethany', 'The Centurion Who Asked for Healing', 'The Samaritan Who Returned to Give Thanks', 'The Samaritan Woman at the Well']::text[], 'The Samaritan Who Returned to Give Thanks', 'Jesus healed ten men with a skin disease as they went to show themselves to the priests, but only one returned to thank him, and he was a Samaritan.', 'Luke 17:11-19', '{"difficulty":"beginner","case_title":"The One Who Returned","clues":["Ten men with a skin disease stood at a distance and called to Jesus for mercy.","Jesus told them to go and show themselves to the priests; they were cleansed while travelling.","Only one returned, praising God loudly, fell at Jesus'' feet and gave thanks—and the narrator identifies his nationality."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-10-1"}'::jsonb),
('bible-detective-l10-c2', 'bible-detective', 10, 2, 'CASE FILE 047: A prisoner made a governor tremble but remained detained for money. Identify the person or event from the evidence.', ARRAY['Felix', 'Gallio', 'Agrippa', 'Festus']::text[], 'Felix', 'Felix trembled at Paul''s message and hoped for a bribe, leaving Paul imprisoned.', 'Acts 24:24-27', '{"difficulty":"beginner","case_title":"A prisoner made a governor tremble but remained detained for money","clues":["Evidence A — The prisoner spoke about righteousness, self-control and judgment.","Evidence B — The governor became afraid but sent for him repeatedly.","Evidence C — The governor hoped the prisoner would offer him money for release."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-47"}'::jsonb),
('bible-detective-l10-c3', 'bible-detective', 10, 3, 'CASE FILE 048: A crowd in a Greek city shouted for nearly two hours over a goddess. Identify the person or event from the evidence.', ARRAY['Alexander', 'Demetrius', 'Eutychus', 'Tychicus']::text[], 'Demetrius', 'Demetrius stirred the Ephesian riot because Christian preaching threatened his idol-making trade.', 'Acts 19:23-41', '{"difficulty":"beginner","case_title":"A crowd in a Greek city shouted for nearly two hours over a goddess","clues":["Evidence A — A silversmith made silver shrines and feared loss of trade.","Evidence B — He gathered craftsmen and stirred public anger against the missionaries.","Evidence C — The crowd filled the theatre and repeatedly shouted the greatness of Artemis."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-48"}'::jsonb),
('bible-detective-l10-c4', 'bible-detective', 10, 4, 'CASE FILE 049: The Commander Who Fell at Hebron
Investigate the evidence and identify the biblical event or person.', ARRAY['Abner Kills Asahel', 'Joab Murders Abner', 'Ish-bosheth Is Murdered', 'Amasa Is Killed by Joab']::text[], 'Joab Murders Abner', 'Joab secretly called Abner back to Hebron and killed him in revenge for the death of his brother Asahel; David publicly mourned Abner.', '2 Samuel 3:22-39', '{"difficulty":"beginner","case_title":"The Commander Who Fell at Hebron","clues":["A military commander had just left David after negotiating the transfer of Israel''s allegiance.","Another commander sent messengers to bring him back and met him privately at the city gate.","The returning commander was killed in revenge for Asahel, and the king ordered mourning rather than celebrating the death."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-10-4"}'::jsonb),
('bible-detective-l10-c5', 'bible-detective', 10, 5, 'CASE FILE 050: A prisoner survived a shipwreck and a snakebite on the same island. Identify the person or event from the evidence.', ARRAY['Julius', 'Luke', 'Aristarchus', 'Paul']::text[], 'Paul', 'Paul survived the shipwreck and was unharmed by a viper on Malta.', 'Acts 27:39-44; 28:1-6', '{"difficulty":"beginner","case_title":"A prisoner survived a shipwreck and a snakebite on the same island","clues":["Evidence A — A ship carrying prisoners ran aground and broke apart.","Evidence B — The islanders welcomed the survivors and built a fire.","Evidence C — A viper fastened onto a prisoner''s hand, but he shook it into the fire and suffered no harm."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-50"}'::jsonb)
ON CONFLICT (game_slug, level, challenge_index) DO UPDATE SET
  question_key = EXCLUDED.question_key,
  question_text = EXCLUDED.question_text,
  options = EXCLUDED.options,
  correct_answer = EXCLUDED.correct_answer,
  explanation = EXCLUDED.explanation,
  reference = EXCLUDED.reference,
  metadata = EXCLUDED.metadata;

INSERT INTO public.game_content (
  question_key, game_slug, level, challenge_index, question_text,
  options, correct_answer, explanation, reference, metadata
) VALUES
('bible-detective-l11-c1', 'bible-detective', 11, 1, 'CASE FILE 051: The Captive King Who Prayed
Investigate the evidence and identify the biblical event or person.', ARRAY['Nebuchadnezzar''s Humbling', 'Hezekiah''s Prayer during the Assyrian Siege', 'Ahab''s Repentance after Naboth''s Vineyard', 'Manasseh''s Repentance']::text[], 'Manasseh''s Repentance', 'After being taken captive to Babylon, Manasseh humbled himself and prayed; God restored him to Jerusalem, where he removed foreign worship objects and restored the altar.', '2 Chronicles 33:10-17', '{"difficulty":"easy","case_title":"The Captive King Who Prayed","clues":["A king repeatedly ignored warnings from the LORD, and the Assyrian army captured him with hooks and bronze chains.","In distress in a foreign place, he humbled himself greatly and prayed to the God of his ancestors.","After being returned to Jerusalem, he removed foreign gods and repaired the altar of the LORD."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-11-1"}'::jsonb),
('bible-detective-l11-c2', 'bible-detective', 11, 2, 'CASE FILE 052: The Hand Reaching for the Sacred Chest. Examine all three clues and identify the biblical account.', ARRAY['Uzzah Touches the Ark', 'Ahio Falls from the Cart', 'Obed-Edom Receives the Ark', 'Nadab Touches the Altar']::text[], 'Uzzah Touches the Ark', 'Uzzah touched the ark when the oxen stumbled and died; David named the place Perez-uzzah.', '2 Samuel 6:1-8; 1 Chronicles 13:9-11', '{"difficulty":"easy","case_title":"The Hand Reaching for the Sacred Chest","clues":["Evidence A — The ark was being transported on a new cart.","Evidence B — When the oxen stumbled, a man reached out to steady it.","Evidence C — He died immediately, and the place was named for the breach."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-52"}'::jsonb),
('bible-detective-l11-c3', 'bible-detective', 11, 3, 'CASE FILE 053: The Household Shrine and the Wandering Levite
Investigate the evidence and identify the biblical event or person.', ARRAY['Micah''s Shrine and the Levite', 'The House of the Rechabites', 'The Danites Capture Laish', 'Gideon''s Ephod']::text[], 'Micah''s Shrine and the Levite', 'Micah''s mother dedicated silver, a carved image and a cast idol were made, and a wandering Levite from Bethlehem in Judah became Micah''s household priest.', 'Judges 17:1-13', '{"difficulty":"easy","case_title":"The Household Shrine and the Wandering Levite","clues":["A man from the hill country of Ephraim confessed that he had taken a large sum of silver from his mother.","The silver was partly given to a craftsman, who made a carved image and a cast idol for the household.","A young Levite from Bethlehem in Judah was hired as priest, and the household assumed this arrangement would bring prosperity."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-11-3"}'::jsonb),
('bible-detective-l11-c4', 'bible-detective', 11, 4, 'CASE FILE 054: The Watcher at the Rock of the Goats. Examine all three clues and identify the biblical account.', ARRAY['Bathsheba Mourns Uriah', 'Michal Hides David''s Image', 'Rizpah Guards Saul''s Descendants', 'Abigail Mourns Nabal']::text[], 'Rizpah Guards Saul''s Descendants', 'Rizpah protected the exposed bodies; David later gathered the bones for burial.', '2 Samuel 21:1-14', '{"difficulty":"easy","case_title":"The Watcher at the Rock of the Goats","clues":["Evidence A — Seven male descendants of Saul and two sons of Rizpah were handed over after a famine.","Evidence B — Their bodies were exposed during the harvest season.","Evidence C — A woman guarded them from birds by day and beasts by night until rain fell."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-54"}'::jsonb),
('bible-detective-l11-c5', 'bible-detective', 11, 5, 'CASE FILE 055: The Taste That Broke a Military Oath. Examine all three clues and identify the biblical account.', ARRAY['Elijah Eats Bread from an Angel', 'David Eats the Showbread', 'Jonathan Eats Honey During Saul''s Oath', 'Samson Eats Honey from a Lion']::text[], 'Jonathan Eats Honey During Saul''s Oath', 'Jonathan unknowingly violated Saul''s oath by tasting honey; the people rescued him.', '1 Samuel 14:24-45', '{"difficulty":"easy","case_title":"The Taste That Broke a Military Oath","clues":["Evidence A — Saul placed his troops under a curse: no one was to eat before evening.","Evidence B — His son had not heard the oath and tasted honey with his staff.","Evidence C — The soldiers intervened when Saul sought to put his son to death."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-55"}'::jsonb),
('bible-detective-l12-c1', 'bible-detective', 12, 1, 'CASE FILE 056: The Chest with a Hole in Its Lid. Examine all three clues and identify the biblical account.', ARRAY['Hezekiah Cleanses the Temple', 'Joash Repairs the Temple', 'Josiah Repairs the Temple', 'Nehemiah Repairs Jerusalem''s Wall']::text[], 'Joash Repairs the Temple', 'Jehoiada arranged a collection chest to fund temple repairs during Joash''s reign.', '2 Kings 12:4-16; 2 Chronicles 24:4-14', '{"difficulty":"easy","case_title":"The Chest with a Hole in Its Lid","clues":["Evidence A — A king ordered repairs to the neglected temple.","Evidence B — A priest placed a chest beside the altar with a hole bored in its lid.","Evidence C — The money was counted and given to trusted workers for repairs."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-56"}'::jsonb),
('bible-detective-l12-c2', 'bible-detective', 12, 2, 'CASE FILE 057: The Throne Room Filled with Deception. Examine all three clues and identify the biblical account.', ARRAY['Micaiah''s Vision Before Ahab', 'Isaiah''s Vision of the Seraphim', 'Elijah''s Contest on Carmel', 'Elisha''s Vision of the Chariots']::text[], 'Micaiah''s Vision Before Ahab', 'Micaiah son of Imlah described the heavenly council and lying spirit before Ahab''s final battle.', '1 Kings 22:13-28; 2 Chronicles 18:18-27', '{"difficulty":"easy","case_title":"The Throne Room Filled with Deception","clues":["Evidence A — A king wanted to attack Ramoth-gilead and gathered prophets.","Evidence B — One prophet described a heavenly council discussing how to entice the king.","Evidence C — A spirit volunteered to become a lying spirit in the mouths of the king''s prophets."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-57"}'::jsonb),
('bible-detective-l12-c3', 'bible-detective', 12, 3, 'CASE FILE 058: The Fleet That Never Reached Its Destination. Examine all three clues and identify the biblical account.', ARRAY['Solomon''s Fleet at Ezion-geber', 'Hiram''s Ships to Ophir', 'Jonah''s Ship to Tarshish', 'Jehoshaphat''s Failed Fleet']::text[], 'Jehoshaphat''s Failed Fleet', 'Jehoshaphat''s alliance with Ahaziah ended with the ships being wrecked at Ezion-geber.', '1 Kings 22:48-49; 2 Chronicles 20:35-37', '{"difficulty":"easy","case_title":"The Fleet That Never Reached Its Destination","clues":["Evidence A — Two kings formed an alliance to build merchant ships at a Red Sea port.","Evidence B — A prophet rebuked the alliance because one king had joined an ungodly ruler.","Evidence C — The ships were wrecked before they could sail to Tarshish."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-58"}'::jsonb),
('bible-detective-l12-c4', 'bible-detective', 12, 4, 'CASE FILE 059: The Commander Anointed in a Private Room. Examine all three clues and identify the biblical account.', ARRAY['David Is Anointed at Bethlehem', 'Solomon Is Anointed at Gihon', 'Jehu Is Anointed King', 'Hazael Is Anointed King of Aram']::text[], 'Jehu Is Anointed King', 'A young prophet anointed Jehu and declared that he would become king over Israel.', '2 Kings 9:1-13', '{"difficulty":"easy","case_title":"The Commander Anointed in a Private Room","clues":["Evidence A — A young prophet was sent to Ramoth-gilead.","Evidence B — He took a commander into an inner room, poured oil on his head and delivered a message.","Evidence C — The newly anointed commander drove away in his chariot, described as driving furiously."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-59"}'::jsonb),
('bible-detective-l12-c5', 'bible-detective', 12, 5, 'CASE FILE 060: The Queen Who Tried to Erase the Royal Family. Examine all three clues and identify the biblical account.', ARRAY['Herodias'' Plot Against John', 'Jezebel''s Threat Against Elijah', 'Athaliah''s Attempt to Destroy the Royal Heirs', 'Vashti''s Removal from the Palace']::text[], 'Athaliah''s Attempt to Destroy the Royal Heirs', 'Athaliah seized power, but Jehosheba hid Joash and Jehoiada later crowned him.', '2 Kings 11:1-16; 2 Chronicles 22:10-23:15', '{"difficulty":"easy","case_title":"The Queen Who Tried to Erase the Royal Family","clues":["Evidence A — After her son died, a queen ordered the royal heirs destroyed.","Evidence B — A princess rescued one infant prince and hid him in the temple.","Evidence C — After six years, a priest presented and crowned the child, then removed the queen."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-60"}'::jsonb),
('bible-detective-l13-c1', 'bible-detective', 13, 1, 'CASE FILE 061: The Feast Using Stolen Temple Vessels. Examine all three clues and identify the biblical account.', ARRAY['Cyrus'' Feast for the Returnees', 'Nebuchadnezzar''s Golden Image', 'Darius'' Decree Against Prayer', 'Belshazzar''s Feast and the Handwriting']::text[], 'Belshazzar''s Feast and the Handwriting', 'Belshazzar profaned the temple vessels; the writing announced the end of his kingdom.', 'Daniel 5:1-31', '{"difficulty":"easy","case_title":"The Feast Using Stolen Temple Vessels","clues":["Evidence A — A ruler hosted a feast for a thousand nobles.","Evidence B — He ordered vessels taken from Jerusalem''s temple to be brought to the banquet.","Evidence C — A hand wrote on the palace wall; the wise men could not interpret it."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-61"}'::jsonb),
('bible-detective-l13-c2', 'bible-detective', 13, 2, 'CASE FILE 062: The Tree That Reached the Sky in a King''s Dream. Examine all three clues and identify the biblical account.', ARRAY['Joseph''s Dream of the Sheaves', 'Nebuchadnezzar''s Dream of the Great Tree', 'Pharaoh''s Dream of the Seven Cows', 'Daniel''s Vision of Four Beasts']::text[], 'Nebuchadnezzar''s Dream of the Great Tree', 'Daniel interpreted the tree as Nebuchadnezzar, whose pride led to humiliation until he acknowledged God.', 'Daniel 4:4-37', '{"difficulty":"easy","case_title":"The Tree That Reached the Sky in a King''s Dream","clues":["Evidence A — A king saw a great tree providing shelter and food.","Evidence B — A heavenly watcher ordered it cut down but left its stump bound.","Evidence C — Daniel interpreted the tree as the king, who would live like an animal until acknowledging heaven''s rule."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-62"}'::jsonb),
('bible-detective-l13-c3', 'bible-detective', 13, 3, 'CASE FILE 063: The Fourth Figure in the Furnace. Examine all three clues and identify the biblical account.', ARRAY['Elijah on Mount Carmel', 'The Three Hebrews in the Fiery Furnace', 'Daniel in the Lions'' Den', 'The Maccabees in the Furnace']::text[], 'The Three Hebrews in the Fiery Furnace', 'Shadrach, Meshach and Abednego were preserved in the furnace; the king saw a fourth figure.', 'Daniel 3:1-30', '{"difficulty":"easy","case_title":"The Fourth Figure in the Furnace","clues":["Evidence A — Three Judean officials refused to bow to a golden image.","Evidence B — The furnace was heated seven times hotter than usual; the king saw four figures walking inside.","Evidence C — The men emerged without the smell of fire on their clothes."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-63"}'::jsonb),
('bible-detective-l13-c4', 'bible-detective', 13, 4, 'CASE FILE 064: The Rusted Cooking Pot
Investigate the evidence and identify the biblical event or person.', ARRAY['Ezekiel''s Parable of the Boiling Pot', 'The Bronze Basin of the Tabernacle', 'Zechariah''s Ephah Vision', 'Jeremiah''s Potter''s Vessel']::text[], 'Ezekiel''s Parable of the Boiling Pot', 'Ezekiel''s boiling-pot sign represented Jerusalem: the choice pieces were placed in the pot, but its corrosion and bloodguilt could not be removed by ordinary cleansing.', 'Ezekiel 24:1-14', '{"difficulty":"easy","case_title":"The Rusted Cooking Pot","clues":["The prophet received a dated message on the tenth day of the tenth month in the ninth year.","He was told to set a pot on the fire, pour in water and place choice pieces of meat and bones inside it.","Even after the pot was emptied and heated, its rust remained; the sign was applied to the bloodguilt of a city."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-13-4"}'::jsonb),
('bible-detective-l13-c5', 'bible-detective', 13, 5, 'CASE FILE 065: The Prophet Measuring a Wall. Examine all three clues and identify the biblical account.', ARRAY['Zechariah''s Flying Scroll', 'Jeremiah''s Potter''s Vessel', 'Ezekiel''s Measuring Reed', 'Amos'' Vision of the Plumb Line']::text[], 'Amos'' Vision of the Plumb Line', 'Amos saw the LORD holding a plumb line, symbolising that Israel would be measured and judged.', 'Amos 7:7-9', '{"difficulty":"easy","case_title":"The Prophet Measuring a Wall","clues":["Evidence A — A prophet saw the LORD standing beside a wall with a measuring tool.","Evidence B — The LORD declared that the standard would no longer be passed over.","Evidence C — The vision announced judgment on Jeroboam''s house and Israel''s sanctuary."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-65"}'::jsonb),
('bible-detective-l14-c1', 'bible-detective', 14, 1, 'CASE FILE 066: The Linen Belt Hidden Beside a River. Examine all three clues and identify the biblical account.', ARRAY['Jeremiah''s Ruined Linen Belt', 'Hosea''s Bought Garment', 'Ezekiel''s Leather Belt', 'Isaiah''s Torn Robe']::text[], 'Jeremiah''s Ruined Linen Belt', 'Jeremiah''s ruined linen belt symbolised how Judah had clung to pride instead of the LORD.', 'Jeremiah 13:1-11', '{"difficulty":"easy","case_title":"The Linen Belt Hidden Beside a River","clues":["Evidence A — A prophet bought a linen belt and wore it without washing it.","Evidence B — He hid it in a rock crevice beside a river and retrieved it later.","Evidence C — It had become ruined, illustrating Judah''s pride and unfaithfulness."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-66"}'::jsonb),
('bible-detective-l14-c2', 'bible-detective', 14, 2, 'CASE FILE 067: The Potter''s Vessel That Could Be Remade. Examine all three clues and identify the biblical account.', ARRAY['Ezekiel''s Valley of Dry Bones', 'Jeremiah at the Potter''s House', 'Amos'' Basket of Summer Fruit', 'Zechariah''s Ephah Vision']::text[], 'Jeremiah at the Potter''s House', 'Jeremiah watched a potter remake a spoiled vessel, illustrating God''s authority and the possibility of repentance.', 'Jeremiah 18:1-10', '{"difficulty":"easy","case_title":"The Potter''s Vessel That Could Be Remade","clues":["Evidence A — A prophet was told to visit a craftsman''s workshop.","Evidence B — A vessel was spoiled in the potter''s hands, so he formed it into another vessel.","Evidence C — The LORD used the scene to explain his authority over nations and his call to repentance."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-67"}'::jsonb),
('bible-detective-l14-c3', 'bible-detective', 14, 3, 'CASE FILE 068: The Scroll Read, Cut and Burned. Examine all three clues and identify the biblical account.', ARRAY['Jehoiakim Burns Jeremiah''s Scroll', 'Belshazzar Reads the Writing', 'Josiah Finds the Book of the Law', 'Zedekiah Breaks Jeremiah''s Yoke']::text[], 'Jehoiakim Burns Jeremiah''s Scroll', 'Baruch wrote Jeremiah''s words; Jehoiakim cut and burned the scroll, and another was prepared.', 'Jeremiah 36:1-32', '{"difficulty":"easy","case_title":"The Scroll Read, Cut and Burned","clues":["Evidence A — A prophet dictated messages to a scribe who wrote them on a scroll.","Evidence B — An official read it before the king, who cut each section and burned it.","Evidence C — The king''s officials urged him not to destroy the message, but he refused."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-68"}'::jsonb),
('bible-detective-l14-c4', 'bible-detective', 14, 4, 'CASE FILE 069: The Rescue from the Muddy Cistern. Examine all three clues and identify the biblical account.', ARRAY['Jonathan Rescues David', 'Ebed-melech Rescues Jeremiah', 'Nehemiah Rescues the Poor', 'Baruch Rescues Jeremiah''s Scroll']::text[], 'Ebed-melech Rescues Jeremiah', 'Ebed-melech the Cushite rescued Jeremiah from the cistern using ropes and worn cloths.', 'Jeremiah 38:1-13', '{"difficulty":"easy","case_title":"The Rescue from the Muddy Cistern","clues":["Evidence A — A prophet was lowered into a cistern because officials opposed his message.","Evidence B — A foreign court official heard he would die there and approached the king.","Evidence C — He used old rags beneath ropes to lift the prophet without injuring him."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-69"}'::jsonb),
('bible-detective-l14-c5', 'bible-detective', 14, 5, 'CASE FILE 070: The Night Inspection of Broken Gates. Examine all three clues and identify the biblical account.', ARRAY['Zerubbabel Surveys the Temple', 'Ezra Inspects the Temple Vessels', 'Nehemiah Inspects Jerusalem''s Walls', 'Sanballat Inspects the Gates']::text[], 'Nehemiah Inspects Jerusalem''s Walls', 'Nehemiah inspected Jerusalem''s broken walls at night before calling the people to rebuild.', 'Nehemiah 2:11-20', '{"difficulty":"easy","case_title":"The Night Inspection of Broken Gates","clues":["Evidence A — A returning exile arrived in Jerusalem and initially kept his mission private.","Evidence B — He rode out at night to inspect damaged gates and walls; rubble blocked his animal.","Evidence C — He organised families and workers to rebuild despite threats and mockery."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-70"}'::jsonb),
('bible-detective-l15-c1', 'bible-detective', 15, 1, 'CASE FILE 071: The Law Read from Dawn Until Midday. Examine all three clues and identify the biblical account.', ARRAY['Moses Reads the Law at Sinai', 'Josiah Reads the Covenant Scroll', 'Jehoiada Reads the Royal Covenant', 'Ezra Reads the Law to the People']::text[], 'Ezra Reads the Law to the People', 'Ezra read the Law publicly while Levites helped the people understand its meaning.', 'Nehemiah 8:1-12', '{"difficulty":"easy","case_title":"The Law Read from Dawn Until Midday","clues":["Evidence A — A returned community gathered in an open square before the Water Gate.","Evidence B — A scribe stood on a wooden platform and read the Law from early morning until midday.","Evidence C — Levites explained its meaning so the people could understand."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-71"}'::jsonb),
('bible-detective-l15-c2', 'bible-detective', 15, 2, 'CASE FILE 072: The Panelled Houses and the Neglected Temple. Examine all three clues and identify the biblical account.', ARRAY['Malachi Rebukes the Priests', 'Zechariah Rebukes the Governors', 'Amos Rebukes the Merchants', 'Haggai Rebukes the Returned Exiles']::text[], 'Haggai Rebukes the Returned Exiles', 'Haggai rebuked the people for neglecting the temple while prioritising their own houses.', 'Haggai 1:1-15', '{"difficulty":"easy","case_title":"The Panelled Houses and the Neglected Temple","clues":["Evidence A — A prophet challenged returned exiles for living in panelled houses while the LORD''s house lay desolate.","Evidence B — Their wages seemed to disappear like money in a bag with holes.","Evidence C — He called them to consider their ways and resume temple work."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-72"}'::jsonb),
('bible-detective-l15-c3', 'bible-detective', 15, 3, 'CASE FILE 073: The Belt Used to Predict an Arrest. Examine all three clues and identify the biblical account.', ARRAY['Agabus Predicts Paul''s Arrest', 'Silas Predicts the Famine', 'Philip Predicts the Shipwreck', 'Ananias Predicts Paul''s Blindness']::text[], 'Agabus Predicts Paul''s Arrest', 'Agabus used Paul''s belt to act out the announced arrest awaiting Paul in Jerusalem.', 'Acts 21:8-14', '{"difficulty":"easy","case_title":"The Belt Used to Predict an Arrest","clues":["Evidence A — A prophet travelled from Judea to a gathering of believers.","Evidence B — He took a belt, bound his own hands and feet, and announced what awaited its owner.","Evidence C — The warning concerned imprisonment and delivery into Gentile hands."],"investigation_type":"multi_evidence_case","fact_key":"detective-case-73"}'::jsonb),
('bible-detective-l15-c4', 'bible-detective', 15, 4, 'CASE FILE 074: The Name the Exorcists Tried to Borrow
Investigate the evidence and identify the biblical event or person.', ARRAY['The Seven Deacons in Jerusalem', 'The Sons of Sceva in Ephesus', 'Simon the Sorcerer in Samaria', 'Elymas the Magician in Paphos']::text[], 'The Sons of Sceva in Ephesus', 'Seven sons of Sceva tried to invoke Jesus by using the name preached by Paul; the possessed man overpowered them, and many believers later burned their magic books.', 'Acts 19:11-20', '{"difficulty":"easy","case_title":"The Name the Exorcists Tried to Borrow","clues":["Extraordinary miracles were being performed through Paul in a major city of Asia.","Some itinerant Jewish exorcists tried to use the name of Jesus as a formula, although they did not belong to the group following him.","The man with the evil spirit overpowered them; fear spread, and many who practised magic publicly burned their books."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-15-4"}'::jsonb),
('bible-detective-l15-c5', 'bible-detective', 15, 5, 'CASE FILE 075: The Farewell at Miletus
Investigate the evidence and identify the biblical event or person.', ARRAY['Peter''s Farewell to the Jerusalem Church', 'Paul''s Defence before Agrippa', 'Paul''s Farewell to the Ephesian Elders', 'John''s Message to the Seven Churches']::text[], 'Paul''s Farewell to the Ephesian Elders', 'Paul summoned the elders of the Ephesian church to Miletus, warned them about fierce wolves, prayed with them and said they would not see his face again.', 'Acts 20:17-38', '{"difficulty":"easy","case_title":"The Farewell at Miletus","clues":["A travelling apostle sent for the elders of a church while his ship waited at a coastal city.","He reviewed his ministry among them, recalling humility, tears and trials, and warned that destructive teachers would arise after his departure.","The meeting ended with kneeling prayer, tears, embraces and grief because he had said they would not see him again."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-15-5"}'::jsonb),
('bible-detective-l16-c1', 'bible-detective', 16, 1, 'CASE FILE 76: Rachel''s Hidden Household Gods. Review the evidence and identify the biblical account.', ARRAY['Michal Hides David''s Image', 'Leah Hides Jacob''s Staff', 'Rachel Hides Laban''s Household Gods', 'Rebekah Takes Laban''s Idols']::text[], 'Rachel Hides Laban''s Household Gods', 'Rachel had taken her father''s household gods and concealed them in the camel''s saddle.', 'Genesis 31:19-35', '{"difficulty":"easy","case_title":"Rachel''s Hidden Household Gods","clues":["Evidence A — A household image was concealed beneath a camel''s saddle.","Evidence B — The searcher asked why the woman did not rise from her seat.","Evidence C — The image was found during the search."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-76"}'::jsonb),
('bible-detective-l16-c2', 'bible-detective', 16, 2, 'CASE FILE 77: The Seven Ewe Lambs. Review the evidence and identify the biblical account.', ARRAY['Isaac''s Wells at Gerar', 'Jacob''s Covenant at Mizpah', 'Abimelech''s Treaty at Shechem', 'Abraham''s Covenant at Beersheba']::text[], 'Abraham''s Covenant at Beersheba', 'Abraham and Abimelech made a covenant at Beersheba; seven ewe lambs witnessed Abraham''s claim to the well.', 'Genesis 21:22-34', '{"difficulty":"easy","case_title":"The Seven Ewe Lambs","clues":["Evidence A — A patriarch and a Philistine king disputed over a well.","Evidence B — The patriarch set aside seven ewe lambs as a witness.","Evidence C — The place received a name connected with an oath and a well."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-77"}'::jsonb),
('bible-detective-l16-c3', 'bible-detective', 16, 3, 'CASE FILE 78: The Stolen Blessing Exposed. Review the evidence and identify the biblical account.', ARRAY['Laban Discovers Rachel''s Flight', 'Jacob Discovers Laban''s Deception', 'Isaac Discovers Jacob''s Deception', 'Esau Discovers Joseph''s Coat']::text[], 'Isaac Discovers Jacob''s Deception', 'Isaac realised Jacob had received the blessing intended for Esau.', 'Genesis 27:30-40', '{"difficulty":"easy","case_title":"The Stolen Blessing Exposed","clues":["Evidence A — A blind patriarch discovered that he had blessed the younger twin.","Evidence B — The elder son arrived with game after the blessing had already been given.","Evidence C — The father trembled when he realised the deception."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-78"}'::jsonb),
('bible-detective-l16-c4', 'bible-detective', 16, 4, 'CASE FILE 79: The Servant at the Well. Review the evidence and identify the biblical account.', ARRAY['Rebekah Meets Abraham''s Servant', 'Zipporah Meets Moses at Midian', 'Leah Meets Jacob at Haran', 'Rachel Meets Jacob at the Well']::text[], 'Rebekah Meets Abraham''s Servant', 'Rebekah watered the servant''s camels and was identified as the answer to his prayer for a wife for Isaac.', 'Genesis 24:10-27', '{"difficulty":"easy","case_title":"The Servant at the Well","clues":["Evidence A — A servant prayed for a sign while seeking a wife for his master''s son.","Evidence B — A young woman offered to draw water for him and his camels.","Evidence C — The servant gave her a nose ring and bracelets before learning her family."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-79"}'::jsonb),
('bible-detective-l16-c5', 'bible-detective', 16, 5, 'CASE FILE 80: The Stairway at Bethel. Review the evidence and identify the biblical account.', ARRAY['Solomon''s Dream at Gibeon', 'Nebuchadnezzar''s Dream of the Statue', 'Jacob''s Dream at Bethel', 'Joseph''s Dream of the Sheaves']::text[], 'Jacob''s Dream at Bethel', 'Jacob dreamed of a stairway between earth and heaven and named the place Bethel.', 'Genesis 28:10-22', '{"difficulty":"easy","case_title":"The Stairway at Bethel","clues":["Evidence A — A fugitive slept with a stone for a pillow.","Evidence B — He dreamed of a stairway reaching heaven with angels ascending and descending.","Evidence C — He named the place Bethel after waking."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-80"}'::jsonb),
('bible-detective-l17-c1', 'bible-detective', 17, 1, 'CASE FILE 81: The Wrestling at Daybreak. Review the evidence and identify the biblical account.', ARRAY['Esau Wrestles with an Angel', 'Jacob Wrestles at Peniel', 'Joshua Wrestles at Jericho', 'Moses Wrestles at Horeb']::text[], 'Jacob Wrestles at Peniel', 'Jacob wrestled until daybreak and was renamed Israel.', 'Genesis 32:22-32', '{"difficulty":"easy","case_title":"The Wrestling at Daybreak","clues":["Evidence A — A man wrestled through the night beside a river crossing.","Evidence B — His opponent touched his hip socket, leaving him limping.","Evidence C — He received a new name before meeting his brother."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-81"}'::jsonb),
('bible-detective-l17-c2', 'bible-detective', 17, 2, 'CASE FILE 82: The Forgotten Prisoner. Review the evidence and identify the biblical account.', ARRAY['Joseph Remembered by Pharaoh''s Cupbearer', 'Daniel Remembered by Nebuchadnezzar', 'Nehemiah Remembered by Artaxerxes', 'Mordecai Remembered by Ahasuerus']::text[], 'Joseph Remembered by Pharaoh''s Cupbearer', 'The cupbearer forgot Joseph until Pharaoh''s dreams created a need for an interpreter.', 'Genesis 40:9-23; 41:1-14', '{"difficulty":"easy","case_title":"The Forgotten Prisoner","clues":["Evidence A — A royal cupbearer was restored after a prison dream.","Evidence B — He promised to remember the interpreter but forgot him.","Evidence C — Two years later, Pharaoh''s troubling dreams brought the prisoner to mind."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-82"}'::jsonb),
('bible-detective-l17-c3', 'bible-detective', 17, 3, 'CASE FILE 83: The Bones Carried from Egypt. Review the evidence and identify the biblical account.', ARRAY['Aaron''s Bones Carried to Hebron', 'Jacob''s Bones Carried to Machpelah', 'Moses'' Bones Carried to Nebo', 'Joseph''s Bones Carried to Canaan']::text[], 'Joseph''s Bones Carried to Canaan', 'Joseph made Israel swear to carry his bones from Egypt; they were buried at Shechem.', 'Genesis 50:24-26; Exodus 13:19; Joshua 24:32', '{"difficulty":"easy","case_title":"The Bones Carried from Egypt","clues":["Evidence A — A dying patriarch made his son swear an oath about his burial.","Evidence B — Centuries later, a leader carried the patriarch''s remains during the Exodus.","Evidence C — The bones were eventually buried at Shechem."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-83"}'::jsonb),
('bible-detective-l17-c4', 'bible-detective', 17, 4, 'CASE FILE 084: The Foreigner in the Barley Field
Investigate the evidence and identify the biblical event or person.', ARRAY['Naomi Returns to Bethlehem', 'The Daughters of Zelophehad Gather Their Inheritance', 'Ruth Meets Boaz at the City Gate', 'Ruth Gleans in Boaz''s Field']::text[], 'Ruth Gleans in Boaz''s Field', 'Ruth gleaned behind the harvesters in Boaz''s field; Boaz protected her and instructed his workers to leave extra grain for her.', 'Ruth 2:1-23', '{"difficulty":"easy","case_title":"The Foreigner in the Barley Field","clues":["A Moabite widow went out to gather leftover grain so that she and her mother-in-law could eat.","The field belonged to a wealthy relative of her late father-in-law, who asked his workers about the unfamiliar woman.","The owner ordered his men not to molest her and to pull out extra stalks for her from the bundles."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-17-4"}'::jsonb),
('bible-detective-l17-c5', 'bible-detective', 17, 5, 'CASE FILE 85: The Staff That Blossomed. Review the evidence and identify the biblical account.', ARRAY['David''s Staff Defeats Goliath', 'Aaron''s Rod Buds', 'Balaam''s Staff Speaks', 'Moses'' Staff Becomes a Serpent']::text[], 'Aaron''s Rod Buds', 'Aaron''s staff budded, blossomed and produced almonds as God''s sign of his chosen priesthood.', 'Numbers 17:1-11', '{"difficulty":"easy","case_title":"The Staff That Blossomed","clues":["Evidence A — Tribal leaders submitted staffs to be placed before the testimony.","Evidence B — One staff produced buds, blossoms and ripe almonds overnight.","Evidence C — The staff was kept as a sign against future rebellion."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-85"}'::jsonb),
('bible-detective-l18-c1', 'bible-detective', 18, 1, 'CASE FILE 86: The Bronze Serpent. Review the evidence and identify the biblical account.', ARRAY['Aaron Makes the Golden Calf', 'Gideon Makes an Ephod', 'Moses Lifts the Bronze Serpent', 'Hezekiah Destroys the Bronze Serpent']::text[], 'Moses Lifts the Bronze Serpent', 'God instructed Moses to make a bronze serpent; those bitten who looked at it lived.', 'Numbers 21:4-9', '{"difficulty":"easy","case_title":"The Bronze Serpent","clues":["Evidence A — A wilderness camp was afflicted by venomous snakes.","Evidence B — A bronze image was lifted on a pole.","Evidence C — Those who looked toward it lived."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-86"}'::jsonb),
('bible-detective-l18-c2', 'bible-detective', 18, 2, 'CASE FILE 87: The Donkey That Saw the Angel. Review the evidence and identify the biblical account.', ARRAY['Balaam''s Donkey Speaks', 'Samson''s Foxes Speak', 'Elijah''s Ravens Speak', 'Gehazi''s Servant Sees Chariots']::text[], 'Balaam''s Donkey Speaks', 'Balaam''s donkey saw the angel and spoke after Balaam struck it.', 'Numbers 22:21-35', '{"difficulty":"easy","case_title":"The Donkey That Saw the Angel","clues":["Evidence A — A diviner travelled on an animal that suddenly turned aside three times.","Evidence B — The rider struck the animal, which then spoke.","Evidence C — The rider''s eyes were opened to see an angel blocking the road."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-87"}'::jsonb),
('bible-detective-l18-c3', 'bible-detective', 18, 3, 'CASE FILE 88: The Land East of Jordan. Review the evidence and identify the biblical account.', ARRAY['Reuben and Gad Request Land East of Jordan', 'Judah and Benjamin Request Hebron', 'Dan and Naphtali Request Bashan', 'Ephraim and Manasseh Request Shechem']::text[], 'Reuben and Gad Request Land East of Jordan', 'Reuben and Gad received land east of the Jordan after agreeing to fight alongside the other tribes.', 'Numbers 32:1-33', '{"difficulty":"easy","case_title":"The Land East of Jordan","clues":["Evidence A — Two tribes requested land east of the Jordan before Israel crossed.","Evidence B — Moses initially challenged their request as discouraging the other tribes.","Evidence C — They agreed to send armed men ahead of Israel before returning to their families."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-88"}'::jsonb),
('bible-detective-l18-c4', 'bible-detective', 18, 4, 'CASE FILE 89: The Cities of Refuge. Review the evidence and identify the biblical account.', ARRAY['The Cities of the Philistines Fortified', 'The Cities of Edom Rebuilt', 'The Levitical Cities Destroyed', 'The Cities of Refuge Established']::text[], 'The Cities of Refuge Established', 'The cities of refuge protected those who killed unintentionally until a proper hearing.', 'Numbers 35:9-34; Joshua 20:1-9', '{"difficulty":"easy","case_title":"The Cities of Refuge","clues":["Evidence A — A legal arrangement provided protection for someone who killed unintentionally.","Evidence B — The accused could flee to designated towns and stand before the congregation.","Evidence C — The arrangement distinguished accidental killing from murder."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-89"}'::jsonb),
('bible-detective-l18-c5', 'bible-detective', 18, 5, 'CASE FILE 90: The Commander with a Drawn Sword. Review the evidence and identify the biblical account.', ARRAY['David Meets the Angel at Araunah''s Threshing Floor', 'Joshua Meets the Commander of the LORD''s Army', 'Balaam Meets the Angel on the Road', 'Gideon Meets the Angel at Ophrah']::text[], 'Joshua Meets the Commander of the LORD''s Army', 'Joshua encountered the commander of the LORD''s army near Jericho and removed his sandals.', 'Joshua 5:13-15', '{"difficulty":"easy","case_title":"The Commander with a Drawn Sword","clues":["Evidence A — A leader approached a fortified city before its capture.","Evidence B — He saw a man with a drawn sword and asked whether he was for Israel or its enemies.","Evidence C — The man identified himself as commander of the LORD''s army and ordered him to remove his sandals."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-90"}'::jsonb),
('bible-detective-l19-c1', 'bible-detective', 19, 1, 'CASE FILE 91: The Treaty Made with Deception. Review the evidence and identify the biblical account.', ARRAY['The Gibeonites Deceive Israel', 'The Hivites Deceive Samson', 'The Moabites Deceive Gideon', 'The Amorites Deceive Deborah']::text[], 'The Gibeonites Deceive Israel', 'The Gibeonites deceived Israel into making a treaty by pretending to come from a distant land.', 'Joshua 9:3-27', '{"difficulty":"easy","case_title":"The Treaty Made with Deception","clues":["Evidence A — Visitors arrived wearing worn clothes and carrying mouldy provisions.","Evidence B — Israel''s leaders examined the provisions but failed to seek the LORD''s counsel.","Evidence C — The visitors were discovered to be neighbours from nearby towns."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-91"}'::jsonb),
('bible-detective-l19-c2', 'bible-detective', 19, 2, 'CASE FILE 92: The Sun Stands Still. Review the evidence and identify the biblical account.', ARRAY['Hezekiah''s Reversed Shadow', 'Moses'' Darkness over Egypt', 'Joshua''s Long Day', 'Elijah''s Drought at Carmel']::text[], 'Joshua''s Long Day', 'Joshua prayed during battle, and the sun and moon stood still until Israel''s victory.', 'Joshua 10:1-14', '{"difficulty":"easy","case_title":"The Sun Stands Still","clues":["Evidence A — A battle took place while Israel pursued a coalition of Amorite kings.","Evidence B — The commander called for the sun and moon to stand still.","Evidence C — The account says the day was prolonged until Israel completed its victory."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-92"}'::jsonb),
('bible-detective-l19-c3', 'bible-detective', 19, 3, 'CASE FILE 93: The Wise Woman at Abel. Review the evidence and identify the biblical account.', ARRAY['The Wise Woman of Abel Beth-maacah', 'Abigail of Carmel', 'The Shunammite Woman', 'The Woman of Tekoa']::text[], 'The Wise Woman of Abel Beth-maacah', 'A wise woman negotiated with Joab and persuaded the city to surrender Sheba.', '2 Samuel 20:14-22', '{"difficulty":"easy","case_title":"The Wise Woman at Abel","clues":["Evidence A — A woman was asked to surrender a fugitive who had taken refuge in her city.","Evidence B — She negotiated with the commander outside the wall.","Evidence C — The people delivered the fugitive''s head, and the army withdrew."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-93"}'::jsonb),
('bible-detective-l19-c4', 'bible-detective', 19, 4, 'CASE FILE 94: The Census and the Threshing Floor. Review the evidence and identify the biblical account.', ARRAY['Jeremiah Buys Hanamel''s Field', 'David Buys Araunah''s Threshing Floor', 'Abraham Buys Machpelah', 'Boaz Redeems Ruth''s Field']::text[], 'David Buys Araunah''s Threshing Floor', 'David bought Araunah''s threshing floor and built an altar after the plague was stopped.', '2 Samuel 24:10-25; 1 Chronicles 21:18-30', '{"difficulty":"easy","case_title":"The Census and the Threshing Floor","clues":["Evidence A — A king ordered a census and later regretted it.","Evidence B — A prophet offered him a choice of judgments.","Evidence C — The king bought a threshing floor and offered sacrifices there after the plague stopped."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-94"}'::jsonb),
('bible-detective-l19-c5', 'bible-detective', 19, 5, 'CASE FILE 95: The Queen Who Tested Solomon. Review the evidence and identify the biblical account.', ARRAY['The Queen of Sheba Visits Solomon', 'Jezebel Visits Elijah', 'Candace Visits Philip', 'Queen Vashti Visits Esther']::text[], 'The Queen of Sheba Visits Solomon', 'The Queen of Sheba tested Solomon with hard questions and praised his wisdom.', '1 Kings 10:1-13; 2 Chronicles 9:1-12', '{"difficulty":"easy","case_title":"The Queen Who Tested Solomon","clues":["Evidence A — A foreign monarch travelled with a large caravan and difficult questions.","Evidence B — She tested a king with riddles and observed his court and temple.","Evidence C — She praised the wisdom she had heard about and gave him gold and spices."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-95"}'::jsonb),
('bible-detective-l20-c1', 'bible-detective', 20, 1, 'CASE FILE 96: Saul''s Sacrifice at Gilgal. Review the evidence and identify the biblical account.', ARRAY['Solomon Offers at Gibeon', 'Jeroboam Offers at Bethel', 'David Offers at Araunah''s Threshing Floor', 'Saul Offers the Sacrifice at Gilgal']::text[], 'Saul Offers the Sacrifice at Gilgal', 'Saul offered the burnt offering at Gilgal instead of waiting for Samuel, and Samuel announced that his kingdom would not endure.', '1 Samuel 13:5-14', '{"difficulty":"easy","case_title":"Saul''s Sacrifice at Gilgal","clues":["Israel''s troops were scattered while a Philistine force gathered for battle.","A king waited for the prophet who was supposed to offer the sacrifice.","When the prophet delayed, the king offered it himself and was rebuked for not keeping God''s command."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l20-c1"}'::jsonb),
('bible-detective-l20-c2', 'bible-detective', 20, 2, 'CASE FILE 97: Hezekiah''s Water Tunnel. Review the evidence and identify the biblical account.', ARRAY['Uzziah Builds a Canal at Jericho', 'Solomon Builds the Pool of Siloam', 'Hezekiah Secures Jerusalem''s Water Supply', 'Nehemiah Diverts the Jordan']::text[], 'Hezekiah Secures Jerusalem''s Water Supply', 'Hezekiah strengthened Jerusalem''s water supply and brought the Gihon spring''s water through a tunnel.', '2 Kings 20:20; 2 Chronicles 32:1-8, 30', '{"difficulty":"easy","case_title":"Hezekiah''s Water Tunnel","clues":["A king prepared Jerusalem for an expected Assyrian attack.","He stopped the water sources outside the city and redirected a spring toward the city.","The water was brought through a tunnel to the western side of the city of David."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l20-c2"}'::jsonb),
('bible-detective-l20-c3', 'bible-detective', 20, 3, 'CASE FILE 98: The Heavenly Army at Dothan. Review the evidence and identify the biblical account.', ARRAY['Gideon and the Midianite Camp', 'Elisha and the Heavenly Army at Dothan', 'David and the Angel at Jerusalem', 'Elijah and the Chariot of Fire']::text[], 'Elisha and the Heavenly Army at Dothan', 'Elisha''s servant saw the mountain filled with heavenly horses and chariots of fire.', '2 Kings 6:8-23', '{"difficulty":"easy","case_title":"The Heavenly Army at Dothan","clues":["Evidence A — A foreign king sent troops to capture a prophet in a city.","Evidence B — The prophet''s servant saw the surrounding hills full of horses and chariots of fire.","Evidence C — The enemy soldiers were struck with blindness and led into the capital."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-98"}'::jsonb),
('bible-detective-l20-c4', 'bible-detective', 20, 4, 'CASE FILE 99: The King Who Found the Law. Review the evidence and identify the biblical account.', ARRAY['Josiah Hears the Book of the Law', 'Hezekiah Reads Isaiah''s Letter', 'Ezra Reads the Law at the Water Gate', 'Jehoiakim Burns Jeremiah''s Scroll']::text[], 'Josiah Hears the Book of the Law', 'Hilkiah found the book of the law; Josiah heard it and sought the LORD''s word through Huldah.', '2 Kings 22:8-20; 2 Chronicles 34:14-28', '{"difficulty":"easy","case_title":"The King Who Found the Law","clues":["Evidence A — A high priest found a book of the law during temple repairs.","Evidence B — A royal secretary read it to a king who tore his clothes.","Evidence C — The king sent officials to consult a prophetess about the words of the book."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-99"}'::jsonb),
('bible-detective-l20-c5', 'bible-detective', 20, 5, 'CASE FILE 100: The Prophet''s Three-Year Sign
Investigate the evidence and identify the biblical event or person.', ARRAY['Ezekiel''s Sign of the Siege Brick', 'Isaiah''s Sign Against Egypt and Cush', 'Jeremiah''s Yoke before the Nations', 'Hosea''s Marriage to Gomer']::text[], 'Isaiah''s Sign Against Egypt and Cush', 'Isaiah walked stripped and barefoot as a sign that Egypt and Cush would be led away captive by Assyria, stripped and barefoot.', 'Isaiah 20:1-6', '{"difficulty":"easy","case_title":"The Prophet''s Three-Year Sign","clues":["The sign was given in the year an Assyrian commander came to Ashdod.","The prophet was told to remove his sackcloth and sandals and then walked stripped and barefoot.","The sign pointed to the humiliation and captivity of Egypt and Cush at the hands of Assyria."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-20-5"}'::jsonb)
ON CONFLICT (game_slug, level, challenge_index) DO UPDATE SET
  question_key = EXCLUDED.question_key,
  question_text = EXCLUDED.question_text,
  options = EXCLUDED.options,
  correct_answer = EXCLUDED.correct_answer,
  explanation = EXCLUDED.explanation,
  reference = EXCLUDED.reference,
  metadata = EXCLUDED.metadata;

INSERT INTO public.game_content (
  question_key, game_slug, level, challenge_index, question_text,
  options, correct_answer, explanation, reference, metadata
) VALUES
('bible-detective-l21-c1', 'bible-detective', 21, 1, 'CASE FILE 101: The Prophet Who Ate a Scroll. Review the evidence and identify the biblical account.', ARRAY['John Eats the Little Scroll', 'Daniel Reads the Sealed Scroll', 'Jeremiah Eats the Book', 'Ezekiel Eats the Scroll']::text[], 'Ezekiel Eats the Scroll', 'Ezekiel ate the scroll before proclaiming God''s message.', 'Ezekiel 2:8-3:3', '{"difficulty":"intermediate","case_title":"The Prophet Who Ate a Scroll","clues":["Evidence A — A prophet saw a hand holding a scroll written on both sides.","Evidence B — He was told to eat it before speaking to the exiles.","Evidence C — It tasted sweet as honey in his mouth."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-101"}'::jsonb),
('bible-detective-l21-c2', 'bible-detective', 21, 2, 'CASE FILE 102: The Watchman of Israel. Review the evidence and identify the biblical account.', ARRAY['Amos Appointed as King', 'Isaiah Appointed as Temple Singer', 'Jeremiah Appointed as Gatekeeper', 'Ezekiel Appointed as Israel''s Watchman']::text[], 'Ezekiel Appointed as Israel''s Watchman', 'Ezekiel was appointed a watchman responsible for warning the people.', 'Ezekiel 3:16-21; 33:1-9', '{"difficulty":"intermediate","case_title":"The Watchman of Israel","clues":["Evidence A — A prophet was appointed as a watchman for Israel.","Evidence B — He was told to warn the wicked and the righteous when danger was revealed.","Evidence C — The responsibility for warning was placed on the watchman."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-102"}'::jsonb),
('bible-detective-l21-c3', 'bible-detective', 21, 3, 'CASE FILE 103: The Prophet''s Wife as a Sign. Review the evidence and identify the biblical account.', ARRAY['Hosea''s Marriage Becomes a Sign', 'Jeremiah''s Unmarried Life', 'Ezekiel''s Wife Becomes a Sign', 'Isaiah''s Children Become Signs']::text[], 'Ezekiel''s Wife Becomes a Sign', 'Ezekiel''s loss and restrained mourning symbolised the people''s response to the temple''s destruction.', 'Ezekiel 24:15-27', '{"difficulty":"intermediate","case_title":"The Prophet''s Wife as a Sign","clues":["Evidence A — A prophet was told his wife would die suddenly.","Evidence B — He was instructed not to perform customary mourning rites.","Evidence C — His conduct became a sign to the exiles concerning the coming loss of the sanctuary."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-103"}'::jsonb),
('bible-detective-l21-c4', 'bible-detective', 21, 4, 'CASE FILE 104: The Four Horns and Craftsmen. Review the evidence and identify the biblical account.', ARRAY['Zechariah''s Four Horns and Four Craftsmen', 'Ezekiel''s Four Living Creatures', 'Amos'' Four Visions', 'Daniel''s Four Beasts']::text[], 'Zechariah''s Four Horns and Four Craftsmen', 'Zechariah''s vision showed four horns and four craftsmen who would cast them down.', 'Zechariah 1:18-21', '{"difficulty":"intermediate","case_title":"The Four Horns and Craftsmen","clues":["Evidence A — A prophet saw four horns that had scattered Judah, Israel and Jerusalem.","Evidence B — He then saw four craftsmen who came to terrify and cast down the horns.","Evidence C — The vision answered the image of nations that had lifted themselves against God''s people."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-104"}'::jsonb),
('bible-detective-l21-c5', 'bible-detective', 21, 5, 'CASE FILE 105: The Measuring Line over Jerusalem. Review the evidence and identify the biblical account.', ARRAY['Amos'' Plumb Line', 'Zechariah''s Measuring Line', 'Ezekiel''s Temple Measuring', 'Nehemiah''s Wall Inspection']::text[], 'Zechariah''s Measuring Line', 'The measuring line vision promised Jerusalem''s expansion and the LORD''s protection.', 'Zechariah 2:1-5', '{"difficulty":"intermediate","case_title":"The Measuring Line over Jerusalem","clues":["Evidence A — A prophet saw a man with a measuring line going to measure Jerusalem.","Evidence B — An angel announced that the city would be inhabited like unwalled villages.","Evidence C — The LORD promised to be a wall of fire around it."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-105"}'::jsonb),
('bible-detective-l22-c1', 'bible-detective', 22, 1, 'CASE FILE 106: The High Priest''s Filthy Garments. Review the evidence and identify the biblical account.', ARRAY['Isaiah''s Lips Cleansed', 'Joshua the High Priest Cleansed', 'Aaron''s Rod Buds', 'Ezra''s Garments Torn']::text[], 'Joshua the High Priest Cleansed', 'Joshua the high priest''s filthy garments were replaced, symbolising removal of guilt.', 'Zechariah 3:1-10', '{"difficulty":"intermediate","case_title":"The High Priest''s Filthy Garments","clues":["Evidence A — A high priest stood before the angel of the LORD while an accuser stood beside him.","Evidence B — His filthy garments were removed and clean clothes were given.","Evidence C — A stone with seven eyes was set before him as a sign of cleansing and restoration."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-106"}'::jsonb),
('bible-detective-l22-c2', 'bible-detective', 22, 2, 'CASE FILE 107: The Lampstand and Two Olive Trees. Review the evidence and identify the biblical account.', ARRAY['Moses'' Golden Candlestick', 'Zechariah''s Lampstand and Olive Trees', 'Ezekiel''s Wheels and Living Creatures', 'Elijah''s Altar and Two Servants']::text[], 'Zechariah''s Lampstand and Olive Trees', 'The lampstand vision encouraged Zerubbabel that God''s work would be accomplished by the Spirit.', 'Zechariah 4:1-14', '{"difficulty":"intermediate","case_title":"The Lampstand and Two Olive Trees","clues":["Evidence A — A prophet saw a golden lampstand with a bowl and seven lamps.","Evidence B — Two olive trees stood beside it, supplying oil.","Evidence C — The vision encouraged Zerubbabel that the work would be accomplished by God''s Spirit."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-107"}'::jsonb),
('bible-detective-l22-c3', 'bible-detective', 22, 3, 'CASE FILE 108: Elijah Flees to Horeb. Review the evidence and identify the biblical account.', ARRAY['Jonah Outside Nineveh', 'Elijah at Mount Horeb', 'Moses at Mount Sinai', 'Jeremiah at the Potter''s House']::text[], 'Elijah at Mount Horeb', 'Elijah fled Jezebel''s threat, was sustained by an angel and encountered the LORD at Horeb.', '1 Kings 19:1-18', '{"difficulty":"intermediate","case_title":"Elijah Flees to Horeb","clues":["After a threat from Jezebel, a prophet fled south and left his servant behind.","He sat beneath a broom tree and asked that his life might end; an angel provided food and water.","At Horeb, he encountered wind, earthquake and fire, then heard a low whisper."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l22-c3"}'::jsonb),
('bible-detective-l22-c4', 'bible-detective', 22, 4, 'CASE FILE 109: The Scroll on the Desert Road
Investigate the evidence and identify the biblical event or person.', ARRAY['Philip and the Ethiopian Official', 'Philip and the Samaritan Crowds', 'Peter and Cornelius', 'Paul and the Philippian Jailer']::text[], 'Philip and the Ethiopian Official', 'Philip met an Ethiopian official reading Isaiah, explained the passage about the suffering servant, and baptised him when they reached water.', 'Acts 8:26-40', '{"difficulty":"intermediate","case_title":"The Scroll on the Desert Road","clues":["An angel directed an evangelist to a road running south from Jerusalem toward Gaza.","A high-ranking official from a distant African kingdom was returning from worship and reading aloud from Isaiah.","The traveller asked for guidance, heard the good news about Jesus, and requested baptism when they came to water."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-22-4"}'::jsonb),
('bible-detective-l22-c5', 'bible-detective', 22, 5, 'CASE FILE 110: The Disagreement over John Mark
Investigate the evidence and identify the biblical event or person.', ARRAY['Paul and Peter Disagree at Antioch', 'Paul and Barnabas Part Ways', 'Paul and Silas Are Released from Prison', 'Barnabas Introduces Saul to the Apostles']::text[], 'Paul and Barnabas Part Ways', 'Paul and Barnabas disagreed about taking John Mark on another journey; Barnabas took Mark to Cyprus, while Paul travelled with Silas through Syria and Cilicia.', 'Acts 15:36-41', '{"difficulty":"intermediate","case_title":"The Disagreement over John Mark","clues":["Two missionaries proposed revisiting the communities where they had previously preached.","One wanted to take a younger companion who had left them during an earlier journey; the other refused to take him.","The disagreement became sharp, and the two leaders travelled separately with different companions."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-22-5"}'::jsonb),
('bible-detective-l23-c1', 'bible-detective', 23, 1, 'CASE FILE 111: Naboth''s Vineyard. Review the evidence and identify the biblical account.', ARRAY['Jezebel''s Contest with Elijah', 'Ahab''s Treaty with Ben-hadad', 'Naboth''s Vineyard Seized by Ahab', 'David Takes Uriah''s Wife']::text[], 'Naboth''s Vineyard Seized by Ahab', 'Jezebel arranged false testimony against Naboth so Ahab could take his vineyard; Elijah announced judgment.', '1 Kings 21:1-29', '{"difficulty":"intermediate","case_title":"Naboth''s Vineyard","clues":["A king wanted a vineyard beside his palace, but its owner refused to sell his ancestral inheritance.","The king''s wife arranged letters in his name and appointed a fast with false witnesses.","The owner was stoned, and a prophet announced judgment on the royal house."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l23-c1"}'::jsonb),
('bible-detective-l23-c2', 'bible-detective', 23, 2, 'CASE FILE 112: Paul Before King Agrippa. Review the evidence and identify the biblical account.', ARRAY['Barnabas'' Defence Before Felix', 'Stephen''s Defence Before Pilate', 'Peter''s Defence Before Herod', 'Paul''s Defence Before Agrippa']::text[], 'Paul''s Defence Before Agrippa', 'Paul defended himself before Agrippa and described his conversion and commission.', 'Acts 25:13-27; 26:1-32', '{"difficulty":"intermediate","case_title":"Paul Before King Agrippa","clues":["A Roman governor arranged a hearing for a prisoner after a royal visit.","The prisoner recounted his former persecution of Jesus'' followers and his encounter on the road to Damascus.","The king remarked that the prisoner was almost persuading him to become a Christian."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l23-c2"}'::jsonb),
('bible-detective-l23-c3', 'bible-detective', 23, 3, 'CASE FILE 113: The Man Seen Under the Fig Tree
Investigate the evidence and identify the biblical event or person.', ARRAY['Nicodemus Visits Jesus at Night', 'Nathanael Meets Jesus', 'Andrew Brings Simon to Jesus', 'The Samaritan Woman Meets Jesus']::text[], 'Nathanael Meets Jesus', 'Philip brought Nathanael to Jesus; Jesus said he had seen him under the fig tree before Philip called him, prompting Nathanael''s confession.', 'John 1:43-51', '{"difficulty":"intermediate","case_title":"The Man Seen Under the Fig Tree","clues":["A disciple invited a friend to meet the one he believed Moses and the prophets had written about.","The friend questioned whether anything good could come from the town where Jesus was raised.","Jesus described him as an Israelite without deceit and said he had seen him under a fig tree before the invitation."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-23-3"}'::jsonb),
('bible-detective-l23-c4', 'bible-detective', 23, 4, 'CASE FILE 114: The Archer at Megiddo
Investigate the evidence and identify the biblical event or person.', ARRAY['Ahab''s Death at Ramoth-gilead', 'Josiah''s Death at Megiddo', 'Saul''s Death on Mount Gilboa', 'Ahaziah''s Fall through the Lattice']::text[], 'Josiah''s Death at Megiddo', 'Josiah went out against Pharaoh Necho despite a warning that God had sent the Egyptian king; archers wounded him at Megiddo, and he died after being taken to Jerusalem.', '2 Chronicles 35:20-27', '{"difficulty":"intermediate","case_title":"The Archer at Megiddo","clues":["A reforming king went out to confront an Egyptian ruler travelling toward the Euphrates.","The Egyptian ruler sent a warning that he was not seeking war with Judah and that God had told him to hurry.","The king disguised himself but was struck by archers at Megiddo and later died; lamentations were made for him."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-23-4"}'::jsonb),
('bible-detective-l23-c5', 'bible-detective', 23, 5, 'CASE FILE 115: The Disguised Wound
Investigate the evidence and identify the biblical event or person.', ARRAY['The Prophet Rebukes Ahab after the Battle', 'Micaiah Warns Ahab before Ramoth-gilead', 'Elijah Confronts Ahab over Naboth', 'Nathan Rebukes David over Uriah']::text[], 'The Prophet Rebukes Ahab after the Battle', 'A prophet disguised himself with a headband and used a prisoner parable to announce judgment on Ahab for releasing Ben-hadad, whom God had devoted to destruction.', '1 Kings 20:35-43', '{"difficulty":"intermediate","case_title":"The Disguised Wound","clues":["A member of a prophetic group asked another man to strike him, but the man refused and was killed by a lion.","After another man struck him, the prophet covered his face with a bandage and waited for the king.","He told the king a story about a prisoner who escaped; the king''s own judgment then exposed his failure to carry out God''s command."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-23-5"}'::jsonb),
('bible-detective-l24-c1', 'bible-detective', 24, 1, 'CASE FILE 116: The Prophet Fed by Birds. Review the evidence and identify the biblical account.', ARRAY['Elijah Fed by Ravens', 'Daniel Fed by Lions', 'Jonah Fed by a Fish', 'Elisha Fed by Angels']::text[], 'Elijah Fed by Ravens', 'Ravens brought Elijah bread and meat while he stayed by the brook Cherith.', '1 Kings 17:1-7', '{"difficulty":"intermediate","case_title":"The Prophet Fed by Birds","clues":["Evidence A — A prophet announced a drought to a king.","Evidence B — He was told to hide beside a brook where ravens brought him bread and meat.","Evidence C — He drank from the brook until it dried up."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-116"}'::jsonb),
('bible-detective-l24-c2', 'bible-detective', 24, 2, 'CASE FILE 117: The Priest Who Could Not Speak
Investigate the evidence and identify the biblical event or person.', ARRAY['The Shepherds Hear the Birth Announcement', 'The Angel Appears to Mary', 'Simeon''s Blessing in the Temple', 'Zechariah''s Temple Vision']::text[], 'Zechariah''s Temple Vision', 'The angel Gabriel appeared to Zechariah while he served in the temple and announced the birth of John; Zechariah became mute after asking for a sign.', 'Luke 1:5-25', '{"difficulty":"intermediate","case_title":"The Priest Who Could Not Speak","clues":["An elderly priest from the division of Abijah was chosen by lot to offer incense in the sanctuary.","A heavenly messenger stood beside the altar and promised that the priest''s wife would bear a son who would prepare a people for the Lord.","The priest questioned how he could know this because he and his wife were old, and he was unable to speak until the promise was fulfilled."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-24-2"}'::jsonb),
('bible-detective-l24-c3', 'bible-detective', 24, 3, 'CASE FILE 118: The Shunammite''s Son. Review the evidence and identify the biblical account.', ARRAY['Elijah Raises the Widow''s Son', 'Peter Raises Tabitha', 'Elisha Raises the Shunammite''s Son', 'Jesus Raises Jairus'' Daughter']::text[], 'Elisha Raises the Shunammite''s Son', 'Elisha prayed for the Shunammite woman''s son and the child was restored to life.', '2 Kings 4:8-37', '{"difficulty":"intermediate","case_title":"The Shunammite''s Son","clues":["Evidence A — A wealthy woman prepared a small room for a travelling prophet.","Evidence B — Her son later died after complaining of a headache in the field.","Evidence C — The prophet prayed and stretched himself over the child before he revived."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-118"}'::jsonb),
('bible-detective-l24-c4', 'bible-detective', 24, 4, 'CASE FILE 119: The Singers Sent Ahead of the Army. Review the evidence and identify the biblical account.', ARRAY['Saul Sends Musicians Before the Philistines', 'Hezekiah Sends Priests Before Sennacherib', 'Jehoshaphat Sends Singers Before the Army', 'David Sends Singers Before Goliath']::text[], 'Jehoshaphat Sends Singers Before the Army', 'Jehoshaphat appointed singers to praise the LORD as the army went out; the enemy forces turned against one another.', '2 Chronicles 20:1-30', '{"difficulty":"intermediate","case_title":"The Singers Sent Ahead of the Army","clues":["Evidence A — A king faced a coalition of Moabites, Ammonites and others.","Evidence B — A prophet told the people not to fear because the battle belonged to God.","Evidence C — The king appointed singers to praise the LORD as they went out before the army."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-119"}'::jsonb),
('bible-detective-l24-c5', 'bible-detective', 24, 5, 'CASE FILE 120: The King Who Showed His Treasures. Review the evidence and identify the biblical account.', ARRAY['Manasseh Shows the Temple to Assyria', 'Josiah Shows the Law to Egypt', 'Uzziah Shows the Altar to Babylon', 'Hezekiah Shows His Treasures to Babylon']::text[], 'Hezekiah Shows His Treasures to Babylon', 'Hezekiah showed the Babylonian envoys his treasures; Isaiah foretold their removal to Babylon.', '2 Kings 20:12-19; Isaiah 39:1-8', '{"difficulty":"intermediate","case_title":"The King Who Showed His Treasures","clues":["Evidence A — Envoys from Babylon visited a king after hearing of his recovery.","Evidence B — The king showed them his treasures, armoury and everything in his house.","Evidence C — A prophet rebuked him and foretold that these treasures would be carried to Babylon."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-120"}'::jsonb),
('bible-detective-l25-c1', 'bible-detective', 25, 1, 'CASE FILE 121: The Shade That Withered
Investigate the evidence and identify the biblical event or person.', ARRAY['Jonah in the Great Fish', 'The Gourd of Elisha', 'Jonah and the Plant', 'The Repentance of Nineveh']::text[], 'Jonah and the Plant', 'Jonah was angry that Nineveh had been spared; God used a plant that grew and then withered to challenge the prophet''s concern for his own comfort over the people of the city.', 'Jonah 4:1-11', '{"difficulty":"intermediate","case_title":"The Shade That Withered","clues":["A prophet became angry after a foreign city repented and escaped the disaster he had announced.","He sat east of the city, where a plant grew overnight and shaded his head; the next day a worm damaged it.","When the heat and wind made him faint, God asked why he pitied the plant but not a city containing many people and animals."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-25-1"}'::jsonb),
('bible-detective-l25-c2', 'bible-detective', 25, 2, 'CASE FILE 122: Shimei Curses David. Review the evidence and identify the biblical account.', ARRAY['Shimei Curses and Seeks Pardon from David', 'Absalom Seeks Pardon from David', 'Joab Rebukes David', 'Ziba Accuses Mephibosheth']::text[], 'Shimei Curses and Seeks Pardon from David', 'Shimei cursed David during his flight and later sought pardon when David returned to Jerusalem.', '2 Samuel 16:5-14; 19:16-23', '{"difficulty":"intermediate","case_title":"Shimei Curses David","clues":["During David''s flight from Jerusalem, a man from Saul''s clan came out cursing him.","He threw stones at the king and his servants while calling David a man of blood.","After David returned, the man hurried to meet him and begged for mercy."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l25-c2"}'::jsonb),
('bible-detective-l25-c3', 'bible-detective', 25, 3, 'CASE FILE 123: The Prophet Who Saw the End in Fruit. Review the evidence and identify the biblical account.', ARRAY['Jeremiah''s Basket of Figs', 'Hosea''s Basket of Grapes', 'Amos'' Basket of Summer Fruit', 'Zechariah''s Ephah Vision']::text[], 'Amos'' Basket of Summer Fruit', 'The summer-fruit vision announced Israel''s end and condemned injustice.', 'Amos 8:1-6', '{"difficulty":"intermediate","case_title":"The Prophet Who Saw the End in Fruit","clues":["Evidence A — A prophet was shown a basket of ripe summer fruit.","Evidence B — The vision used a wordplay to announce the end of the northern kingdom''s patience.","Evidence C — The message condemned dishonest scales and exploitation of the poor."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-123"}'::jsonb),
('bible-detective-l25-c4', 'bible-detective', 25, 4, 'CASE FILE 124: Hezekiah''s Prayer over the Assyrian Letter. Review the evidence and identify the biblical account.', ARRAY['David Prays over the Census', 'Josiah Reads the Covenant', 'Hezekiah Prays over Sennacherib''s Letter', 'Jehoshaphat Prays Before Battle']::text[], 'Hezekiah Prays over Sennacherib''s Letter', 'Hezekiah spread the Assyrian letter before God and prayed; Isaiah announced that Jerusalem would be delivered.', '2 Kings 19:14-37; Isaiah 37:14-38', '{"difficulty":"intermediate","case_title":"Hezekiah''s Prayer over the Assyrian Letter","clues":["An Assyrian ruler sent a threatening letter to Jerusalem.","Judah''s king took the letter into the temple and spread it before the LORD.","A prophet announced deliverance, and the Assyrian army suffered a sudden defeat."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l25-c4"}'::jsonb),
('bible-detective-l25-c5', 'bible-detective', 25, 5, 'CASE FILE 125: Josiah''s Passover. Review the evidence and identify the biblical account.', ARRAY['Solomon Dedicates the Temple', 'Josiah Keeps the Great Passover', 'Hezekiah Keeps the Passover', 'Ezra Restores the Feast of Booths']::text[], 'Josiah Keeps the Great Passover', 'Josiah organised an extensive Passover observance in Jerusalem after the law was rediscovered.', '2 Chronicles 35:1-19', '{"difficulty":"intermediate","case_title":"Josiah''s Passover","clues":["A king ordered the Passover to be observed in Jerusalem after the book of the law had been found.","Priests and Levites were organised to serve and prepare the offerings.","The writer says no Passover like it had been kept in Israel since the days of Samuel."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-revised-bible-detective-l25-c5"}'::jsonb),
('bible-detective-l26-c1', 'bible-detective', 26, 1, 'CASE FILE 126: Hagar and Ishmael Sent Away. Examine the evidence and identify the biblical account.', ARRAY['Sarah and Isaac Sent to Gerar', 'Hagar and Ishmael Sent into the Wilderness', 'Leah and Joseph Sent to Egypt', 'Rebekah and Jacob Sent to Haran']::text[], 'Hagar and Ishmael Sent into the Wilderness', 'God heard Ishmael, showed Hagar a well and promised to make the boy a great nation.', 'Genesis 21:8-21', '{"difficulty":"intermediate","case_title":"Hagar and Ishmael Sent Away","clues":["A household conflict intensified after a son was weaned.","A servant woman and her child were sent into the wilderness with bread and water.","God heard the boy''s cry and showed his mother a well."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-126"}'::jsonb),
('bible-detective-l26-c2', 'bible-detective', 26, 2, 'CASE FILE 127: Moses Intercedes after the Calf. Examine the evidence and identify the biblical account.', ARRAY['Aaron Intercedes after Nadab and Abihu', 'Moses Intercedes after the Golden Calf', 'Samuel Intercedes after Saul', 'Joshua Intercedes after Achan']::text[], 'Moses Intercedes after the Golden Calf', 'Moses pleaded for Israel after the golden calf incident and asked God to spare the people.', 'Exodus 32:7-35', '{"difficulty":"intermediate","case_title":"Moses Intercedes after the Calf","clues":["A leader descended from a mountain carrying two stone tablets.","He found the people worshipping a metal calf and threw down the tablets.","He later pleaded with God not to destroy the people and offered to be blotted out of the book."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-127"}'::jsonb),
('bible-detective-l26-c3', 'bible-detective', 26, 3, 'CASE FILE 128: Miriam Challenges Moses. Examine the evidence and identify the biblical account.', ARRAY['Zipporah Is Disciplined at the Inn', 'Deborah Is Disciplined by Barak', 'Miriam Is Disciplined for Speaking against Moses', 'Huldah Is Disciplined by Josiah']::text[], 'Miriam Is Disciplined for Speaking against Moses', 'Miriam was struck with a skin disease after speaking against Moses and was shut outside the camp for seven days.', 'Numbers 12:1-15', '{"difficulty":"intermediate","case_title":"Miriam Challenges Moses","clues":["Two siblings spoke against their brother because of his marriage and leadership.","The LORD summoned the three to the tent of meeting.","One sibling became white with a skin disease and was shut outside the camp for seven days."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-128"}'::jsonb),
('bible-detective-l26-c4', 'bible-detective', 26, 4, 'CASE FILE 129: Hezekiah Reopens the Temple. Examine the evidence and identify the biblical account.', ARRAY['Josiah Repairs the Temple', 'Ezra Rebuilds the Temple', 'Joash Collects Temple Donations', 'Hezekiah Restores Temple Worship']::text[], 'Hezekiah Restores Temple Worship', 'Hezekiah reopened the temple, consecrated the priests and Levites, and restored sacrifices and worship.', '2 Chronicles 29:3-36', '{"difficulty":"intermediate","case_title":"Hezekiah Reopens the Temple","clues":["Evidence A — Early in his reign, a king opened the doors of the LORD''s house and repaired them.","Evidence B — Priests and Levites were summoned to consecrate themselves and cleanse the sanctuary.","Evidence C — Sacrifices and songs of praise marked the restoration of temple worship."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-129-hezekiah-temple"}'::jsonb),
('bible-detective-l26-c5', 'bible-detective', 26, 5, 'CASE FILE 130: Rahab''s Scarlet Cord. Examine the evidence and identify the biblical account.', ARRAY['Jael Hides Sisera', 'Rahab Hides the Spies', 'Abigail Hides Nabal', 'Michal Hides David']::text[], 'Rahab Hides the Spies', 'Rahab hid the spies and marked her house with a scarlet cord; her family was spared.', 'Joshua 2:1-21; 6:22-25', '{"difficulty":"intermediate","case_title":"Rahab''s Scarlet Cord","clues":["Two spies entered a fortified city and were hidden on a roof beneath stalks of flax.","A woman negotiated protection for her family in exchange for keeping the mission secret.","A scarlet cord in the window marked the house when the city fell."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-130"}'::jsonb),
('bible-detective-l27-c1', 'bible-detective', 27, 1, 'CASE FILE 131: Samson''s Riddle at the Feast. Examine the evidence and identify the biblical account.', ARRAY['Samson''s Wedding Riddle', 'Gideon''s Fleece Sign', 'Daniel''s Writing on the Wall', 'Solomon''s Two Mothers']::text[], 'Samson''s Wedding Riddle', 'Samson''s riddle concerned honey from the lion; his bride obtained the answer through pressure from the guests.', 'Judges 14:5-20', '{"difficulty":"intermediate","case_title":"Samson''s Riddle at the Feast","clues":["A judge posed a riddle at a wedding feast after finding honey in a lion''s carcass.","His companions pressured his bride to obtain the answer.","He later paid the wager by killing men at Ashkelon and taking their garments."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-131"}'::jsonb),
('bible-detective-l27-c2', 'bible-detective', 27, 2, 'CASE FILE 132: Jephthah''s Daughter. Examine the evidence and identify the biblical account.', ARRAY['Jephthah''s Vow and His Daughter', 'Gideon''s Fleece and Vow', 'Samson''s Wedding Feast', 'Saul''s Oath against Jonathan']::text[], 'Jephthah''s Vow and His Daughter', 'Jephthah made a rash vow and his daughter came out first to meet him after victory.', 'Judges 11:29-40', '{"difficulty":"intermediate","case_title":"Jephthah''s Daughter","clues":["A judge made a vow before going to battle against the Ammonites.","His only child came out first to greet him after victory.","She requested two months to mourn her virginity in the mountains."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-132"}'::jsonb),
('bible-detective-l27-c3', 'bible-detective', 27, 3, 'CASE FILE 133: Ruth at the City Gate. Examine the evidence and identify the biblical account.', ARRAY['Abraham Buys Machpelah', 'Boaz Redeems Ruth at the Gate', 'David Buys Araunah''s Threshing Floor', 'Jeremiah Buys Hanamel''s Field']::text[], 'Boaz Redeems Ruth at the Gate', 'Boaz completed the redemption at the city gate after the nearer relative declined and gave his sandal.', 'Ruth 4:1-12', '{"difficulty":"intermediate","case_title":"Ruth at the City Gate","clues":["A relative of a deceased husband approached the nearer family redeemer.","The nearer redeemer declined after learning that the transaction involved the widow''s inheritance.","The sandal exchange confirmed the redemption before the elders."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-133"}'::jsonb),
('bible-detective-l27-c4', 'bible-detective', 27, 4, 'CASE FILE 134: Saul Spares Agag. Examine the evidence and identify the biblical account.', ARRAY['David Spares Saul', 'Jehu Spares the Sons of Ahab', 'Ahab Spares Ben-hadad', 'Saul Spares Agag and Is Rejected']::text[], 'Saul Spares Agag and Is Rejected', 'Saul spared Agag and the best livestock; Samuel rebuked him for disobeying God''s command.', '1 Samuel 15:1-35', '{"difficulty":"intermediate","case_title":"Saul Spares Agag","clues":["A king received a command concerning the Amalekites and their possessions.","He spared the enemy king and kept the best livestock, claiming some were for sacrifice.","A prophet announced that obedience mattered more than sacrifice and rejected the king."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-134"}'::jsonb),
('bible-detective-l27-c5', 'bible-detective', 27, 5, 'CASE FILE 135: David Dances before the Ark. Examine the evidence and identify the biblical account.', ARRAY['Solomon Dances before the Altar', 'David Dances before the Ark', 'Michal Dances before Saul', 'Miriam Dances before Pharaoh']::text[], 'David Dances before the Ark', 'David celebrated before the LORD as the ark was brought to Jerusalem; Michal despised him.', '2 Samuel 6:12-23; 1 Chronicles 15:25-29', '{"difficulty":"intermediate","case_title":"David Dances before the Ark","clues":["A sacred chest was brought toward Jerusalem with music and celebration.","A king wore a linen ephod and danced with all his might.","His wife despised him for the public display, and he answered that he was celebrating before the LORD."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-135"}'::jsonb),
('bible-detective-l28-c1', 'bible-detective', 28, 1, 'CASE FILE 136: The Glory Fills Solomon''s Temple. Examine the evidence and identify the biblical account.', ARRAY['Josiah Repairs the Temple', 'Hezekiah Cleanses the Temple', 'Zerubbabel Lays the Temple Foundation', 'Solomon Dedicates the Temple']::text[], 'Solomon Dedicates the Temple', 'The glory cloud filled Solomon''s temple when the ark was brought into the Most Holy Place.', '1 Kings 8:1-66; 2 Chronicles 5:2-14', '{"difficulty":"intermediate","case_title":"The Glory Fills Solomon''s Temple","clues":["Priests carried the ark into the inner sanctuary of a newly completed house.","A cloud filled the building so that the priests could not continue ministering.","The king blessed the assembly and prayed before the altar."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-136"}'::jsonb),
('bible-detective-l28-c2', 'bible-detective', 28, 2, 'CASE FILE 137: Fire from Heaven against Ahaziah''s Captains. Examine the evidence and identify the biblical account.', ARRAY['Elisha and the Syrian Army', 'Samuel and Saul''s Messengers', 'Moses and Pharaoh''s Captains', 'Elijah and the Captains of Ahaziah']::text[], 'Elijah and the Captains of Ahaziah', 'Fire from heaven consumed the first two captains and their companies; the third approached Elijah humbly.', '2 Kings 1:1-17', '{"difficulty":"intermediate","case_title":"Fire from Heaven against Ahaziah''s Captains","clues":["A sick king sent military captains to summon a prophet.","The first two captains and their companies were consumed by fire from heaven.","A third captain approached humbly and pleaded for his life and his men."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-137"}'::jsonb),
('bible-detective-l28-c3', 'bible-detective', 28, 3, 'CASE FILE 138: The Man Who Washed at Siloam
Investigate the evidence and identify the biblical event or person.', ARRAY['Jesus Heals Bartimaeus near Jericho', 'Jesus Heals the Man Born Blind', 'Peter Heals Aeneas at Lydda', 'Jesus Opens the Ears of a Deaf Man']::text[], 'Jesus Heals the Man Born Blind', 'Jesus made mud, placed it on the eyes of a man born blind and sent him to wash at Siloam; the healing led to questioning by the Pharisees.', 'John 9:1-41', '{"difficulty":"intermediate","case_title":"The Man Who Washed at Siloam","clues":["The disciples asked whether a man''s blindness from birth was caused by his own sin or his parents'' sin.","Jesus made mud, placed it on the man''s eyes and sent him to wash at a pool whose name means ''Sent''.","The healed man was questioned by religious leaders, while his parents confirmed that he had been born blind."],"investigation_type":"multi_evidence_case","fact_key":"detective-rebuilt-28-3"}'::jsonb),
('bible-detective-l28-c4', 'bible-detective', 28, 4, 'CASE FILE 139: Jonah''s Great Fish. Examine the evidence and identify the biblical account.', ARRAY['Daniel Swallowed by the Lions', 'Peter Swallowed by the Sea', 'Jonah Swallowed by the Great Fish', 'Paul Swallowed by the Storm']::text[], 'Jonah Swallowed by the Great Fish', 'Jonah was swallowed by a great fish after being thrown into the sea and prayed to God from within it.', 'Jonah 1:1-17; 2:1-10', '{"difficulty":"intermediate","case_title":"Jonah''s Great Fish","clues":["A prophet fled by ship after receiving an instruction to preach to a foreign city.","A violent storm led the sailors to cast lots and identify him as the cause.","He was thrown into the sea, swallowed by a great fish and prayed from its belly."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-139"}'::jsonb),
('bible-detective-l28-c5', 'bible-detective', 28, 5, 'CASE FILE 140: Daniel''s Seventy Weeks. Examine the evidence and identify the biblical account.', ARRAY['Ezekiel''s Vision of the Dry Bones', 'Daniel''s Vision of the Seventy Weeks', 'Jeremiah''s Vision of the Basket of Figs', 'Zechariah''s Vision of the Flying Scroll']::text[], 'Daniel''s Vision of the Seventy Weeks', 'Gabriel explained Daniel''s prayer through the prophecy of seventy weeks concerning Jerusalem and its people.', 'Daniel 9:1-27', '{"difficulty":"intermediate","case_title":"Daniel''s Seventy Weeks","clues":["A prophet studied Jeremiah''s writings about Jerusalem''s desolation.","An angelic messenger explained a period of seventy sevens concerning the holy city and its people.","The vision included an anointed one, a cut-off figure and the desolation of the sanctuary."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-140"}'::jsonb),
('bible-detective-l29-c1', 'bible-detective', 29, 1, 'CASE FILE 141: The Three Hebrews Refuse the King''s Food. Examine the evidence and identify the biblical account.', ARRAY['Daniel''s Food Test in Babylon', 'Ezra''s Food Test at Ahava', 'Moses'' Food Test in Midian', 'Joseph''s Food Test in Egypt']::text[], 'Daniel''s Food Test in Babylon', 'Daniel and his companions requested vegetables and water and were found healthier after ten days.', 'Daniel 1:3-20', '{"difficulty":"intermediate","case_title":"The Three Hebrews Refuse the King''s Food","clues":["Four Judean youths were selected for training in a foreign royal court.","One resolved not to defile himself with the king''s food and wine.","After a ten-day test of vegetables and water, the youths appeared healthier."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-141"}'::jsonb),
('bible-detective-l29-c2', 'bible-detective', 29, 2, 'CASE FILE 142: Peter''s Escape from Herod''s Prison. Examine the evidence and identify the biblical account.', ARRAY['Paul Freed from Caesarea by an Angel', 'Peter Freed from Prison by an Angel', 'James Freed from Herod by an Angel', 'John Freed from Patmos by an Angel']::text[], 'Peter Freed from Prison by an Angel', 'An angel led Peter out of Herod''s prison while the church prayed for him.', 'Acts 12:1-19', '{"difficulty":"intermediate","case_title":"Peter''s Escape from Herod''s Prison","clues":["A ruler imprisoned a leading apostle during the days of unleavened bread.","The prisoner slept between two soldiers, bound with chains, while guards watched the door.","An angel led him past the guards and through an iron gate that opened by itself."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-142"}'::jsonb),
('bible-detective-l29-c3', 'bible-detective', 29, 3, 'CASE FILE 143: Cornelius'' Vision. Examine the evidence and identify the biblical account.', ARRAY['John and the Elders'' Vision', 'Paul and Ananias'' Visions', 'Cornelius and Peter''s Visions', 'Philip and the Ethiopian''s Vision']::text[], 'Cornelius and Peter''s Visions', 'Cornelius saw an angel, while Peter saw a vision that prepared him to visit the Gentile household.', 'Acts 10:1-48', '{"difficulty":"intermediate","case_title":"Cornelius'' Vision","clues":["A Roman centurion in Caesarea prayed regularly and gave generously to the needy.","An angel instructed him to send for a man staying by the sea in Joppa.","The visitor''s arrival followed a rooftop vision that taught him not to call unclean what God had cleansed."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-143"}'::jsonb),
('bible-detective-l29-c4', 'bible-detective', 29, 4, 'CASE FILE 144: Stephen''s Final Vision. Examine the evidence and identify the biblical account.', ARRAY['Paul''s Stoning at Lystra', 'James'' Execution', 'Stephen''s Martyrdom', 'Peter''s Imprisonment']::text[], 'Stephen''s Martyrdom', 'Stephen saw the Son of Man at God''s right hand before he was stoned outside Jerusalem.', 'Acts 7:54-60', '{"difficulty":"intermediate","case_title":"Stephen''s Final Vision","clues":["A witness was accused before the council and recounted Israel''s history.","He declared that he saw the heavens opened and the Son of Man standing at God''s right hand.","The crowd dragged him outside the city and stoned him while he prayed for his killers."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-144"}'::jsonb),
('bible-detective-l29-c5', 'bible-detective', 29, 5, 'CASE FILE 145: Lydia''s Open Heart. Examine the evidence and identify the biblical account.', ARRAY['Priscilla Believes at Ephesus', 'Damaris Believes at Athens', 'Phoebe Believes at Cenchreae', 'Lydia Believes at Philippi']::text[], 'Lydia Believes at Philippi', 'The Lord opened Lydia''s heart to Paul''s message; she and her household were baptised.', 'Acts 16:11-15', '{"difficulty":"intermediate","case_title":"Lydia''s Open Heart","clues":["A group of missionaries met women praying beside a river outside a Macedonian city.","A seller of purple cloth listened to the message.","The Lord opened her heart, and she and her household were baptised; she offered the missionaries lodging."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-145"}'::jsonb),
('bible-detective-l30-c1', 'bible-detective', 30, 1, 'CASE FILE 146: Apollos Corrected in Ephesus. Examine the evidence and identify the biblical account.', ARRAY['Barnabas Instructs Mark', 'Paul Instructs Timothy', 'Peter Instructs Cornelius', 'Priscilla and Aquila Instruct Apollos']::text[], 'Priscilla and Aquila Instruct Apollos', 'Priscilla and Aquila privately explained God''s way more accurately to Apollos.', 'Acts 18:24-28', '{"difficulty":"intermediate","case_title":"Apollos Corrected in Ephesus","clues":["A learned speaker from Alexandria taught accurately about Jesus but knew only John''s baptism.","A married couple heard him speak boldly in a synagogue.","They took him aside and explained the way of God more accurately."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-146"}'::jsonb),
('bible-detective-l30-c2', 'bible-detective', 30, 2, 'CASE FILE 147: The Sudden Death of Ananias and Sapphira. Examine the evidence and identify the biblical account.', ARRAY['Aquila and Priscilla Hide Their Money', 'Felix and Drusilla Conceal a Gift', 'Ananias and Sapphira Lie to the Holy Spirit', 'Herod and Herodias Steal an Offering']::text[], 'Ananias and Sapphira Lie to the Holy Spirit', 'Ananias and Sapphira lied about the proceeds of their land sale and died after being confronted.', 'Acts 5:1-11', '{"difficulty":"intermediate","case_title":"The Sudden Death of Ananias and Sapphira","clues":["A couple sold property and brought only part of the proceeds to the apostles.","The husband represented the gift as though it were the full amount.","His wife repeated the deception hours later and also fell dead."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-147"}'::jsonb),
('bible-detective-l30-c3', 'bible-detective', 30, 3, 'CASE FILE 148: John''s Vision on Patmos. Examine the evidence and identify the biblical account.', ARRAY['Ezekiel''s Vision by the Chebar', 'John''s Vision of the Risen Christ', 'Isaiah''s Vision in the Temple', 'Daniel''s Vision of the Ancient of Days']::text[], 'John''s Vision of the Risen Christ', 'John saw the risen Christ among seven golden lampstands while exiled on Patmos.', 'Revelation 1:9-20', '{"difficulty":"intermediate","case_title":"John''s Vision on Patmos","clues":["An apostle was exiled to an island because of the word of God and testimony of Jesus.","He heard a loud voice like a trumpet and saw seven golden lampstands.","A figure like the Son of Man stood among the lampstands and held seven stars."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-148"}'::jsonb),
('bible-detective-l30-c4', 'bible-detective', 30, 4, 'CASE FILE 149: Paul Escapes Damascus in a Basket. Examine the evidence and identify the biblical account.', ARRAY['Peter Escapes Jerusalem in a Basket', 'Paul Escapes Damascus in a Basket', 'Barnabas Escapes Cyprus in a Basket', 'Silas Escapes Philippi in a Basket']::text[], 'Paul Escapes Damascus in a Basket', 'Paul''s disciples lowered him in a basket through an opening in the Damascus wall to escape the governor.', 'Acts 9:19-25; 2 Corinthians 11:32-33', '{"difficulty":"intermediate","case_title":"Paul Escapes Damascus in a Basket","clues":["A city governor guarded the gates to arrest a newly converted preacher.","His followers lowered him through an opening in the city wall in a basket.","The escape came after opponents plotted to kill him."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-149"}'::jsonb),
('bible-detective-l30-c5', 'bible-detective', 30, 5, 'CASE FILE 150: The Prophet''s Message to Nineveh. Examine the evidence and identify the biblical account.', ARRAY['Babylon Repents at Daniel''s Warning', 'Nineveh Repents at Jonah''s Warning', 'Jericho Repents at Joshua''s Warning', 'Sodom Repents at Lot''s Warning']::text[], 'Nineveh Repents at Jonah''s Warning', 'Nineveh''s people and king repented after Jonah announced judgment, and God relented from the disaster.', 'Jonah 3:1-10', '{"difficulty":"intermediate","case_title":"The Prophet''s Message to Nineveh","clues":["A reluctant messenger finally entered a great foreign city.","He announced that the city would be overthrown in forty days.","The king removed his robe, covered himself with sackcloth and called the people to fast."],"investigation_type":"multi_evidence_case","fact_key":"detective-expert-150"}'::jsonb)
