('old-vs-new-testament-l1-c1', 'old-vs-new-testament', 1, 1, 'Which Testament contains the passage Genesis 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'Old Testament', 'Genesis 1:1 is in Genesis, which belongs to the Law section of the Old Testament.', 'Genesis 1:1', '{"difficulty":"beginner","fact_key":"testament-genesis-1-1","curated":true,"book_name":"Genesis","testament":"Old Testament"}'::jsonb),
('old-vs-new-testament-l1-c2', 'old-vs-new-testament', 1, 2, 'Which Testament contains the passage Matthew 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'New Testament', 'Matthew 1:1 is in Matthew, which belongs to the Gospels section of the New Testament.', 'Matthew 1:1', '{"difficulty":"beginner","fact_key":"testament-matthew-1-1","curated":true,"book_name":"Matthew","testament":"New Testament"}'::jsonb),
('old-vs-new-testament-l1-c3', 'old-vs-new-testament', 1, 3, 'Which Testament contains the passage Exodus 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'Old Testament', 'Exodus 1:1 is in Exodus, which belongs to the Law section of the Old Testament.', 'Exodus 1:1', '{"difficulty":"beginner","fact_key":"testament-exodus-1-1","curated":true,"book_name":"Exodus","testament":"Old Testament"}'::jsonb),
('old-vs-new-testament-l1-c4', 'old-vs-new-testament', 1, 4, 'Which Testament contains the passage Mark 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'New Testament', 'Mark 1:1 is in Mark, which belongs to the Gospels section of the New Testament.', 'Mark 1:1', '{"difficulty":"beginner","fact_key":"testament-mark-1-1","curated":true,"book_name":"Mark","testament":"New Testament"}'::jsonb),
('old-vs-new-testament-l1-c5', 'old-vs-new-testament', 1, 5, 'Which Testament contains the passage Leviticus 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'Old Testament', 'Leviticus 1:1 is in Leviticus, which belongs to the Law section of the Old Testament.', 'Leviticus 1:1', '{"difficulty":"beginner","fact_key":"testament-leviticus-1-1","curated":true,"book_name":"Leviticus","testament":"Old Testament"}'::jsonb),
('old-vs-new-testament-l2-c1', 'old-vs-new-testament', 2, 1, 'Which Testament contains the passage Luke 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'New Testament', 'Luke 1:1 is in Luke, which belongs to the Gospels section of the New Testament.', 'Luke 1:1', '{"difficulty":"beginner","fact_key":"testament-luke-1-1","curated":true,"book_name":"Luke","testament":"New Testament"}'::jsonb),
('old-vs-new-testament-l2-c2', 'old-vs-new-testament', 2, 2, 'Which Testament contains the passage Numbers 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'Old Testament', 'Numbers 1:1 is in Numbers, which belongs to the Law section of the Old Testament.', 'Numbers 1:1', '{"difficulty":"beginner","fact_key":"testament-numbers-1-1","curated":true,"book_name":"Numbers","testament":"Old Testament"}'::jsonb),
('old-vs-new-testament-l2-c3', 'old-vs-new-testament', 2, 3, 'Which Testament contains the passage John 1:1?', ARRAY['Old Testament', 'New Testament']::text[], 'New Testament', 'John 1:1 is in John, which belongs to the Gospels section of the New Testament.', 'John 1:1', '{"difficulty":"beginner","fact_key":"testament-john-1-1","curated":true,"book_name":"John","testament":"New Testament"}'::jsonb),
